"""Checkpoint/trace audit and isolated learner ablation.

Never changes production source or overwrites official training checkpoints.
"""
import argparse
import json
import sys
from pathlib import Path

ROOT = Path(__file__).resolve().parents[3]
OUT = Path(__file__).resolve().parent
sys.path.insert(0, str(ROOT))
sys.path.insert(0, str(ROOT / 'UniFP'))
CHECKPOINTS = {
    8000: 'ranger-unifp-v3-original-to8000/model_iter_008000.pt',
    9000: 'ranger-unifp-v3-original-force-to9000/model_iter_009000.pt',
    9500: 'ranger-unifp-v3-original-force-to10000/model_iter_009500.pt',
    10000: 'ranger-unifp-v3-original-force-to10000-resume9500/model_iter_010000.pt',
}


def offline():
    import numpy as np
    import torch
    torch.set_num_threads(2)
    tape_path = ROOT / 'logs/ranger-unifp-v3-original-force-to9000/force-diagnostics/force_schedule.json'
    tape = json.loads(tape_path.read_text())
    tf = np.asarray([x['external_world_n'] for x in tape['samples']])
    result = {'traces': {}, 'checkpoints': {}, 'scope': 'diagnostics, no new acceptance thresholds'}
    previous = None
    for it, path in CHECKPOINTS.items():
        ck = torch.load(ROOT / 'logs' / path, map_location='cpu', weights_only=True)
        state = ck['model_state_dict']
        modules = {}
        for name in ('adaptation_encoder_module', 'adaptation_decoder_module', 'actor_body', 'critic_body'):
            keys = [k for k in state if k.startswith(name)]
            modules[name] = {
                'all_finite': all(bool(torch.isfinite(state[k]).all()) for k in keys),
                'delta_l2_from_previous': float(sum((state[k]-previous[k]).double().square().sum() for k in keys).sqrt()) if previous else None,
            }
        optim = ck['adaptation_optimizer_state_dict']
        ids = optim['param_groups'][0]['params']
        params = [k for k in state if k != 'std']
        # Optimizer ids follow named_parameters: std first, then modules.
        param_names = ['std'] + params
        force_row_state = optim['state'][ids[param_names.index('adaptation_decoder_module.4.weight')]]
        result['checkpoints'][it] = {'iterations': ck['iterations'], 'global_policy_steps': ck['global_policy_steps'],
            'modules': modules, 'supervision_lr': optim['param_groups'][0]['lr'],
            'decoder_optimizer_step': float(force_row_state['step']),
            'force_output_exp_avg_norm': float(force_row_state['exp_avg'][6:9].norm()),
            'force_output_exp_avg_sq_sum': float(force_row_state['exp_avg_sq'][6:9].sum())}
        previous = state
        p = ROOT / f'logs/ranger-unifp-v3-original-force-to10000-resume9500/fixed_goal_zero_base_command/iter_{it}.trace.json'
        rows = json.loads(p.read_text())['samples']
        def a(key): return np.asarray([r['pre_action'][key] for r in rows], dtype=float)
        f, fw, pred = a('force_truth_yaw_n'), a('force_truth_world_n'), a('force_estimate_yaw_n')
        quat = a('base_yaw_quaternion_wxyz')
        yaw = 2*np.arctan2(quat[..., 3], quat[..., 0])
        rotated = np.stack((np.cos(yaw)*f[...,0]-np.sin(yaw)*f[...,1], np.sin(yaw)*f[...,0]+np.cos(yaw)*f[...,1], f[...,2]), -1)
        resets = np.asarray([r['done'] for r in rows], bool)
        expected = np.zeros_like(fw); expected[1:] = tf[:-1]; expected[1:][resets[:-1]] = 0
        goal, ee, target = a('goal_position_world_m'), a('ee_position_world_m'), a('force_target_world_m')
        cmdw = a('force_command_world_n')
        align = float(np.abs(expected-fw).max())
        rotation = float(np.abs(rotated-fw).max())
        offset = float(np.abs(target-goal-(fw+cmdw)/200).max())
        assert align < 1e-4 and rotation < 1e-4 and offset < 1e-5, (it, align, rotation, offset)
        active = np.linalg.norm(f[:,1], axis=-1) > 1
        world_axis = np.argmax(np.abs(fw[:,1]), axis=-1)
        gains = {}
        for ax in range(3):
            mask = active & (world_axis == ax) & (np.abs(fw[:,1,ax]) >= 4)
            # Fit in world coordinates because external tape axes are world.
            pw = np.stack((np.cos(yaw[:,1])*pred[:,1,0]-np.sin(yaw[:,1])*pred[:,1,1], np.sin(yaw[:,1])*pred[:,1,0]+np.cos(yaw[:,1])*pred[:,1,1], pred[:,1,2]), -1)
            gains['xyz'[ax]] = np.polyfit(fw[mask,1,ax], pw[mask,ax], 1).tolist()
        result['traces'][it] = {'force_label_alignment_max_n': align, 'yaw_roundtrip_max_n': rotation,
            'force_target_identity_max_m': offset,
            'active_vector_error_n': float(np.linalg.norm(pred[active,1]-f[active,1], axis=-1).mean()),
            'zero_predictor_active_vector_error_n': float(np.linalg.norm(f[active,1], axis=-1).mean()),
            'world_axis_fit_slope_intercept': gains,
            'no_force_mean_vector_n': pred[:,0].mean(0).tolist(),
            'no_force_mean_norm_n': float(np.linalg.norm(pred[:,0],axis=-1).mean())}
        trace_result = result['traces'][it]
        trace_result['error_not_better_than_zero_predictor'] = (
            trace_result['active_vector_error_n'] >= trace_result['zero_predictor_active_vector_error_n'])
    (OUT / 'offline.json').write_text(json.dumps(result, indent=2)+'\n')
    print(json.dumps(result, indent=2))


def live(args):
    from isaaclab.app import AppLauncher
    app = AppLauncher(args).app
    import torch
    from isaaclab.utils.math import quat_apply_inverse, yaw_quat
    from ranger_unifp_vec_env import RangerUniFPVecEnv
    from legged_gym.b2_gym_learn.ppo_cse_pf.actor_critic import ActorCritic
    from legged_gym.b2_gym_learn.ppo_cse_pf.ppo import PPO
    env = RangerUniFPVecEnv(num_envs=16, device=args.device, domain_randomization=True,
        observation_noise=True, command_sampling=True, random_goals=True,
        force_curriculum=True, push_robots=True, curriculum_start_step=192001, seed=0)
    try:
        ck = torch.load(ROOT/'logs'/CHECKPOINTS[10000], map_location=env.device, weights_only=True)
        env.global_policy_steps = ck['global_policy_steps']
        model = ActorCritic(env.num_obs, env.num_privileged_obs, env.num_pred_obs, env.num_single_obs,
            env.num_actions, actor_hidden_dims=[512,256,128], critic_hidden_dims=[512,256,128]).to(env.device)
        model.load_state_dict(ck['model_state_dict'])
        algo = PPO(model, device=env.device, entropy_coef=.01, num_learning_epochs=5,
            num_mini_batches=4, schedule='adaptive', desired_kl=.01, gamma=.99, lam=.95)
        algo.optimizer.load_state_dict(ck['optimizer_state_dict'])
        algo.adaptation_module_optimizer.load_state_dict(ck['adaptation_optimizer_state_dict'])
        algo.learning_rate = ck['learning_rate']
        algo.init_storage(16,24,[env.num_obs],[env.num_privileged_obs],[env.num_pred_obs],[env.num_actions])
        last_force = {}
        setter = env.robot.set_external_force_and_torque
        def capture(**kw):
            last_force.update(force=kw['forces'][:,0].clone(), body_ids=kw['body_ids'], is_global=kw['is_global'])
            return setter(**kw)
        env.robot.set_external_force_and_torque = capture
        obs = env.get_observations()
        xs, ys = [], []
        label_error = ownership_error = storage_error = 0.
        for step in range(504):
            previous_obs = {k:v.clone() for k,v in obs.items()}
            with torch.no_grad():
                if step >= 480:
                    act = algo.act(obs['obs'], obs['privileged_obs'], obs['obs_pred'])
                else:
                    act = model.act(obs['obs'])
                next_obs,reward,done,info = env.step(act)
                if step >= 480:
                    algo.process_env_step(reward,done,info)
                    j = step - 480
                    storage_error = max(storage_error,
                        float((algo.storage.observations[j]-previous_obs['obs']).abs().max()),
                        float((algo.storage.observation_preds[j]-previous_obs['obs_pred']).abs().max()))
            expected = quat_apply_inverse(yaw_quat(env.robot.data.root_quat_w),last_force['force'])*.01
            expected[done] = 0
            label_error = max(label_error,float((next_obs['obs_pred'][:,6:9]-expected).abs().max()))
            ownership_error = max(ownership_error,max(float((obs[k]-v).abs().max()) for k,v in previous_obs.items()))
            assert last_force['body_ids']==[env.gripper_id] and last_force['is_global']
            if step >= 376:
                xs.append(obs['obs'].clone()); ys.append(obs['obs_pred'].clone())
            obs = next_obs
        assert label_error < 1e-6 and ownership_error == 0 and storage_error == 0
        x,y = torch.cat(xs),torch.cat(ys)
        with torch.no_grad():
            pred = model.get_student_latent(x)
        force_rmse = float((pred[:,6:9]-y[:,6:9]).square().mean().sqrt()*100)
        force_zero_rmse = float(y[:,6:9].square().mean().sqrt()*100)
        common_history = {}
        for it,path in CHECKPOINTS.items():
            other = torch.load(ROOT/'logs'/path, map_location=env.device, weights_only=True)
            model.load_state_dict(other['model_state_dict'])
            with torch.no_grad():
                z = model.get_student_latent(x)[:,6:9]
                common_history[it] = float((z-y[:,6:9]).square().mean().sqrt()*100)
        model.load_state_dict(ck['model_state_dict'])
        enc = list(model.adaptation_encoder_module.parameters())
        dec = list(model.adaptation_decoder_module.parameters())
        task_gradients = {}
        for i,weight in enumerate(model.adaptation_weights):
            loss = ((model.get_student_latent(x)[:,i*3:i*3+3]-y[:,i*3:i*3+3])*weight).square().mean()
            gs = torch.autograd.grad(loss,enc+dec)
            task_gradients[model.adaptation_labels[i]] = {'actual_mse_weighted':float(loss.detach()),
                'encoder_grad_norm':float(sum(g.square().sum() for g in gs[:len(enc)]).sqrt()),
                'decoder_grad_norm':float(sum(g.square().sum() for g in gs[len(enc):]).sqrt())}
        # Use the actual released update on the final real 24-step rollout.
        # Parameters/optimizers exist only in memory and are discarded afterwards.
        with torch.no_grad(): algo.compute_returns(obs['privileged_obs'])
        sb = algo.storage
        ob = sb.observations.flatten(0,1)
        model.update_distribution(ob)
        ratio = (model.get_actions_log_prob(sb.actions.flatten(0,1))-sb.actions_log_prob.flatten()).exp()
        adv = sb.advantages.flatten()
        policy_loss = torch.maximum(-adv*ratio, -adv*ratio.clamp(.8,1.2)).mean()-.01*model.entropy.mean()
        pg = torch.autograd.grad(policy_loss,enc)
        sg = torch.autograd.grad((model.get_student_latent(ob)[:,6:9]-sb.observation_preds.flatten(0,1)[:,6:9]).square().mean(),enc)
        pgv,sgv = torch.cat([g.flatten() for g in pg]),torch.cat([g.flatten() for g in sg])
        gradient_relation = {'policy_encoder_norm':float(pgv.norm()), 'force_supervision_encoder_norm':float(sgv.norm()),
            'cosine':float(torch.nn.functional.cosine_similarity(pgv,sgv,dim=0)),
            'scope':'one actual rollout before update; does not establish chronic gradient conflict'}
        before = {k:v.clone() for k,v in model.state_dict().items()}
        summary = algo.update()
        changed = {}
        for module in ('adaptation_encoder_module','adaptation_decoder_module','actor_body','critic_body'):
            changed[module] = float(sum((v-before[k]).square().sum() for k,v in model.state_dict().items() if k.startswith(module)).sqrt())
        assert all(v>0 for v in changed.values())
        out = {'scope':'disposable 16-env, 504-step training-distribution probe; no checkpoint saved',
            'gripper_body':env.robot.body_names[env.gripper_id], 'force_world_to_label_max_error_scaled':label_error,
            'rollout_tensor_mutation_max':ownership_error, 'storage_obs_label_max_error':storage_error,
            'force_rmse_per_axis_n':force_rmse,
            'zero_predictor_rmse_per_axis_n':force_zero_rmse,
            'common_training_history_rmse_per_axis_n':common_history,
            'nonzero_external_fraction':float((y[:,6:9].norm(dim=-1)>0.01).float().mean()),
            'gradient_by_task':task_gradients, 'released_update_loss':list(summary),
            'module_change_l2_in_disposable_update':changed,
            'encoder_gradient_relation':gradient_relation,
            'logging_loss_divisor':64, 'force_curriculum_summary':env.curriculum.summary()}
        (OUT/'live.json').write_text(json.dumps(out,indent=2)+'\n')
        print('SUPERVISION_AUDIT_PASS',json.dumps(out))
    finally:
        env.close(); app.close(skip_cleanup=True)


def ablation(args):
    """Paired updates on on-policy joint rollouts; fixed held-out env histories.

    The supervised branch never controls data collection. Thus this comparison
    isolates the extra PPO updates on identical inputs, not closed-loop policies.
    """
    import copy
    import hashlib
    from isaaclab.app import AppLauncher
    app = AppLauncher(args).app
    import torch
    from ranger_unifp_vec_env import RangerUniFPVecEnv
    from legged_gym.b2_gym_learn.ppo_cse_pf.actor_critic import ActorCritic
    from legged_gym.b2_gym_learn.ppo_cse_pf.ppo import PPO
    output = args.ablation_output or OUT / f'ablation_seed{args.ablation_seed}'
    if output.exists():
        raise FileExistsError(f'Use a fresh experiment directory: {output}')
    output.mkdir(parents=True)
    train_n, val_n, rollout = 128, 32, 24
    seed = args.ablation_seed
    config = {'seed':seed, 'iterations':args.ablation_iterations,
        'training_envs':train_n, 'validation_envs':val_n, 'steps_per_env':rollout,
        'checkpoint':str(ROOT/'logs'/CHECKPOINTS[10000]),
        'validation':'independent env ids 128..159, fixed pre-update histories; no window split',
        'collection':'joint branch sampled actions, on-policy; supervisor sees identical rollouts',
        'supervision':'all four released MSE tasks, weights and Adam restored unchanged',
        'domain_randomization':True, 'observation_noise':True, 'random_goals':True,
        'command_sampling':True, 'push_robots':True, 'max_force_per_axis_n':15,
        'scope':'diagnostic 200-round branches; not production continuation or deployable policy'}
    (output/'config.json').write_text(json.dumps(config,indent=2)+'\n')
    env = RangerUniFPVecEnv(num_envs=train_n+val_n, device=args.device,
        domain_randomization=True, observation_noise=True, command_sampling=True,
        random_goals=True, force_curriculum=True, push_robots=True,
        curriculum_start_step=192001, seed=seed)
    try:
        checkpoint = torch.load(ROOT/'logs'/CHECKPOINTS[10000],map_location=env.device,weights_only=True)
        env.global_policy_steps = checkpoint['global_policy_steps']
        model = ActorCritic(env.num_obs,env.num_privileged_obs,env.num_pred_obs,env.num_single_obs,
            env.num_actions,actor_hidden_dims=[512,256,128],critic_hidden_dims=[512,256,128]).to(env.device)
        model.load_state_dict(checkpoint['model_state_dict'])
        supervised = copy.deepcopy(model)
        joint = PPO(model,device=env.device,entropy_coef=.01,num_learning_epochs=5,
            num_mini_batches=4,schedule='adaptive',desired_kl=.01,gamma=.99,lam=.95)
        joint.optimizer.load_state_dict(checkpoint['optimizer_state_dict'])
        joint.adaptation_module_optimizer.load_state_dict(checkpoint['adaptation_optimizer_state_dict'])
        joint.learning_rate=checkpoint['learning_rate']
        joint.init_storage(train_n,rollout,[env.num_obs],[env.num_privileged_obs],
            [env.num_pred_obs],[env.num_actions])
        supervisor = torch.optim.Adam(supervised.parameters(),lr=1e-5)
        supervisor.load_state_dict(copy.deepcopy(checkpoint['adaptation_optimizer_state_dict']))
        # load_state_dict may reuse same-device optimizer tensors. The two
        # branches must never share mutable Adam moments or step counters.
        for k,v in joint.adaptation_module_optimizer.state.items():
            name=next(n for n,p in model.named_parameters() if p is k)
            other=dict(supervised.named_parameters())[name]
            for field,tensor in v.items():
                if isinstance(tensor,torch.Tensor):
                    assert tensor.data_ptr()!=supervisor.state[other][field].data_ptr()
        frozen = {k:v.clone() for k,v in supervised.state_dict().items()
            if not k.startswith(('adaptation_encoder_module','adaptation_decoder_module'))}
        # Keep non-overlapping environment groups. Each val environment has its
        # own episode, domain parameters, commands, force/noise RNG draws.
        obs=env.get_observations()
        vx,vy=[],[]
        with torch.no_grad():
            for step in range(1000):
                if step>=32 and step%8==0:
                    vx.append(obs['obs'][train_n:].clone())
                    vy.append(obs['obs_pred'][train_n:].clone())
                obs,_,_,_=env.step(model.act(obs['obs']))
        vx,vy=torch.cat(vx),torch.cat(vy)
        torch.save({'obs':vx.cpu(),'obs_pred':vy.cpu(),'env_ids':list(range(train_n,train_n+val_n)),
            'sampling':'steps 32..999 every 8 policy steps, 32 independent validation environments'},
            output/'validation.pt')
        val_hash=hashlib.sha256((output/'validation.pt').read_bytes()).hexdigest()
        def evaluate(m):
            with torch.no_grad():
                p=torch.cat([m.get_student_latent(x) for x in vx.split(512)])[:,6:9]*100
                f=vy[:,6:9]*100
                active=f.norm(dim=-1)>1
                zero=f.norm(dim=-1)<.05
                return {'force_rmse_per_axis_n':float((p-f).square().mean().sqrt()),
                    'active_vector_error_n':float((p[active]-f[active]).norm(dim=-1).mean()),
                    'zero_estimate_norm_n':float(p[zero].norm(dim=-1).mean()),
                    'force_rmse_xyz_n':(p-f).square().mean(0).sqrt().tolist()}
        with torch.no_grad():
            vf=vy[:,6:9]*100
            val_baseline={'zero_predictor_rmse_per_axis_n':float(vf.square().mean().sqrt()),
                'zero_predictor_active_vector_error_n':float(vf[vf.norm(dim=-1)>1].norm(dim=-1).mean()),
                'active_samples':int((vf.norm(dim=-1)>1).sum()),
                'zero_samples':int((vf.norm(dim=-1)<.05).sum()),'samples':len(vy)}
        history=[{'iteration':0,'joint':evaluate(model),'supervised_only':evaluate(supervised)}]
        print('ABLATION_VALIDATION',json.dumps(history[-1]),flush=True)
        # New episodes for training; frozen validation tensors are never passed
        # to either optimizer or rollout storage.
        obs,_=env.reset()
        zero=0.
        def sup_loss(x,y):
            pred=supervised.get_student_latent(x)
            return sum(((pred[:,i*3:i*3+3]-y[:,i*3:i*3+3])*w).square().mean()
                for i,w in enumerate(supervised.adaptation_weights))
        for iteration in range(1,args.ablation_iterations+1):
            with torch.no_grad():
                for _ in range(rollout):
                    actions=joint.act(obs['obs'][:train_n],obs['privileged_obs'][:train_n],obs['obs_pred'][:train_n])
                    val_actions=model.act(obs['obs'][train_n:])
                    obs,reward,done,info=env.step(torch.cat((actions,val_actions)))
                    joint.process_env_step(reward[:train_n],done[:train_n],
                        {'time_outs':info['time_outs'][:train_n]})
                joint.compute_returns(obs['privileged_obs'][:train_n])
            # Equal minibatch permutations, same 5x4 supervised Adam steps.
            rng=torch.cuda.get_rng_state(env.device) if str(env.device).startswith('cuda') else torch.get_rng_state()
            official_loss=joint.update()
            after_rng=torch.cuda.get_rng_state(env.device) if str(env.device).startswith('cuda') else torch.get_rng_state()
            if str(env.device).startswith('cuda'): torch.cuda.set_rng_state(rng,env.device)
            else: torch.set_rng_state(rng)
            losses=[]
            # update() clears only storage.step, not stored rollout tensors.
            for batch in joint.storage.mini_batch_generator(4,5):
                loss=sup_loss(batch[0],batch[2])
                supervisor.zero_grad(); loss.backward(); supervisor.step()
                losses.append(float(loss.detach()))
            if str(env.device).startswith('cuda'): torch.cuda.set_rng_state(after_rng,env.device)
            else: torch.set_rng_state(after_rng)
            assert torch.isfinite(torch.tensor([*official_loss[:3],*losses])).all()
            if iteration%25==0 or iteration==args.ablation_iterations:
                row={'iteration':iteration,'joint':evaluate(model),'supervised_only':evaluate(supervised),
                    'official_logged_force_loss':official_loss[3]['force_ee_loss'],
                    'supervised_total_loss':sum(losses)/len(losses)}
                history.append(row)
                (output/'progress.json').write_text(json.dumps(history,indent=2)+'\n')
                print('ABLATION_VALIDATION',json.dumps(row),flush=True)
        assert all(torch.equal(v,frozen[k]) for k,v in supervised.state_dict().items() if k in frozen)
        for name,m in [('joint',model),('supervised_only',supervised)]:
            torch.save({'model_state_dict':m.state_dict(),'diagnostic_only':True,
                'initial_iterations':10000,'diagnostic_iterations':args.ablation_iterations,
                'config':config},output/f'{name}.pt')
        result={'config':config,'validation_sha256':val_hash,'validation_baseline':val_baseline,
            'history':history,'supervised_actor_critic_std_unchanged':True,
            'supervised_steps_per_branch':20*args.ablation_iterations,
            'training_transitions':train_n*rollout*args.ablation_iterations,
            'limitations':['fixed validation samples collected with initial policy',
                'shared joint-branch collection isolates update effects, not independent closed-loop policy performance',
                'held-out environments share simulator and global seed but no training histories',
                'small diagnostic budget does not establish paper-level convergence']}
        (output/'result.json').write_text(json.dumps(result,indent=2)+'\n')
        print('ABLATION_PASS',json.dumps({k:v for k,v in result.items() if k!='history'}),flush=True)
    finally:
        env.close(); app.close(skip_cleanup=True)


class PairedNoiseHistory:
    """Diagnostic-only hooks: one clean frame, two reset-synchronous FIFOs.

    The original actor owns the clean FIFO. Noise is sampled only for the new
    frame, exactly where released observe() samples it; padding stays zero.
    The environment/behavior receives the noisy FIFO, as in normal training.
    """
    def __init__(self, actor):
        import torch
        self.actor = actor
        self.noisy = torch.zeros_like(actor.history)
        self.age = torch.zeros(actor.num_envs, dtype=torch.long, device=actor.device)
        self.original_observe, self.original_reset = actor.observe, actor.reset
        self.calls = self.reset_envs = 0
        actor.observe, actor.reset = self.observe, self.reset

    def reset(self, env_ids):
        self.original_reset(env_ids)
        self.noisy[env_ids] = 0
        self.age[env_ids] = 0
        self.reset_envs += len(env_ids)

    def observe(self, robot, actions, add_noise=False):
        import torch
        assert add_noise, 'The behavior must retain official observation noise'
        frame, _ = self.original_observe(robot, actions, add_noise=False)
        noisy_frame = frame + torch.randn_like(frame) * self.actor.noise_scale
        self.noisy[:, :-1] = self.noisy[:, 1:].clone()
        self.noisy[:, -1] = noisy_frame
        self.age = (self.age + 1).clamp(max=32)
        self.calls += 1
        # Validate padding after every manual or automatic reset and confirm
        # command/action (zero noise scale) channels are identical at all ages.
        padding = torch.arange(32, device=frame.device)[None, :] < (32-self.age[:, None])
        assert (self.actor.history[padding] == 0).all()
        assert (self.noisy[padding] == 0).all()
        unchanged = self.actor.noise_scale == 0
        assert torch.equal(self.actor.history[:, :, unchanged], self.noisy[:, :, unchanged])
        assert torch.isfinite(self.noisy).all()
        return noisy_frame, self.noisy.flatten(1)

    def clean(self):
        return self.actor.history.flatten(1).clamp(-100., 100.).clone()



def install_dynamics_split(nominal_start, factor='all'):
    """Split rigid/motor domains without disabling original reset sampling."""
    import torch
    import ranger_unifp_vec_env as ranger
    from unifp_domain_randomization import UniFPDomainRandomization
    class SplitDynamics(UniFPDomainRandomization):
        def __init__(self, robot, controller, scene, **kwargs):
            self.nominal_start=nominal_start
            self.view=robot.root_physx_view
            fields=('masses','inertias','coms','material_properties')
            before={key:getattr(self.view,f'get_{key}')().clone() for key in fields}
            super().__init__(robot,controller,scene,**kwargs)
            assert self.enabled and scene.num_envs==2*nominal_start
            self.baseline=before
            ids=torch.arange(nominal_start,scene.num_envs,device='cpu')
            randomized={key:getattr(self.view,f'get_{key}')().clone() for key in fields}
            reference={key:value.clone() for key,value in (randomized if factor=='motor' else before).items()}
            if factor=='motor':
                # Match random rigid properties by local environment id. Keep
                # every original draw to preserve the random-number stream.
                for value in reference.values(): value[nominal_start:]=value[:nominal_start].clone()
            for key in fields: getattr(self.view,f'set_{key}')(reference[key],ids)
            self.reference=reference
            self.mass_deltas[nominal_start:]=self.mass_deltas[:nominal_start].clone() if factor=='motor' else 0
            self.friction[nominal_start:]=self.view.get_material_properties()[nominal_start:,:1,0].to(self.device)
            self.motor_strength[nominal_start:]=1
            self.diagnostic_properties={'nominal_reference':before,
                'randomized_before_split':randomized,'expected_rigid_properties':reference,'factor':factor,
                'actual':{key:getattr(self.view,f'get_{key}')().clone() for key in fields},
                'motor_strength':self.motor_strength.cpu().clone(),'nominal_start':nominal_start}
            self.check_nominal()
            print('DYNAMICS_PROPERTIES_CHECK_PASS',self.integrity,flush=True)

        def resample_motor(self, env_ids):
            # Always consume the same original draws, including for nominal
            # ids; do not disable the reset-state randomization code path.
            super().resample_motor(env_ids)
            self.motor_strength[env_ids[env_ids>=self.nominal_start]]=1
            self.check_motor()

        def check_motor(self):
            assert self.enabled
            assert (self.motor_strength[self.nominal_start:]==1).all()
            assert (self.motor_strength[:self.nominal_start]>=.85).all()
            assert (self.motor_strength[:self.nominal_start]<=1.15).all()

        def check_nominal(self):
            self.check_motor(); self.integrity={}
            for key,before in self.reference.items():
                after=getattr(self.view,f'get_{key}')()
                error=float((after[self.nominal_start:]-before[self.nominal_start:]).abs().max())
                if factor=='motor':
                    # PhysX round-trips randomized inertia through its principal
                    # axes; compare at float32 precision, not bit equality.
                    torch.testing.assert_close(after[self.nominal_start:],before[self.nominal_start:],rtol=1e-6,atol=1e-6)
                    assert torch.equal(after[:self.nominal_start],before[:self.nominal_start])
                else: assert error<1e-6, (key,error)
                self.integrity[f'reference_{key}_max_error']=error
            assert (self.mass_deltas[:self.nominal_start,0]>0).all()
            if factor=='motor':
                assert torch.equal(self.mass_deltas[self.nominal_start:],self.mass_deltas[:self.nominal_start])
                assert torch.equal(self.friction[self.nominal_start:],self.friction[:self.nominal_start])
                self.integrity['paired_random_rigid_properties']=True
            else: assert (self.mass_deltas[self.nominal_start:]==0).all()
            self.integrity['reset_enabled_both']=True
            self.integrity['treatment_motor_exactly_one']=True
    ranger.UniFPDomainRandomization=SplitDynamics

def pd_equivalence(args):
    """Execute the official method directly from its AST, without importing Isaac Gym."""
    import ast
    import hashlib
    import shutil
    from types import SimpleNamespace
    import torch
    import numpy as np
    from unifp_stage1_control import NamedJointPD, ALL_JOINT_NAMES, ACTION_JOINT_NAMES, HOLD_JOINT_NAMES
    output=args.probe_output
    output.mkdir(parents=True,exist_ok=False)
    shutil.copyfile(__file__,output/'audit_snapshot.py')
    source=ROOT/'UniFP/legged_gym/envs/b2/legged_robot_b2z1_pos_force.py'
    cfg_source=ROOT/'UniFP/legged_gym/envs/b2/b2z1_pos_force_config.py'
    tree=ast.parse(source.read_text())
    method=next(n for n in ast.walk(tree) if isinstance(n,ast.FunctionDef) and n.name=='_compute_torques')
    scope={'torch':torch}
    exec(compile(ast.Module(body=[method],type_ignores=[]),str(source),'exec'),scope)
    cfg_tree=ast.parse(cfg_source.read_text())
    cfg=next(n for n in cfg_tree.body if isinstance(n,ast.ClassDef) and n.name=='B2Z1PosForceRoughCfg')
    cfg_scope={'np':np}
    for node in cfg.body:
        if isinstance(node,ast.ClassDef) and node.name in ('control','init_state'):
            node.bases=[]
            exec(compile(ast.Module(body=[node],type_ignores=[]),str(cfg_source),'exec'),cfg_scope)
    control=cfg_scope['control']; official_defaults=cfg_scope['init_state'].default_joint_angles
    count=257; rng=torch.Generator().manual_seed(20261023)
    order=ACTION_JOINT_NAMES+HOLD_JOINT_NAMES; sim_order=tuple(reversed(order))
    pd=NamedJointPD.from_robot(SimpleNamespace(joint_names=sim_order,
        data=SimpleNamespace(joint_pos=torch.zeros(count,len(ALL_JOINT_NAMES)))))
    defaults=torch.tensor([official_defaults[n] for n in order]).unsqueeze(0)
    q=defaults+.7*torch.randn((count,19),generator=rng)
    velocity=3*torch.randn((count,19),generator=rng)
    actions=2*torch.rand((count,17),generator=rng)-1
    strength=.8+.4*torch.rand((count,17),generator=rng)
    def official_gains(mapping):
        return torch.tensor([next(value for key,value in mapping.items() if key in name)
            for name in order[:17]])
    to_sim=[order.index(n) for n in sim_order]; to_official=[sim_order.index(n) for n in order]
    state=SimpleNamespace(motor_strength=strength,cfg=SimpleNamespace(control=control),
        p_gains=official_gains(control.stiffness),d_gains=official_gains(control.damping),
        default_dof_pos=defaults,default_dof_pos_wo_gripper=defaults[:,:17],
        dof_pos=q,dof_vel=velocity,dof_pos_wo_gripper=q[:,:17],dof_vel_wo_gripper=velocity[:,:17],
        torque_limits=pd.effort_limits[to_official])
    expected=scope['_compute_torques'](state,actions)
    actual=pd.compute(actions,q[:,to_sim],velocity[:,to_sim],strength)[:,to_official]
    difference=(actual-expected).abs()
    torch.testing.assert_close(actual,expected,rtol=0,atol=1e-6)
    result={'seed':20261023,'samples':count,'executed_official_method_ast':True,
        'gains_and_defaults_loaded_from_official_config':True,
        'simulation_joint_order':list(sim_order),
        'max_abs_torque_difference_nm':float(difference.max()),
        'mean_abs_torque_difference_nm':float(difference.mean()),
        'source_sha256':{str(p.relative_to(ROOT)):hashlib.sha256(p.read_bytes()).hexdigest()
            for p in (source,cfg_source,ROOT/'unifp_stage1_control.py')}}
    torch.save({'actions':actions,'strength':strength,'q':q,'velocity':velocity,
        'official':expected,'adapted':actual,'official_joint_order':order},output/'inputs_outputs.pt')
    (output/'result.json').write_text(json.dumps(result,indent=2)+'\n')
    print('PD_EQUIVALENCE_PASS',json.dumps(result),flush=True)


def adapter_probe(args):
    """Read effective solver/shape settings, without modifying assets or stepping a policy."""
    import hashlib
    import shutil
    import torch
    from isaaclab.app import AppLauncher
    output=args.probe_output
    output.mkdir(parents=True,exist_ok=False)
    shutil.copyfile(__file__,output/'audit_snapshot.py')
    app=AppLauncher(args).app
    env=None
    try:
        from pxr import Usd, UsdPhysics, PhysxSchema
        from ranger_unifp_vec_env import RangerUniFPVecEnv
        from unifp_vec_env import UniFPVecEnv
        cls=RangerUniFPVecEnv if args.probe_robot=='ranger' else UniFPVecEnv
        env=cls(num_envs=1,device=args.device,domain_randomization=False,
            force_curriculum=False,observation_noise=False,command_sampling=False,
            random_goals=False,push_robots=False,seed=19024)
        rows=[]
        for prim in Usd.PrimRange.Stage(env.sim.stage,Usd.TraverseInstanceProxies()):
            if '/World/envs/env_0/Robot' not in str(prim.GetPath()):
                continue
            values={}
            for name in ('physxArticulation:solverPositionIterationCount',
                         'physxArticulation:solverVelocityIterationCount',
                         'physxCollision:contactOffset','physxCollision:restOffset',
                         'physxRigidBody:maxDepenetrationVelocity'):
                attr=prim.GetAttribute(name)
                if attr:
                    values[name]={'get':attr.Get(),'authored':attr.HasAuthoredValueOpinion()}
            if values:
                rows.append({'path':str(prim.GetPath()),'values':values})
        tape={}
        for key in ('contact_offsets','rest_offsets','linear_dampings','angular_dampings',
                    'masses','inertias','coms','max_depenetration_velocities'):
            getter=getattr(env.robot.root_physx_view,'get_'+key,None)
            if getter is not None:
                tape[key]=getter().cpu().clone()
        tape['joint_positions']=env.robot.data.joint_pos.cpu().clone()
        torch.save(tape,output/'shape_properties.pt')
        result={'robot':args.probe_robot,'physx_cfg':env.sim.cfg.physx.to_dict(),
            'rigid_body_schema_defaults':{name:getattr(PhysxSchema.PhysxRigidBodyAPI.Get(
                env.sim.stage,'/World/envs/env_0/Robot/base_link'),'Get'+name+'Attr')().Get()
                for name in ('LinearDamping','AngularDamping','MaxDepenetrationVelocity')},
            'body_names':env.robot.body_names,'joint_names':env.robot.joint_names,
            'usd_values':rows,'runtime_tensor_summary':{key:{'shape':list(v.shape),
                'min':float(v.min()),'max':float(v.max()),'unique':v.unique().tolist()}
                for key,v in tape.items()},
            'caveat':'USD Get values are schema/default values; authored=false is not a backend measurement',
            'source_sha256':{name:hashlib.sha256((ROOT/name).read_bytes()).hexdigest()
                for name in ('unifp_vec_env.py','ranger_unifp_vec_env.py')}}
        (output/'result.json').write_text(json.dumps(result,indent=2)+'\n')
        print('ADAPTER_PROBE_PASS',args.probe_robot,json.dumps(result['runtime_tensor_summary']),flush=True)
    finally:
        if env is not None: env.close()
        app.close(skip_cleanup=True)


def force_response(args):
    """Controlled open-loop force/no-force pairs on the CURRENT asset, no fit."""
    import hashlib
    import shutil
    from isaaclab.app import AppLauncher
    output=args.response_output or OUT/'force_response_v3_original'
    output.mkdir(parents=True,exist_ok=False)
    shutil.copyfile(__file__,output/'audit_snapshot.py')
    app=AppLauncher(args).app
    import torch
    from isaaclab.utils.math import quat_apply_inverse,yaw_quat
    from ranger_unifp_vec_env import RangerUniFPVecEnv
    torch.set_num_threads(2)
    poses=[[0,1,-1.5,0,0,0],[.6,.8,-1.2,.2,.3,0],
        [-.6,1.2,-1.8,-.2,-.3,.3],[0,.5,-.8,0,.4,0]]
    force_levels = sorted(set(float(v) for v in args.response_force_levels))
    if not force_levels or force_levels[0] <= 0:
        raise ValueError("response force levels must be positive")
    forces=[[0,0,0]]
    for level in force_levels:
        forces.extend([[level,0,0],[-level,0,0],[0,level,0],[0,-level,0],[0,0,level],[0,0,-level]])
    config={'scope':'diagnostic forward force response only; no learner/production updates',
        'asset':'v3_original','poses_arm_rad':poses,'forces_world_n':forces,
        'physx_iteration_profile':args.response_physx_profile,
        'force_levels_per_axis_n':force_levels,
        'pairing':'two adjacent envs per pose/force: zero control then loaded; identical constant action replay',
        'steps':300,'policy_dt_s':.02,'force_window_steps':[100,200],'steady_window_steps':[175,200],
        'controls':'nominal rigid parameters and motor=1; no observation noise, random tasks or base pushes',
        'reason_for_controls':'measure mechanical response separately from policy feedback and task/random-parameter confounding',
        'force_point':'arm_seg6, API default wrench position; same setter/body/global coordinates as training',
        'checkpoint_sha256':hashlib.sha256((ROOT/'logs'/CHECKPOINTS[10000]).read_bytes()).hexdigest()}
    (output/'config.json').write_text(json.dumps(config,indent=2)+'\n')
    import isaaclab.sim as sim_utils
    original_physx_cfg=sim_utils.PhysxCfg
    def diagnostic_physx_cfg(**kwargs):
        if args.response_physx_profile=='official_b2':
            kwargs.update(min_position_iteration_count=4,max_position_iteration_count=4,
                min_velocity_iteration_count=0,max_velocity_iteration_count=0)
        return original_physx_cfg(**kwargs)
    # Keep the override within this diagnostic's construction; production files
    # and the persistent USD assets remain unchanged.
    sim_utils.PhysxCfg=diagnostic_physx_cfg
    try:
        env=RangerUniFPVecEnv(num_envs=2*len(poses)*len(forces),device=args.device,
            domain_randomization=False,observation_noise=False,command_sampling=False,
            random_goals=False,force_curriculum=True,push_robots=False,seed=0)
    finally:
        sim_utils.PhysxCfg=original_physx_cfg
    try:
        from pxr import PhysxSchema
        articulation_prim=next(p for p in env.sim.stage.Traverse()
            if PhysxSchema.PhysxArticulationAPI(p))
        articulation_api=PhysxSchema.PhysxArticulationAPI(articulation_prim)
        config['runtime_physx']={
            'solver_type':int(env.sim.cfg.physx.solver_type),
            'position_iteration_clamp':[int(env.sim.cfg.physx.min_position_iteration_count),
                int(env.sim.cfg.physx.max_position_iteration_count)],
            'velocity_iteration_clamp':[int(env.sim.cfg.physx.min_velocity_iteration_count),
                int(env.sim.cfg.physx.max_velocity_iteration_count)],
            'root_usd_position_iteration_count':int(articulation_api.GetSolverPositionIterationCountAttr().Get()),
            'root_usd_velocity_iteration_count':int(articulation_api.GetSolverVelocityIterationCountAttr().Get()),
            'effective_root_iteration_counts':[
                min(max(int(articulation_api.GetSolverPositionIterationCountAttr().Get()),
                    int(env.sim.cfg.physx.min_position_iteration_count)),
                    int(env.sim.cfg.physx.max_position_iteration_count)),
                min(max(int(articulation_api.GetSolverVelocityIterationCountAttr().Get()),
                    int(env.sim.cfg.physx.min_velocity_iteration_count)),
                    int(env.sim.cfg.physx.max_velocity_iteration_count))],
        }
        (output/'config.json').write_text(json.dumps(config,indent=2)+'\n')
        env.reset()
        robot=env.robot
        q=robot.data.default_joint_pos.clone()
        arm_ids=env.controller.action_indices[8:]
        q[:,arm_ids]=torch.tensor(poses,device=env.device).repeat_interleave(2*len(forces),dim=0)
        limits=robot.data.joint_pos_limits[:,arm_ids]
        assert ((q[:,arm_ids]>=limits[:,:,0]) & (q[:,arm_ids]<=limits[:,:,1])).all()
        robot.write_joint_state_to_sim(q,torch.zeros_like(q))
        actions=torch.zeros(env.num_envs,14,device=env.device)
        actions[:,8:]=(q[:,arm_ids]-env.controller.default_positions[arm_ids])/.25
        assert torch.equal(actions[::2],actions[1::2]) and (env.domain.motor_strength==1).all()
        root=robot.data.root_state_w.clone(); root[:,:3]-=env.scene.env_origins
        torch.testing.assert_close(root[::2],root[1::2],rtol=0,atol=1e-6)
        assert torch.equal(q[::2],q[1::2])
        properties={k:getattr(robot.root_physx_view,f'get_{k}')().cpu().clone()
            for k in ('masses','inertias','coms','material_properties')}
        for values in properties.values():
            torch.testing.assert_close(values[::2],values[1::2],rtol=1e-6,atol=1e-6)
        torch.save({'joint_pos':q.cpu(),'root_relative':root.cpu(),'properties':properties,
            'actions':actions.cpu(),'motor_strength':env.domain.motor_strength.cpu()},output/'initial_state.pt')
        applied=torch.zeros(env.num_envs,3,device=env.device)
        pulse=torch.tensor(forces,device=env.device,dtype=torch.float32).repeat(len(poses),1)
        def manual_force(*unused,**kwargs):
            return torch.zeros_like(applied),applied
        env.curriculum.update=manual_force
        rows={key:[] for key in ('joint_pos','joint_vel','root_pos','ee_pos','clean_frame','force_world','force_label','pd_effort_fraction')}
        label_error=0.
        for step in range(300):
            applied.zero_()
            if 100<=step<200: applied[1::2]=pulse
            obs,_,done,_=env.step(actions)
            assert not done.any(),'A reset invalidates the matched initial-state response trial'
            expected=quat_apply_inverse(yaw_quat(robot.data.root_quat_w),applied)*.01
            label_error=max(label_error,float((obs['obs_pred'][:,6:9]-expected).abs().max()))
            rows['joint_pos'].append(robot.data.joint_pos[:,arm_ids].cpu().clone())
            rows['joint_vel'].append(robot.data.joint_vel[:,arm_ids].cpu().clone())
            rows['root_pos'].append((robot.data.root_pos_w-env.scene.env_origins).cpu().clone())
            rows['ee_pos'].append((robot.data.body_pos_w[:,env.gripper_id]-env.scene.env_origins).cpu().clone())
            rows['clean_frame'].append(env.actor.history[:,-1].cpu().clone())
            rows['force_world'].append(applied.cpu().clone())
            rows['force_label'].append(obs['obs_pred'][:,6:9].cpu().clone())
            rows['pd_effort_fraction'].append((robot.data.applied_torque[:,arm_ids].abs()/env.controller.effort_limits[arm_ids]).cpu().clone())
        data={key:torch.stack(values) for key,values in rows.items()}
        data.update(actions=actions.cpu(),noise_scale=env.actor.noise_scale.cpu(),config=config)
        torch.save(data,output/'response.pt')
        assert label_error<1e-6
        results=[]
        for pose in range(len(poses)):
            for direction,force in enumerate(forces):
                c=2*(pose*len(forces)+direction); t=c+1
                dq=data['joint_pos'][:,t]-data['joint_pos'][:,c]
                dr=data['root_pos'][:,t]-data['root_pos'][:,c]
                df=data['clean_frame'][:,t]-data['clean_frame'][:,c]
                results.append({'pose':pose,'force_world_n':force,
                    'force_level_per_axis_n':float(max(abs(v) for v in force)),
                    'pre_force_joint_delta_max_deg':float(dq[:100].abs().max().rad2deg()),
                    'steady_joint_delta_xyz_deg':dq[175:200].mean(0).rad2deg().tolist(),
                    'steady_max_joint_delta_deg':float(dq[175:200].mean(0).abs().max().rad2deg()),
                    'loaded_peak_joint_delta_deg':float(dq[100:200].abs().max().rad2deg()),
                    'steady_base_xy_delta_mm':float(dr[175:200,:2].norm(dim=-1).mean()*1000),
                    'steady_arm_position_delta_over_noise_std':(df[175:200,9:15].square().mean(0).sqrt()/data['noise_scale'][9:15]).tolist(),
                    'loaded_effort_limit_fraction_max':float(data['pd_effort_fraction'][100:200,[c,t]].max())})
        result={'config':config,'pairs':results,'force_label_max_error_scaled':label_error,
            'paired_actions_exactly_equal':True,'paired_initial_states_and_rigid_properties_checked':True,
            'response_sha256':hashlib.sha256((output/'response.pt').read_bytes()).hexdigest(),
            'checkpoint_unchanged':hashlib.sha256((ROOT/'logs'/CHECKPOINTS[10000]).read_bytes()).hexdigest()==config['checkpoint_sha256'],
        'limitations':[f'four selected stationary poses, nominal dynamics and {force_levels} N-per-axis axis-aligned steps only',
                'open-loop response does not establish force identifiability under random dynamics/commands or closed-loop feedback',
                'delta/noise compares deterministic frame response to configured one-frame noise std, not a learned estimator SNR',
                'implicit PD effort is the simulator estimate, not measured actuator torque; no Jacobian inverse force estimator']}
        assert result['checkpoint_unchanged']
        (output/'result.json').write_text(json.dumps(result,indent=2)+'\n')
        print('FORCE_RESPONSE_PASS',json.dumps(result),flush=True)
    finally:
        env.close();app.close(skip_cleanup=True)


def summarize_response(args):
    """Recompute mechanical deltas from the saved CPU tape, then plot them."""
    import hashlib
    import shutil
    import torch
    import matplotlib
    matplotlib.use('Agg')
    import matplotlib.pyplot as plt
    output=args.response_output or OUT/'force_response_v3_original'
    target=output/'summary.json'
    assert not target.exists() and not (output/'response.png').exists()
    r=json.loads((output/'result.json').read_text())
    assert hashlib.sha256((output/'response.pt').read_bytes()).hexdigest()==r['response_sha256']
    d=torch.load(output/'response.pt',map_location='cpu',weights_only=True)
    initial=torch.load(output/'initial_state.pt',map_location='cpu',weights_only=True)
    assert torch.equal(d['actions'][::2],d['actions'][1::2])
    assert torch.equal(d['actions'],initial['actions'])
    assert not d['force_world'][:100].any() and not d['force_world'][200:].any()
    assert not d['force_world'][:,::2].any()
    fig,axes=plt.subplots(1,2,figsize=(12,4.6))
    values=[];zeros=[]
    for i,row in enumerate(r['pairs']):
        c,t=2*i,2*i+1
        q=d['joint_pos'][:,t]-d['joint_pos'][:,c]
        dq=q[175:200].mean(0).rad2deg()
        assert max(abs(a-b) for a,b in zip(dq.tolist(),row['steady_joint_delta_xyz_deg']))<1e-6
        expected=torch.tensor(row['force_world_n'],dtype=d['force_world'].dtype)
        assert torch.equal(d['force_world'][100:200,t],expected.expand(100,3))
        if expected.any(): values.append(row)
        else: zeros.append(row)
        if row['pose']==0 and expected.any() and row['force_level_per_axis_n'] == min(
                v['force_level_per_axis_n'] for v in r['pairs'] if v['force_level_per_axis_n'] > 0):
            axis=int(expected.abs().argmax()); sign='+' if expected[axis]>0 else '-'
            axes[1].plot(torch.arange(300)*.02,q.abs().max(1).values.rad2deg(),
                label=f"{sign}{'XYZ'[axis]} {row['force_level_per_axis_n']:g}N")
    levels=sorted({v['force_level_per_axis_n'] for v in values})
    for pose in range(4):
        ys=[max(v['steady_max_joint_delta_deg'] for v in values
                if v['pose']==pose and v['force_level_per_axis_n']==level) for level in levels]
        axes[0].plot(levels,ys,marker='o',label=f'Pose {pose}')
    axes[0].set(xticks=levels,xticklabels=[f'{level:g}' for level in levels],
        xlabel='Force amplitude per axis (N)',ylabel='Max absolute mean joint response (deg)',
        title='Steady response, identical actions')
    axes[1].axvspan(2,4,alpha=.1,color='gray')
    axes[1].set(xlabel='Time (s)',ylabel='Max absolute joint difference (deg)',title='Pose 0: force applied at 2–4 s')
    for ax in axes: ax.grid(alpha=.2);ax.legend(fontsize=8)
    fig.tight_layout();fig.savefig(output/'response.png',dpi=180);plt.close(fig)
    result={'saved_tape_cpu_recomputation_passed':True,'loaded_pairs':len(values),'zero_pairs':len(zeros),
        'force_levels_per_axis_n':levels,
        'steady_max_joint_delta_deg_range':[min(v['steady_max_joint_delta_deg'] for v in values),max(v['steady_max_joint_delta_deg'] for v in values)],
        'steady_base_xy_delta_mm_range':[min(v['steady_base_xy_delta_mm'] for v in values),max(v['steady_base_xy_delta_mm'] for v in values)],
        'loaded_effort_limit_fraction_max':max(v['loaded_effort_limit_fraction_max'] for v in values),
        'pre_force_joint_difference_max_deg':max(v['pre_force_joint_delta_max_deg'] for v in r['pairs']),
        'zero_pair_steady_joint_difference_max_deg':max(v['steady_max_joint_delta_deg'] for v in zeros),
        'per_pose_steady_joint_delta_deg':{str(p):[max(v['steady_max_joint_delta_deg'] for v in values
            if v['pose']==p and v['force_level_per_axis_n']==level) for level in levels] for p in range(4)},
        'per_pose_max_channel_delta_over_noise_std':{str(p):[max(v['steady_arm_position_delta_over_noise_std'])
            for v in values if v['pose']==p] for p in range(4)}}
    target.write_text(json.dumps(result,indent=2)+'\n')
    shutil.copyfile(__file__,output/'summary_snapshot.py')
    print('FORCE_RESPONSE_SUMMARY_PASS',json.dumps(result),flush=True)


def auxiliary_metrics(pred, target):
    """Actual four-task MSEs and the established force diagnostics (no /64)."""
    import torch
    p, vf = pred[:,6:9]*100, target[:,6:9]*100
    active, zero = vf.norm(dim=-1)>1, vf.norm(dim=-1)<.05
    labels = ('base_velocity_loss','gripper_pos_loss','force_ee_loss','force_base_loss')
    mse = (pred-target).square().mean(0).reshape(4,3).mean(1)
    weighted = mse * mse.new_tensor([.2,.2,1.,1.]).square()
    return {'force_rmse_per_axis_n':float((p-vf).square().mean().sqrt()),
        'force_rmse_xyz_n':(p-vf).square().mean(0).sqrt().tolist(),
        'active_vector_error_n':float((p[active]-vf[active]).norm(dim=-1).mean()),
        'zero_estimate_norm_n':float(p[zero].norm(dim=-1).mean()),
        'zero_mean_vector_n':p[zero].mean(0).tolist(),
        'auxiliary_mse':dict(zip(labels,mse.tolist())),
        'auxiliary_weighted_mse':dict(zip(labels,weighted.tolist())),
        'supervised_total_loss':float(weighted.sum())}


def restore_diagnostic_learner(algorithm, source):
    """Restore both existing Adams with independent tensors and verify ordering."""
    import copy
    import torch
    model = algorithm.actor_critic
    model.load_state_dict(source['model_state_dict'], strict=True)
    checks = {}
    for name, optimizer, key in (
            ('ppo', algorithm.optimizer, 'optimizer_state_dict'),
            ('supervision', algorithm.adaptation_module_optimizer, 'adaptation_optimizer_state_dict')):
        optimizer.load_state_dict(copy.deepcopy(source[key]))
        actual = optimizer.state_dict()
        assert actual['param_groups'] == source[key]['param_groups']
        assert actual['state'].keys() == source[key]['state'].keys()
        for pid, fields in actual['state'].items():
            for field, tensor in fields.items():
                expected = source[key]['state'][pid][field]
                if isinstance(tensor, torch.Tensor):
                    assert torch.equal(tensor.cpu(), expected.cpu())
                    assert tensor.data_ptr() != expected.data_ptr()
        for group in optimizer.param_groups:
            for parameter in group['params']:
                state = optimizer.state.get(parameter, {})
                for field in ('exp_avg', 'exp_avg_sq'):
                    if field in state: assert state[field].shape == parameter.shape
        checks[name] = dict(states=len(actual['state']), independent_tensors=True,
            steps=sorted({float(s['step']) for s in actual['state'].values()}))
    algorithm.learning_rate = float(source['learning_rate'])
    assert algorithm.optimizer.param_groups[0]['lr'] == algorithm.learning_rate
    return checks


def install_gym_control_audit(env, algorithm, args):
    """Disposable boundary instrumentation; never edits the native task or PPO."""
    import ast
    import __future__
    import math
    import torch
    from types import SimpleNamespace as NS
    checks = dict(history_max_abs=0., non_noise_frame_max_abs=0., goal_roundtrip_max_m=0., pd_equation_max_nm=0.)
    events, reward_terms, last_state = [], {}, {}
    if args.gym_sync_after_simulate:
        native = env.gym
        class SyncedGym:
            def __getattr__(self, name): return getattr(native, name)
            def fetch_results(self, *a, **kw): return None
            def simulate(self, sim):
                native.simulate(sim)
                native.fetch_results(sim, True)
        env.gym = SyncedGym()
    if args.gym_zero_external_force:
        push = env._push_gripper
        def no_external(*a, **kw):
            result = push(*a, **kw)
            env.forces[:, env.gripper_idx] = 0.
            return result
        env._push_gripper = no_external
    namespace = {'torch':torch, 'math':math,
        'copysign':lambda magnitude,sign:torch.copysign(torch.full_like(sign,magnitude),sign)}
    for path,name in ((ROOT/'IsaacLab/source/isaaclab/isaaclab/utils/math.py','euler_xyz_from_quat'),
            (ROOT/'unifp_observations.py','UniFPActorInputs')):
        node = next(n for n in ast.parse(path.read_text()).body if getattr(n,'name',None)==name)
        node.decorator_list=[]
        exec(compile(ast.Module(body=[node],type_ignores=[]),str(path),'exec',
            flags=__future__.annotations.compiler_flag),namespace)
    shadow = object.__new__(namespace['UniFPActorInputs'])
    shadow.num_envs=env.num_envs;shadow.num_actions=17;shadow.frame_size=73;shadow.with_gait=True
    shadow.joint_ids=shadow.position_ids=torch.arange(17)
    shadow.command_scales=env.commands_scale.clone()
    shadow.history=env.obs_buf.reshape(env.num_envs,32,73).clone()
    original_reset, original_observe = env.reset_idx, env.compute_observations
    def reset(ids):
        original_reset(ids)
        shadow.history[ids]=0.
    def observe():
        original_observe()
        shadow.gait_phase=env._get_phase();shadow.commands=env.commands
        robot=NS(data=NS(root_quat_w=env.base_quat[:,[3,0,1,2]],root_ang_vel_b=env.base_ang_vel,
            joint_pos=env.dof_pos,joint_vel=env.dof_vel,default_joint_pos=env.default_dof_pos))
        frame,flat=shadow.observe(robot,env.actions,add_noise=False)
        actual=env.obs_buf.reshape(env.num_envs,32,73)
        checks['non_noise_frame_max_abs']=max(checks['non_noise_frame_max_abs'],float((frame[:,39:]-actual[:,-1,39:]).abs().max()))
        # Copy ONLY the current frame's observed noise; reset padding stays zero.
        shadow.history[:,-1]=actual[:,-1]
        checks['history_max_abs']=max(checks['history_max_abs'],float((flat-env.obs_buf).abs().max()))
    env.reset_idx,env.compute_observations=reset,observe
    last_pd={}
    original_pd=env._compute_torques
    def pd(actions):
        torque=original_pd(actions)
        target=env.default_dof_pos.expand(env.num_envs,-1).clone()
        target[:,:17]+=actions*env.motor_strength*env.cfg.control.action_scale
        kp=torch.cat((env.p_gains,torch.tensor([64.,64.])))
        kd=torch.cat((env.d_gains,torch.tensor([1.5,1.5])))
        expected=torch.clip(kp*(target-env.dof_pos)-kd*env.dof_vel,-env.torque_limits,env.torque_limits)
        checks['pd_equation_max_nm']=max(checks['pd_equation_max_nm'],float((torque-expected).abs().max()))
        last_pd.update(pd_target=target,pd_position=env.dof_pos.clone(),pd_velocity=env.dof_vel.clone(),
            applied_action=actions.clone(),motor_strength=env.motor_strength.clone())
        return torque
    env._compute_torques=pd
    for i,(name,function) in enumerate(zip(env.reward_names,env.reward_functions)):
        def measured(function=function,name=name):
            result=function();reward_terms[name]=torch.as_tensor(result).detach().clone();return result
        env.reward_functions[i]=measured
    from isaacgym.torch_utils import quat_rotate_inverse, quat_apply
    original_reward=env.compute_reward
    def reward():
        original_reward()
        center=env.get_ee_goal_spherical_center()
        local=quat_rotate_inverse(env.base_yaw_quat,env.curr_ee_goal_cart_world-center)
        checks['goal_roundtrip_max_m']=max(checks['goal_roundtrip_max_m'],float((local-env.curr_ee_goal_cart).abs().max()))
        last_state.update(root_state=env.root_states.clone(),joint_position=env.dof_pos.clone(),
            joint_velocity=env.dof_vel.clone(),requested_torque=env.torques.clone(),
            ee_position=env.ee_pos.clone(),goal_world=env.curr_ee_goal_cart_world.clone(),
            goal_local=local.clone(),force_world=env.forces[:,env.gripper_idx].clone(),
            command_force=env.current_Fxyz_gripper_cmd.clone(),episode_steps=env.episode_length_buf.clone(),
            base_rpy=env.base_euler_xyz.clone(),commands=env.commands.clone(),
            ee_local=quat_rotate_inverse(env.base_yaw_quat,env.ee_pos-center))
        last_state.update(last_pd)
    env.compute_reward=reward
    original_step=env.step
    def step(actions):
        obs,rewards,dones,infos=original_step(actions)
        current=env.time_out_buf.bool();given=infos.get('time_outs',torch.zeros_like(current)).bool()
        effective=current if args.gym_fresh_timeouts else given
        values=algorithm.transition.values
        row=dict(step=len(events),done_count=int(dones.sum()),current_timeout_count=int(current.sum()),
            native_info_timeout_count=int(given.sum()),stale_timeout_count=int((given & ~current).sum()),
            missing_timeout_count=int((current & ~given).sum()),effective_timeout_count=int(effective.sum()),
            reward_min=float(rewards.min()),reward_max=float(rewards.max()),
            root_z_mean=float(last_state['root_state'][:,2].mean()),
            joint_speed_max=float(last_state['joint_velocity'].abs().max()),
            ee_error_mean_m=float((last_state['ee_position']-last_state['goal_world']).norm(dim=-1).mean()),
            torque_limit_fraction=float((last_state['requested_torque'].abs()>=env.torque_limits-1e-5).float().mean()),
            reward_terms_mean={k:float(v.mean()) for k,v in reward_terms.items()})
        if values is not None:
            extra=algorithm.gamma*values.flatten()*effective
            wrong=algorithm.gamma*values.flatten()*(effective.float()-current.float())
            row.update(bootstrap_extra_abs_max=float(extra.abs().max()),
                incorrect_bootstrap_abs_sum=float(wrong.abs().sum()),
                stored_reward_abs_max=float((rewards+extra).abs().max()),
                native_info_timeout_mask=given.tolist(),current_timeout_mask=current.tolist(),
                raw_reward=rewards.tolist())
        events.append(row)
        if args.gym_fresh_timeouts: infos=dict(infos,time_outs=current.clone())
        return obs,rewards,dones,infos
    env.step=step
    return dict(checks=checks,events=events,last_state=last_state,
        interventions=dict(sync_after_simulate=args.gym_sync_after_simulate,
            zero_external_force=args.gym_zero_external_force,fresh_timeouts=args.gym_fresh_timeouts,
            action_mode=args.gym_control_action))


def official_shared_methods():
    """Load released task methods verbatim; do not import its simulator class."""
    import ast
    import hashlib
    import numpy as np
    import torch
    from isaacgym import gymtorch
    from isaacgym.torch_utils import quat_apply, quat_rotate_inverse, quat_from_euler_xyz, torch_rand_float
    helper_path=ROOT/'UniFP/legged_gym/utils/isaacgym_utils.py'
    helper=next(x for x in ast.parse(helper_path.read_text()).body if isinstance(x,ast.FunctionDef) and x.name=='sphere2cart')
    helper.decorator_list=[]
    helper_ns=dict(torch=torch,Tensor=torch.Tensor)
    exec(compile(ast.Module(body=[helper],type_ignores=[]),str(helper_path),'exec'),helper_ns)
    sphere2cart=helper_ns['sphere2cart']
    cfg_ns = dict(BaseConfig=object, np=np)
    for relative in ('base/legged_robot_config.py', 'b2/b2z1_pos_force_config.py'):
        path = ROOT/'UniFP/legged_gym/envs'/relative
        nodes = [x for x in ast.parse(path.read_text()).body if isinstance(x, ast.ClassDef)]
        exec(compile(ast.Module(body=nodes, type_ignores=[]), str(path), 'exec'), cfg_ns)
    path = ROOT/'UniFP/legged_gym/envs/b2/legged_robot_b2z1_pos_force.py'
    tree = ast.parse(path.read_text())
    cls = next(x for x in tree.body if isinstance(x, ast.ClassDef))
    nodes = {x.name:x for x in cls.body if isinstance(x, ast.FunctionDef)}
    ns = dict(torch=torch, np=np, gymtorch=gymtorch, quat_apply=quat_apply, quat_rotate_inverse=quat_rotate_inverse,
              quat_from_euler_xyz=quat_from_euler_xyz, torch_rand_float=torch_rand_float, sphere2cart=sphere2cart)
    for x in tree.body:
        if isinstance(x, ast.Assign) and any(isinstance(t, ast.Name) and t.id.startswith('INDEX_') for t in x.targets):
            exec(compile(ast.Module(body=[x], type_ignores=[]), str(path), 'exec'), ns)
    names = ['_push_gripper', '_push_robots', '_resample_commands', '_randomize_dof_props',
             '_resample_ee_goal', '_resample_ee_goal_sphere_once', '_resample_ee_goal_orn_once',
             'collision_check', 'update_curr_ee_goal', 'get_ee_goal_spherical_center', 'check_termination']
    names += [name for name in nodes if name.startswith('_reward_')]
    for name in names:
        exec(compile(ast.Module(body=[nodes[name]], type_ignores=[]), str(path), 'exec'), ns)
    # Only the force-buffer statements of released reset_idx are portable.
    # Keep the exact statements, including the source's asymmetric ext reset.
    body = nodes['reset_idx'].body
    start = next(i for i,x in enumerate(body) if ast.get_source_segment(path.read_text(),x).startswith('self.forces[env_ids, self.gripper_idx'))
    stop = next(i for i,x in enumerate(body) if i > start and any(isinstance(v,ast.Attribute) and v.attr=='extras' for v in ast.walk(x)))
    reset = ast.FunctionDef(name='reset_force_buffers', args=nodes['_resample_commands'].args,
                           body=body[start:stop], decorator_list=[])
    ast.fix_missing_locations(reset)
    exec(compile(ast.Module(body=[reset], type_ignores=[]), str(path), 'exec'), ns)
    hashes = {name:hashlib.sha256(ast.dump(nodes[name], include_attributes=False).encode()).hexdigest() for name in names}
    return ns, cfg_ns['B2Z1PosForceRoughCfg'], hashes


def install_ranger_official_shared(env, ns, official_dt):
    """Diagnostic-only bridge: source methods own portable task behavior.

    Body/joint selection, A1 target ranges, implicit drives and observation
    layout remain explicit morphology boundaries. No learner change.
    """
    import ast
    import copy
    import math
    import types
    import torch
    from types import SimpleNamespace as NS
    methods, cfg, hashes = official_shared_methods()
    n = env.num_envs
    def bind(obj, name):setattr(obj, name, types.MethodType(methods[name], obj))
    def yaw_xyzw():return ns['yaw_quat'](env.robot.data.root_quat_w)[:, [1,2,3,0]]
    s = NS(num_envs=n, device='cpu', cfg=cfg, commands=env.actor.commands,
           forces=torch.zeros(n,2,3), gripper_idx=0, robot_base_idx=1,
           current_Fxyz_gripper_cmd=torch.zeros(n,3), current_Fxyz_base_cmd=torch.zeros(n,3),
           episode_length_buf=env.episode_length_buf, settling_time_force_gripper=float(math.ceil(1./official_dt)))
    for location in ('gripper', 'base'):
        for stream in ('cmd', 'ext'):
            suffix=location+'_'+stream
            setattr(s,'push_interval_'+suffix,torch.randint(math.ceil(3.5/official_dt),math.ceil(9./official_dt),(n,1)))
            setattr(s,'freed_envs_'+suffix,torch.zeros(n,dtype=torch.bool))
            setattr(s,'selected_env_ids_'+suffix,torch.zeros(n,dtype=torch.long))
            setattr(s,'force_target_'+suffix,torch.zeros(n,3))
            setattr(s,'push_duration_'+suffix,torch.zeros(n))
            setattr(s,'push_end_time_'+suffix,torch.zeros(n))
            if location=='gripper':
                for field,seconds in (('push_interval_',(3.5,9.)),('push_duration_', (1.,3.))):
                    setattr(s,field+suffix+'_min',math.ceil(seconds[0]/official_dt))
                    setattr(s,field+suffix+'_max',math.ceil(seconds[1]/official_dt))
    for name in ('gripper_force_kps','gripper_force_kds','base_force_kps','base_force_kds'):
        setattr(s,name,torch.full((n,1),200.))
    bind(s,'_push_gripper');bind(s,'_randomize_dof_props')
    class Curriculum:
        def __init__(self):
            self.start_step=192001;self.enabled_steps=0;self.enabled_physics_updates=0
            self.command=NS(max_force_n=60.,value=s.commands[:,9:12],selected_count=0,peak_force_n=0.)
            self.external=NS(max_force_n=60.,value=s.forces[:,0],selected_count=0,peak_force_n=0.)
        def reset(self, ids):methods['reset_force_buffers'](s,ids)
        def update(self, global_policy_step, episode_steps, *, substep_index=0):
            s.episode_length_buf=episode_steps
            if global_policy_step>=self.start_step:
                before=[getattr(s,'selected_env_ids_gripper_'+stream).clone() for stream in ('cmd','ext')]
                s._push_gripper(env._all_ids)
                self.enabled_steps+=int(substep_index==0);self.enabled_physics_updates+=1
                for obj,stream,old in zip((self.command,self.external),('cmd','ext'),before):
                    obj.selected_count+=int(((getattr(s,'selected_env_ids_gripper_'+stream)==1)&(old==0)).sum())
                    obj.peak_force_n=max(obj.peak_force_n,float(obj.value.abs().max()))
            return self.command.value,self.external.value
        def summary(self):return dict(implementation='released _push_gripper and force reset block',
            configured_start_policy_step=self.start_step,configured_max_force_per_axis_n=60.,
            enabled_policy_steps=self.enabled_steps,enabled_physics_updates=self.enabled_physics_updates,
            command_peak_abs_n=self.command.peak_force_n,external_peak_abs_n=self.external.peak_force_n,
            command_pulses_selected=self.command.selected_count,external_pulses_selected=self.external.selected_count,
            interval_steps=[s.push_interval_gripper_cmd_min,s.push_interval_gripper_cmd_max],
            duration_steps=[s.push_duration_gripper_cmd_min,s.push_duration_gripper_cmd_max],
            settling_steps=s.settling_time_force_gripper,base_force_curriculum_enabled=False)
    env.curriculum=Curriculum()
    # The original keeps motors fixed over resets. Gain sampling is retained
    # even for constant ranges, so its actual RNG consumption is not omitted.
    motor_initial=env.domain.motor_strength.clone()
    def reset_motor(ids):
        assert torch.equal(env.domain.motor_strength,motor_initial)
    env.domain.resample_motor=reset_motor
    s.command_ranges={name:getattr(cfg.commands.ranges,name) for name in ('lin_vel_x','lin_vel_y','ang_vel_yaw')}
    def commands(ids):
        methods['_resample_commands'](s,ids)
        s._randomize_dof_props(ids)
    env._sample_velocity_commands=commands
    # Reuse spherical goal generation/trajectory/rejection with A1 geometry.
    old_goal=env.goal
    g=NS(num_envs=n,device='cpu',cfg=cfg,commands=env.actor.commands,global_steps=env.global_policy_steps,
         play=False,stop_update_goal=False,goal_timer=torch.zeros(n),
         traj_timesteps=(1.+2.*torch.rand(n))/official_dt,
         ee_start_sphere=torch.zeros(n,3),ee_goal_sphere=torch.zeros(n,3),ee_goal_cart=torch.zeros(n,3),
         curr_ee_goal_sphere=torch.zeros(n,3),curr_ee_goal_cart=torch.zeros(n,3),
         curr_ee_goal_cart_world=torch.zeros(n,3),ee_goal_orn_delta_rpy=torch.zeros(n,3),
         init_start_ee_sphere=old_goal._initial[None],init_end_ee_sphere=old_goal._first_goal[None],
         ee_goal_center_offset=old_goal._offset.expand(n,-1),collision_lower_limits=old_goal._lower,
         collision_upper_limits=old_goal._upper,underground_limit=-.7,num_collision_check_samples=10,
         collision_check_t=torch.linspace(0,1,10)[None,None,:])
    g.traj_total_timesteps=g.traj_timesteps+(.5+1.5*torch.rand(n))/official_dt
    g.goal_ee_ranges=dict(pos_l=[float(old_goal._goal_lower[0]),float(old_goal._goal_upper[0])],
        pos_p=[float(old_goal._goal_lower[1]),float(old_goal._goal_upper[1])],
        pos_y=[float(old_goal._goal_lower[2]),float(old_goal._goal_upper[2])],
        delta_orn_r=[-.5,.5],delta_orn_p=[-.5,.5],delta_orn_y=[-.5,.5])
    for name in ('_resample_ee_goal','_resample_ee_goal_sphere_once','_resample_ee_goal_orn_once',
                 'collision_check','get_ee_goal_spherical_center'):bind(g,name)
    def sync_goal():
        g.root_states=torch.cat((env.robot.data.root_pos_w,env.robot.data.root_quat_w[:,[1,2,3,0]],env.robot.data.root_vel_w),-1)
        g.base_yaw_quat=yaw_xyzw();g.ee_pos=env.robot.data.body_pos_w[:,env.gripper_id]
        g.global_steps=env.global_policy_steps
    class Goal:
        schedule=None;schedule_index=0;resample_count=0;rejected_count=0
        def __init__(self):
            self.current=g.curr_ee_goal_sphere;self.orientation_delta=g.ee_goal_orn_delta_rpy
            self.goal_world=g.curr_ee_goal_cart_world
        def center_world(self,robot):sync_goal();return g.get_ee_goal_spherical_center()
        def reset(self,ids):sync_goal();g._resample_ee_goal(ids,is_init=True)
        def update(self,robot,cmd,env_ids=None,*,advance=True):
            sync_goal()
            if advance:
                methods['update_curr_ee_goal'](g)
                self.goal_world=g.curr_ee_goal_cart_world
            else:
                # Initial/reset observations must not advance other histories
                # or goal timers. Execute the same source on a sliced facade.
                ids=env._all_ids if env_ids is None else env_ids
                sub=copy.copy(g);sub.num_envs=len(ids)
                for key in ('commands','goal_timer','traj_timesteps','traj_total_timesteps','ee_start_sphere',
                            'ee_goal_sphere','curr_ee_goal_sphere','curr_ee_goal_cart','ee_goal_orn_delta_rpy',
                            'root_states','base_yaw_quat','ee_goal_center_offset'):
                    setattr(sub,key,getattr(g,key)[ids].clone())
                sub._resample_ee_goal=lambda indices:None
                sub.get_ee_goal_spherical_center=types.MethodType(methods['get_ee_goal_spherical_center'],sub)
                methods['update_curr_ee_goal'](sub)
                for key in ('commands','curr_ee_goal_sphere','curr_ee_goal_cart'):
                    getattr(g,key)[ids]=getattr(sub,key)
                g.curr_ee_goal_cart_world[ids]=sub.curr_ee_goal_cart_world
                self.goal_world=g.curr_ee_goal_cart_world
    env.goal=Goal()
    # Preserve the existing 17 applicable rewards. Only hard-coded leg/arm
    # slices need morphology mapping (12->8 base actions; 17->14 total).
    r=env.rewards
    local_reward=r.compute
    reward_cfg=NS(**{k:getattr(cfg.rewards,k) for k in dir(cfg.rewards) if not k.startswith('_')})
    reward_cfg.base_height_target=ns['ROOT_HEIGHT']
    reward_state=NS(cfg=NS(rewards=reward_cfg,commands=cfg.commands),num_envs=n,device='cpu',dt=official_dt,
        gripper_idx=0,robot_base_idx=1,gripper_force_kps=s.gripper_force_kps,base_force_kds=s.base_force_kds,
        penalised_contact_indices=r.penalized_ids)
    functions={}
    class Slices(ast.NodeTransformer):
        def visit_Slice(self,node):
            self.generic_visit(node)
            for field in ('lower','upper'):
                value=getattr(node,field)
                if isinstance(value,ast.Constant) and value.value in (12,17):
                    setattr(node,field,ast.copy_location(ast.Constant({12:8,17:14}[value.value]),value))
            return node
    for name in r.scales:
        f=methods['_reward_'+name]
        if name in ('torques','dof_vel','dof_acc','dof_vel_arm','dof_acc_arm','action_rate','action_rate_arm','dof_pos_limits'):
            source=ast.parse((ROOT/'UniFP/legged_gym/envs/b2/legged_robot_b2z1_pos_force.py').read_text())
            node=next(x for c in source.body if isinstance(c,ast.ClassDef) for x in c.body if isinstance(x,ast.FunctionDef) and x.name==f.__name__)
            node=Slices().visit(node);ast.fix_missing_locations(node)
            mapped=dict(methods);exec(compile(ast.Module(body=[node],type_ignores=[]),str(ROOT/'ranger_unifp_vec_env.py'),'exec'),mapped)
            f=mapped[f.__name__]
        functions[name]=f
    def reward(robot,feet,contacts,controller,actions,torques,cmd,goal,force,base_force,frame,slices):
        st=reward_state;st.commands=cmd;st.forces=torch.stack((force,base_force),1)
        st.current_Fxyz_gripper_cmd=cmd[:,9:12];st.current_Fxyz_base_cmd=cmd[:,12:15]
        st.base_yaw_quat=yaw_xyzw();st.curr_ee_goal_cart_world=goal.goal_world
        st.ee_pos=robot.data.body_pos_w[:,env.gripper_id];st.base_lin_vel=robot.data.root_lin_vel_b
        st.base_ang_vel=robot.data.root_ang_vel_b;st.root_states=torch.cat((robot.data.root_pos_w,torch.zeros(n,10)),-1)
        st.torques=torques[:,controller.action_indices];st.dof_vel=robot.data.joint_vel[:,controller.action_indices]
        st.last_dof_vel=r.prev_vel;st.actions=actions;st.last_actions=r.prev_actions
        st.contact_forces=contacts.data.net_forces_w
        st.dof_pos=robot.data.joint_pos[:,controller.action_indices].clone()
        limits=torch.zeros(14,2);limits[controller.position_action_indices]=r.soft_pos_limits
        st.dof_pos[:,4:8]=0.;st.dof_pos_limits=limits
        terms={}
        for name,f in functions.items():
            if name=='torque_limits':
                value=f(NS(torques=torques,torque_limits=r.effort_limits,cfg=st.cfg))
            else:value=f(st)
            terms[name]=torch.as_tensor(value).expand(n)*r.scales[name]*official_dt
        total=torch.stack(list(terms.values())).sum(0)
        assert torch.isfinite(total).all()
        r.prev_vel[:]=st.dof_vel;r.prev_actions[:]=actions;r.step_count+=n
        for name,value in terms.items():r.term_sums[name]+=float(value.sum())
        r.total_sum+=float(total.sum())
        return total,terms
    env.rewards.compute=reward
    # Reuse the termination guards with the actual source runtime's ceil.
    maximum=math.ceil(float(cfg.env.episode_length_s)/official_dt)
    def termination(robot,*,safety_height=False,contact_forces=None):
        assert not safety_height
        roll,pitch,_=ns['euler_xyz_from_quat'](robot.data.root_quat_w)
        t=NS(contact_forces=torch.zeros(n,0,3),termination_contact_indices=[],
             base_euler_xyz=torch.stack((roll,pitch,roll*0),-1),episode_length_buf=env.episode_length_buf,
             max_episode_length=maximum)
        methods['check_termination'](t)
        r.last_termination_masks=dict(termination_contact=torch.zeros(n,dtype=torch.bool),
            roll=roll.abs()>.8,pitch=pitch.abs()>1.,timeout=t.time_out_buf,safety_height=torch.zeros(n,dtype=torch.bool))
        for key,value in r.last_termination_masks.items():r.termination_counts[key]+=int(value.sum())
        return t.reset_buf,t.time_out_buf
    env.rewards.termination=termination
    # Inline push implementation is replaced only in this opt-in extracted
    # method; source task and all default diagnostic paths stay untouched.
    tree=ast.parse((ROOT/'unifp_vec_env.py').read_text())
    step=next(m for c in tree.body if isinstance(c,ast.ClassDef) and c.name=='UniFPVecEnv'
              for m in c.body if isinstance(m,ast.FunctionDef) and m.name=='step')
    push=next(x for x in step.body if isinstance(x,ast.If) and any(isinstance(v,ast.Attribute) and v.attr=='push_robots_enabled' for v in ast.walk(x.test)))
    push.body=ast.parse('self._released_push_robots()').body
    push.test=ast.parse('self.push_robots_enabled and (self._shared_common_step_counter + 1) % self.push_interval_steps == 0',mode='eval').body
    step.body.remove(push)
    sample_index=next(i for i,x in enumerate(step.body) if isinstance(x,ast.Expr) and isinstance(x.value,ast.Call)
                      and isinstance(x.value.func,ast.Attribute) and x.value.func.attr=='_sample_velocity_commands')
    step.body.insert(sample_index+1,push)
    step.body.insert(-1,ast.parse('self._shared_common_step_counter += 1').body[0])
    ast.fix_missing_locations(step)
    step_ns=dict(ns);exec(compile(ast.Module(body=[step],type_ignores=[]),str(ROOT/'unifp_vec_env.py'),'exec'),step_ns)
    env.step=types.MethodType(step_ns['step'],env)
    env._shared_common_step_counter=0
    def push_robots():
        handles=env.diagnostic_gym_handles
        root=torch.cat((env.robot.data.root_pos_w,env.robot.data.root_quat_w[:,[1,2,3,0]],env.robot.data.root_vel_w),-1)
        from isaacgym import gymtorch
        bridge=NS(cfg=cfg,device='cpu',num_envs=n,commands=env.actor.commands,root_states=root,
            sim=handles.sim,gym=NS(set_actor_root_state_tensor=lambda sim,tensor:env.robot.write_root_velocity_to_sim(root[:,7:13])))
        methods['_push_robots'](bridge)
        env.push_count+=n;env.push_peak_velocity=max(env.push_peak_velocity,float(root[:,7:9].abs().max()))
    env._released_push_robots=push_robots
    env.push_interval_steps=math.ceil(8./official_dt)
    # The generic step clears command force slots each policy tick; released
    # pulses retain their values on hold ticks. Restore the source buffer at
    # each update, separately from the actor command view.
    s.commands=s.commands.clone()
    env.curriculum.command.value=s.commands[:,9:12]
    # Commands/goal bridge must keep writing the actor's live tensor; pulse
    # code owns only its force slots in a private persistent command buffer.
    sample=env._sample_velocity_commands
    def sample_commands(ids):
        saved=s.commands;s.commands=env.actor.commands
        try:sample(ids)
        finally:s.commands=saved
    env._sample_velocity_commands=sample_commands
    env.shared_contract=dict(official_dt=official_dt,max_episode_length=maximum,
        verbatim_method_ast_sha256=hashes,mapped_reward_slices={'base':[0,8],'arm':[8,14]},
        remaining_differences=['Ranger/A1 body and joint selection; 58x32 actor and 98x3 critic',
            'A1 joint gains/limits and implicit steering/arm, velocity wheel drives',
            'A1 goal center/ranges and home pose; flat ground and existing collision/solver settings',
            'Base-link COM object and mass/inertia adaptation; wheel contact semantics',
            'Morphology-specific state/reset/observation packing; CPU mixed learner and 128 environments'],
        motor_strength_constant_across_reset=True,initial_episode_lengths_randomized_in_training=True)
    env.shared_state=NS(pulse=s,goal=g,motor_initial=motor_initial,local_reward=local_reward)


def ranger_shared_contract_probe(args):
    """Deterministic differential checks on the real adapter entry points."""
    from isaacgym import gymapi
    import copy
    import torch
    root=args.probe_output.resolve();root.mkdir(parents=True,exist_ok=False)
    env,ns=gym_ranger_backend(8,140101,60.,official_shared=True)
    try:
        methods,cfg,hashes=official_shared_methods()
        pulse=env.shared_state.pulse;ref=copy.deepcopy(pulse)
        maxima=dict(pulse=0.,goal=0.,reward=0.)
        partial_resets=0
        for tick in range(1100):
            env.episode_length_buf[:]=tick
            ref.episode_length_buf=env.episode_length_buf.clone()
            if tick in (180,501,809):
                ids=torch.tensor([0,2,5]);env.curriculum.reset(ids)
                methods['reset_force_buffers'](ref,ids);partial_resets+=1
            for substep in range(4):
                before=torch.get_rng_state()
                methods['_push_gripper'](ref,env._all_ids)
                after=torch.get_rng_state();torch.set_rng_state(before)
                cmd,force=env.curriculum.update(192001+tick,env.episode_length_buf,substep_index=substep)
                assert torch.equal(torch.get_rng_state(),after)
                assert torch.equal(cmd,pulse.commands[:,9:12]) and torch.equal(force,pulse.forces[:,0])
                for key,value in vars(pulse).items():
                    if isinstance(value,torch.Tensor):
                        delta=float((value.double()-getattr(ref,key).double()).abs().max())
                        maxima['pulse']=max(maxima['pulse'],delta)
                        assert delta==0.,(tick,key,delta)
        # Goal interpolation, random resampling and collision rejection must
        # use exactly the same RNG sequence as the unmodified source methods.
        env.goal.center_world(env.robot)
        g=env.shared_state.goal;reference=copy.deepcopy(g)
        for tick in range(1100):
            before=torch.get_rng_state();methods['update_curr_ee_goal'](reference)
            after=torch.get_rng_state();torch.set_rng_state(before)
            env.goal.update(env.robot,env.actor.commands)
            assert torch.equal(torch.get_rng_state(),after)
            for key in ('curr_ee_goal_sphere','curr_ee_goal_cart_world','goal_timer',
                        'ee_goal_sphere','ee_start_sphere','ee_goal_orn_delta_rpy'):
                delta=float((getattr(g,key)-getattr(reference,key)).abs().max())
                maxima['goal']=max(maxima['goal'],delta);assert delta==0.,(tick,key,delta)
        ids=torch.tensor([1,4]);other=torch.tensor([0,2,3,5,6,7])
        timers=g.goal_timer.clone();commands_before=g.commands.clone()
        env.goal.reset(ids)
        reset_timers=g.goal_timer.clone()
        env.goal.update(env.robot,env.actor.commands,ids,advance=False)
        assert torch.equal(g.goal_timer,reset_timers)
        assert torch.equal(g.goal_timer[other],timers[other])
        assert torch.equal(g.commands[other],commands_before[other])
        for tick in range(32):
            actions=torch.randn(8,14);torques=torch.randn_like(env.robot.data.joint_pos)
            forces=torch.randn(8,3)*60.;zeros=torch.zeros(8,3)
            arguments=(env.robot,env.scene['feet'],env.scene['robot_contacts'],env.controller,
                actions,torques,env.actor.commands,env.goal,forces,zeros,torch.zeros(8,98),env.critic_slices)
            previous=(env.rewards.prev_vel.clone(),env.rewards.prev_actions.clone())
            _,expected=env.shared_state.local_reward(*arguments)
            env.rewards.prev_vel[:]=previous[0];env.rewards.prev_actions[:]=previous[1]
            _,actual=env.rewards.compute(*arguments)
            for key in expected:
                # The only numerical difference is the source runtime dt.
                delta=float((actual[key]-expected[key]*env.shared_contract['official_dt']/.02).abs().max())
                maxima['reward']=max(maxima['reward'],delta)
                assert torch.allclose(actual[key],expected[key]*env.shared_contract['official_dt']/.02,atol=1e-5,rtol=1e-5),(key,delta)
        for _ in range(4):env.domain.resample_motor(env._all_ids)
        assert torch.equal(env.domain.motor_strength,env.shared_state.motor_initial)
        result=dict(all_passed=True,max_absolute_difference=maxima,pulse_ticks=1100,pulse_substeps_per_tick=4,goal_ticks=1100,partial_goal_reset_checked=True,
            partial_force_resets=partial_resets,reward_fixtures=32,reward_terms=17,
            source_method_ast_sha256=hashes,contract=env.shared_contract,
            scope='Source/adapter differential checks, not a force-accuracy acceptance threshold')
        (root/'result.json').write_text(json.dumps(result,indent=2)+'\n')
        print('SHARED_CONTRACT_VERIFIED',maxima,flush=True)
    finally:env.close()


def gym_ranger_backend(num_envs, seed, max_force_n=15., measure_dof_forces=False, fixed_com=False,
                       init_before_prepare=True, official_shared=False):
    """Gym transport for existing Ranger task code, extracted without Kit imports.

    Only simulator I/O is implemented here. Observation, PD target equations,
    reset, task step, reward, goal, randomization and force code execute from
    the production sources, without rewriting their formulas.
    """
    from isaacgym import gymapi, gymtorch
    import torch
    import numpy as np
    import random
    import math
    import ast
    import __future__
    from types import SimpleNamespace as NS
    torch.set_num_threads(2)
    torch.manual_seed(seed); np.random.seed(seed); random.seed(seed)
    ns = dict(torch=torch,np=np,random=random,math=math,Path=Path,
        copysign=lambda mag,sign:torch.copysign(torch.full_like(sign,mag),sign))
    def extract(relative, names):
        path = ROOT/relative
        tree = ast.parse(path.read_text())
        selected = []
        for node in tree.body:
            if getattr(node,'name',None) in names:
                node.decorator_list = []
                selected.append(node)
            elif isinstance(node,(ast.Assign,ast.AnnAssign)):
                targets = node.targets if isinstance(node,ast.Assign) else [node.target]
                if any(isinstance(t,ast.Name) and t.id in names for t in targets): selected.append(node)
        found = {getattr(n,'name',None) for n in selected}
        exec(compile(ast.Module(body=selected,type_ignores=[]),str(path),'exec',
            flags=__future__.annotations.compiler_flag),ns)
        assert all(name in ns for name in names), (relative,names,found)
    extract('IsaacLab/source/isaaclab/isaaclab/utils/math.py',
        ['normalize','euler_xyz_from_quat','quat_from_euler_xyz','yaw_quat',
         'quat_apply','quat_apply_inverse','quat_apply_yaw'])
    extract('unifp_observations.py',['COMMAND_SCALES','UniFPActorInputs'])
    extract('unifp_domain_randomization.py',['UniFPDomainRandomization'])
    extract('unifp_force_curriculum.py',['OFFICIAL_START_POLICY_STEP','POLICY_DT','_ForcePulse','UniFPForceCurriculum'])
    extract('unifp_task_signals.py',['field_slices','sphere_to_cart','cart_to_sphere','UniFPEEGoal'])
    extract('unifp_task_rewards.py',['REWARD_SCALES','POLICY_DT','MAX_EPISODE_STEPS','UniFPTaskRewards'])
    ns.update(ARM_NAMES=['arm_joint'+str(i) for i in range(1,7)],
        ARM_EFFORT_LIMITS=dict(zip(['arm_joint'+str(i) for i in range(1,7)],[40.,40.,27.,7.,7.,7.])),
        PHYSICS_DT=.005,DECIMATION=4,ASSET_VERSION='v3_original',USD_PATH=Path('unused'),RangerSceneCfg=None)
    extract('ranger_unifp_vec_env.py',['ROOT_HEIGHT','CORNERS','ACTION_NAMES','ARM_HOME',
        'CRITIC_FIELDS','CRITIC_SLICES','CRITIC_SIZE','RangerJointPD','RangerPrivilegedInputs','RangerRewards'])
    ns['ACTION_JOINT_NAMES']=ns['ACTION_NAMES']
    extract('unifp_vec_env.py',['UniFPVecEnv'])
    extract('ranger_unifp_vec_env.py',['RangerUniFPVecEnv'])
    gym = gymapi.acquire_gym()
    lab_root=OUT/'gym_ranger_20261024/lab_transport_defaults'
    lab_metadata=json.loads((lab_root/'result.json').read_text())
    lab_properties=torch.load(lab_root/'shape_properties.pt',map_location='cpu')
    schema_path=Path('/var/local/sorry/conda/envs/isaaclab-unifp/lib/python3.11/site-packages/isaacsim/extscache/omni.usd.schema.physx-107.3.26+107.3.3.lx64.r.cp311.u353/plugins/PhysxSchema/resources/generatedSchema.usda')
    import re
    defaults={key:(value if value is not None else float(re.search(
        r'float physxRigidBody:'+key[0].lower()+key[1:]+r' = ([0-9.]+)',schema_path.read_text()).group(1)))
        for key,value in lab_metadata['rigid_body_schema_defaults'].items()}
    params = gymapi.SimParams()
    params.dt=.005; params.substeps=1; params.up_axis=gymapi.UP_AXIS_Z
    params.gravity=gymapi.Vec3(0,0,-9.81); params.use_gpu_pipeline=False
    params.physx.use_gpu=True; params.physx.solver_type=1
    params.physx.num_position_iterations=32; params.physx.num_velocity_iterations=1
    params.physx.rest_offset=0.
    params.physx.bounce_threshold_velocity=.5
    params.physx.friction_offset_threshold=.04
    params.physx.friction_correlation_distance=.025
    params.physx.max_depenetration_velocity=defaults['MaxDepenetrationVelocity']
    sim = gym.create_sim(0,-1,gymapi.SIM_PHYSX,params)
    assert sim
    plane=gymapi.PlaneParams(); plane.normal=gymapi.Vec3(0,0,1)
    plane.static_friction=plane.dynamic_friction=1.
    gym.add_ground(sim,plane)
    opts=gymapi.AssetOptions()
    opts.collapse_fixed_joints=True; opts.replace_cylinder_with_capsule=False
    opts.default_dof_drive_mode=gymapi.DOF_MODE_NONE; opts.use_mesh_materials=False
    opts.linear_damping=defaults['LinearDamping']; opts.angular_damping=defaults['AngularDamping']
    asset_root=ROOT/'robot_description/a1arm_description/urdf'
    asset=gym.load_asset(sim,str(asset_root),'a1arm_rgm3_original_movable.urdf',opts)
    assert asset
    joint_names=gym.get_asset_dof_names(asset); body_names=gym.get_asset_rigid_body_names(asset)
    props=gym.get_asset_dof_properties(asset)
    shape_spans=gym.get_asset_rigid_body_shape_indices(asset)
    span_by_body=dict(zip(body_names,shape_spans))
    # Both importers retain the same collision XML and merge the same fixed
    # links. Map flattened Lab offsets by named body, then collision ordinal.
    lab_offsets={};cursor=0
    for name in lab_metadata['body_names']:
        count=int(span_by_body[name].count)
        lab_offsets[name]=lab_properties['contact_offsets'][0,cursor:cursor+count]
        cursor+=count
    assert cursor==lab_properties['contact_offsets'].numel()
    q0=torch.zeros(len(joint_names))
    for name,value in zip(ns['ARM_NAMES'],ns['ARM_HOME']): q0[joint_names.index(name)]=value
    kp=torch.full_like(q0,20.); kd=torch.full_like(q0,2.); limits=torch.full_like(q0,10.)
    for i,name in enumerate(joint_names):
        mode=gymapi.DOF_MODE_POS
        if 'steering' in name: kp[i]=300.; kd[i]=20.; limits[i]=35.
        elif 'drive' in name: kp[i]=0.; kd[i]=20.; limits[i]=80.; mode=gymapi.DOF_MODE_VEL
        elif name in ns['ARM_NAMES']: kp[i]=80.; kd[i]=4.; limits[i]=ns['ARM_EFFORT_LIMITS'][name]
        props['driveMode'][i]=mode
    props['stiffness']=kp.numpy(); props['damping']=kd.numpy(); props['effort']=limits.numpy()
    envs=[]; actors=[]
    for i in range(num_envs):
        env=gym.create_env(sim,gymapi.Vec3(-2,-2,0),gymapi.Vec3(2,2,2),int(math.ceil(math.sqrt(num_envs))))
        pose=gymapi.Transform(); pose.p=gymapi.Vec3(0,0,.32)
        actor=gym.create_actor(env,asset,pose,'ranger',i,1)
        if measure_dof_forces: gym.enable_actor_dof_force_sensors(env,actor)
        shape_props=gym.get_actor_rigid_shape_properties(env,actor)
        for name,span in span_by_body.items():
            for ordinal in range(span.count):
                shape_props[span.start+ordinal].contact_offset=float(lab_offsets[name][ordinal])
                shape_props[span.start+ordinal].rest_offset=0.
                shape_props[span.start+ordinal].friction=1.
        gym.set_actor_rigid_shape_properties(env,actor,shape_props)
        gym.set_actor_dof_properties(env,actor,props)
        state=np.zeros(len(joint_names),dtype=gymapi.DofState.dtype); state['pos']=q0.numpy()
        gym.set_actor_dof_states(env,actor,state,gymapi.STATE_ALL)
        gym.set_actor_dof_position_targets(env,actor,q0.numpy())
        gym.set_actor_dof_velocity_targets(env,actor,np.zeros(len(joint_names),np.float32))
        envs.append(env);actors.append(actor)
    sim_prepared=False
    class BodyView:
        # Implements just the init-time Lab domain randomizer property API.
        def __init__(self):
            self.ps=[gym.get_actor_rigid_body_properties(e,a) for e,a in zip(envs,actors)]
            self.ms=[gym.get_actor_rigid_shape_properties(e,a) for e,a in zip(envs,actors)]
        def read_bodies(self):
            self.ps=[gym.get_actor_rigid_body_properties(e,a) for e,a in zip(envs,actors)]
            return self.ps
        def get_masses(self): return torch.tensor([[p.mass for p in ps] for ps in self.read_bodies()])
        def get_coms(self): return torch.tensor([[[p.com.x,p.com.y,p.com.z,0.,0.,0.,1.] for p in ps] for ps in self.read_bodies()])
        def get_inertias(self): return torch.tensor([[[getattr(getattr(p.inertia,r),c) for r in 'xyz' for c in 'xyz'] for p in ps] for ps in self.read_bodies()])
        def get_material_properties(self):
            self.ms=[gym.get_actor_rigid_shape_properties(e,a) for e,a in zip(envs,actors)]
            return torch.tensor([[[p.friction,p.friction,p.restitution] for p in ps] for ps in self.ms])
        def set_masses(self,values,ids):
            assert not (init_before_prepare and sim_prepared), 'Rigid properties must be initialized before prepare_sim'
            for i in ids.tolist():
                for j,p in enumerate(self.ps[i]):p.mass=float(values[i,j])
                gym.set_actor_rigid_body_properties(envs[i],actors[i],self.ps[i],False)
        def set_coms(self,values,ids):
            assert not (init_before_prepare and sim_prepared), 'COM must be initialized before prepare_sim'
            # Keep the production randomizer and every RNG draw. Intervene at
            # simulator I/O before it reads back the realized privileged COM.
            if fixed_com:
                values=values.clone()
                values[:,body_names.index('base_link'),:3]=baseline_com[:,body_names.index('base_link'),:3]
            for i in ids.tolist():
                for j,p in enumerate(self.ps[i]):p.com=gymapi.Vec3(*values[i,j,:3].tolist())
                gym.set_actor_rigid_body_properties(envs[i],actors[i],self.ps[i],False)
        def set_inertias(self,values,ids):
            assert not (init_before_prepare and sim_prepared), 'Inertia must be initialized before prepare_sim'
            for i in ids.tolist():
                for j,p in enumerate(self.ps[i]):
                    m=values[i,j].view(3,3)
                    inertia=gymapi.Mat33()
                    inertia.x=gymapi.Vec3(*m[0].tolist())
                    inertia.y=gymapi.Vec3(*m[1].tolist())
                    inertia.z=gymapi.Vec3(*m[2].tolist())
                    p.inertia=inertia
                gym.set_actor_rigid_body_properties(envs[i],actors[i],self.ps[i],False)
        def set_material_properties(self,values,ids):
            assert not (init_before_prepare and sim_prepared), 'Materials must be initialized before prepare_sim'
            for i in ids.tolist():
                for j,p in enumerate(self.ms[i]): p.friction=float(values[i,j,0]);p.restitution=float(values[i,j,2])
                gym.set_actor_rigid_shape_properties(envs[i],actors[i],self.ms[i])
    body_view=BodyView()
    # Preserve the original baseline before applying any randomized property.
    baseline_com=body_view.get_coms()
    baseline_inertia=body_view.get_inertias()
    baseline_mass=body_view.get_masses()
    staged_domain=None
    if init_before_prepare:
        # Execute the existing randomizer once, at its required Gym boundary.
        # Neither RangerJointPD nor UniFPActorInputs draws RNG before the
        # production domain constructor. Its only controller dependency here
        # is the number of actions; all subsequent goal/reset RNG is retained.
        staged_domain=ns['UniFPDomainRandomization'](
            NS(root_physx_view=body_view,body_names=body_names),
            NS(action_indices=torch.arange(len(ns['ACTION_NAMES']))),
            NS(num_envs=num_envs,device='cpu'),enabled=True,
            com_body='base_link',gripper_body='arm_seg6')
    gym.prepare_sim(sim)
    sim_prepared=True
    roots=gymtorch.wrap_tensor(gym.acquire_actor_root_state_tensor(sim))
    dof=gymtorch.wrap_tensor(gym.acquire_dof_state_tensor(sim)).view(num_envs,len(joint_names),2)
    rb=gymtorch.wrap_tensor(gym.acquire_rigid_body_state_tensor(sim)).view(num_envs,len(body_names),13)
    contacts=gymtorch.wrap_tensor(gym.acquire_net_contact_force_tensor(sim)).view(num_envs,len(body_names),3)
    sensed_effort=(gymtorch.wrap_tensor(gym.acquire_dof_force_tensor(sim)).view(num_envs,len(joint_names))
        if measure_dof_forces else None)
    forces=torch.zeros(num_envs,len(body_names),3); moments=torch.zeros_like(forces)
    pos_target=q0.expand(num_envs,-1).clone(); vel_target=torch.zeros_like(pos_target)
    class Robot:
        def __init__(self):
            self.joint_names=joint_names;self.body_names=body_names
            default=torch.zeros(num_envs,13);default[:,2]=.32;default[:,3]=1.
            self.data=NS(joint_pos=dof[:,:,0],joint_vel=dof[:,:,1],
                default_joint_pos=q0.expand(num_envs,-1).clone(),default_joint_vel=torch.zeros_like(pos_target),
                default_root_state=default,joint_pos_limits=torch.tensor(np.stack((props['lower'],props['upper']),-1)).unsqueeze(0),
                applied_torque=torch.zeros_like(pos_target))
            self.root_physx_view=body_view
        def refresh(self):
            gym.refresh_dof_state_tensor(sim);gym.refresh_actor_root_state_tensor(sim)
            gym.refresh_rigid_body_state_tensor(sim);gym.refresh_net_contact_force_tensor(sim)
            if measure_dof_forces:
                gym.refresh_dof_force_tensor(sim)
                self.data.measured_dof_force=sensed_effort
            d=self.data;d.root_pos_w=roots[:,:3];d.root_quat_w=roots[:,[6,3,4,5]]
            d.root_vel_w=roots[:,7:13];d.body_pos_w=rb[:,:,:3]
            d.body_quat_w=rb[:,:,[6,3,4,5]];d.body_vel_w=rb[:,:,7:13]
            d.root_lin_vel_b=ns['quat_apply_inverse'](d.root_quat_w,roots[:,7:10])
            d.root_ang_vel_b=ns['quat_apply_inverse'](d.root_quat_w,roots[:,10:13])
            d.projected_gravity_b=ns['quat_apply_inverse'](d.root_quat_w,torch.tensor([0.,0.,-1.]).expand(num_envs,-1))
        def set_joint_position_target(self,target):pos_target.copy_(target)
        def set_joint_velocity_target(self,target):
            vel_target.copy_(target)
            self.data.applied_torque=torch.clamp(kp*(pos_target-dof[:,:,0])+kd*(vel_target-dof[:,:,1]),-limits,limits)
        def set_joint_effort_target(self,target):assert torch.count_nonzero(target)==0
        def set_external_force_and_torque(self,*,forces,torques,body_ids,is_global):
            assert is_global
            # This API replaces the prior wrench each physics substep.
            external_forces.zero_();external_forces[:,body_ids]=forces
            moments.zero_();moments[:,body_ids]=torques
        def write_root_pose_to_sim(self,pose,env_ids):
            roots[env_ids,:3]=pose[:,:3];roots[env_ids,3:7]=pose[:,[4,5,6,3]]
            ids=env_ids.to(torch.int32)
            gym.set_actor_root_state_tensor_indexed(sim,gymtorch.unwrap_tensor(roots),gymtorch.unwrap_tensor(ids),len(ids))
            self.refresh()
        def write_root_velocity_to_sim(self,velocity,env_ids=None):
            if env_ids is None:env_ids=torch.arange(num_envs)
            roots[env_ids,7:13]=velocity;ids=env_ids.to(torch.int32)
            gym.set_actor_root_state_tensor_indexed(sim,gymtorch.unwrap_tensor(roots),gymtorch.unwrap_tensor(ids),len(ids))
            self.refresh()
        def write_joint_state_to_sim(self,q,dq,env_ids):
            dof[env_ids,:,0]=q;dof[env_ids,:,1]=dq;ids=env_ids.to(torch.int32)
            gym.set_dof_state_tensor_indexed(sim,gymtorch.unwrap_tensor(dof),gymtorch.unwrap_tensor(ids),len(ids))
            self.refresh()
    external_forces=forces
    robot=Robot();robot.refresh()
    lab_indices=[lab_metadata['body_names'].index(name) for name in body_names]
    baseline_differences=dict(mass_kg=float((baseline_mass-lab_properties['masses'][:,lab_indices]).abs().max()),
        com_xyz_m=float((baseline_com[:,:,:3]-lab_properties['coms'][:,lab_indices,:3]).abs().max()),
        inertia_kg_m2=float((baseline_inertia-lab_properties['inertias'][:,lab_indices]).abs().max()))
    assert max(baseline_differences.values())<2e-6,baseline_differences
    class Scene:
        def __init__(self):
            self.num_envs=num_envs;self.device='cpu'
            # Gym API environment placement is global, but CPU tensor root and
            # rigid body states are environment-local. Keep all task vectors
            # in that same local world frame, including reset positions.
            self.gym_grid_origins=torch.tensor([[gym.get_env_origin(e).x,gym.get_env_origin(e).y,
                gym.get_env_origin(e).z] for e in envs])
            assert roots[:,:2].abs().max()<.01
            self.env_origins=torch.zeros(num_envs,3)
            self.items={'feet':NS(body_names=body_names,data=NS(net_forces_w=contacts)),
                        'robot_contacts':NS(body_names=body_names,data=NS(net_forces_w=contacts))}
        def __getitem__(self,key):return self.items[key]
        def reset(self,ids):
            external_forces[ids]=0.;moments[ids]=0.
            pos_target[ids]=robot.data.joint_pos[ids];vel_target[ids]=0.
        def write_data_to_sim(self):
            gym.set_dof_position_target_tensor(sim,gymtorch.unwrap_tensor(pos_target))
            gym.set_dof_velocity_target_tensor(sim,gymtorch.unwrap_tensor(vel_target))
            gym.apply_rigid_body_force_tensors(sim,gymtorch.unwrap_tensor(external_forces),gymtorch.unwrap_tensor(moments),gymapi.GLOBAL_SPACE)
        def update(self,dt):robot.refresh()
    class Simulation:
        def step(self):gym.simulate(sim);gym.fetch_results(sim,True)
        def clear_instance(self):gym.destroy_sim(sim)
    class RangerGym(ns['UniFPVecEnv']):
        num_single_obs=58;num_obs=1856;num_privileged_obs=294;num_pred_obs=12;num_actions=14
        critic_slices=ns['CRITIC_SLICES'];_create_task=ns['RangerUniFPVecEnv']._create_task
        def __init__(self):
            self.sim=Simulation();self.scene=Scene();self.robot=robot
            self.device='cpu';self.num_envs=num_envs;self._all_ids=torch.arange(num_envs)
            self.implicit_pd=True;self.capture_diagnostics=True
            if staged_domain is None:
                self._create_task(True,True,192001)
            else:
                constructor=ns['UniFPDomainRandomization']
                def use_staged(robot_arg,controller_arg,scene_arg,**kw):
                    assert robot_arg is robot and scene_arg is self.scene
                    assert len(controller_arg.action_indices)==staged_domain.num_motors
                    assert kw==dict(enabled=True,com_body='base_link',gripper_body='arm_seg6')
                    return staged_domain
                ns['UniFPDomainRandomization']=use_staged
                try:self._create_task(True,True,192001)
                finally:ns['UniFPDomainRandomization']=constructor
            # Set both independent pulse streams before the first reset. No
            # extra RNG draw, observation call, or reward/learner change.
            self.curriculum.command.max_force_n=float(max_force_n)
            self.curriculum.external.max_force_n=float(max_force_n)
            self.force_curriculum_enabled=True;self.safety_height_termination=False;self.rough_terrain=False
            self.push_robots_enabled=True;self.push_interval_steps=400;self.max_push_vel_xy=.8
            self.push_count=0;self.push_peak_velocity=0.
            self.observation_noise=True;self.command_sampling=True
            self.zero_wrench=torch.zeros(num_envs,1,3);self.gripper_id=self.privileged.ee_id
            self.global_policy_steps=240000;self.episode_length_buf=self.rewards.episode_steps
            self.obs_buf=torch.zeros(num_envs,1856);self.privileged_obs_buf=torch.zeros(num_envs,294)
            self.obs_pred=torch.zeros(num_envs,12);self.rew_buf=torch.zeros(num_envs)
            self.reset_buf=torch.zeros(num_envs,dtype=torch.bool);self.extras={}
            self.transport=dict(physics_dt=.005,decimation=4,solver_iterations=[32,1],
                pipeline='GPU PhysX / CPU tensors and learner',self_collision=False,
                collapse_fixed_joints=True,replace_cylinder_with_capsule=False,
                rigid_body_defaults=defaults,baseline_mass_com_inertia_max_difference=baseline_differences,
                lab_property_evidence=str(lab_root),contact_offset_mapping='named body plus within-body collision ordinal',
                body_names=body_names,joint_names=joint_names,dof_properties={k:props[k].tolist() for k in props.dtype.names},
                fixed_com=fixed_com,rigid_property_initialization='before_prepare' if init_before_prepare else 'legacy_after_prepare',
                com_intervention='nominal base COM only; retain all randomizer draws' if fixed_com else 'original randomization',
                limitations=['Gym and Lab PhysX versions/collision cooking are different',
                    'Within-body merged collision ordinal was assumed from the same URDF, not geometrically certified',
                    'Gym drive torque reward uses the same clamped PD estimate as Lab implicit actuator, not measured force',
                    'CPU pipeline uses environment-local world coordinates'])
            self.diagnostic_gym_handles=NS(gym=gym,sim=sim,envs=envs,actors=actors)
            if official_shared:
                assert max_force_n==60. and init_before_prepare
                install_ranger_official_shared(self,ns,float(params.dt)*4)
                self.transport['official_shared']=self.shared_contract
            self.reset()
    return RangerGym(),ns


def diagnostic_action_noise(actions, model, generator, args, arm_start):
    """Frozen rollout intervention only; never changes learned std or task RNG."""
    import math
    import torch
    scale=args.gym_action_noise_scale
    if scale is None:scale=1. if args.gym_ranger_sample_actions else 0.
    assert math.isfinite(scale) and 0. <= scale <= 1.
    group=args.gym_action_noise_group
    assert group in ('all','arm','base','steer','wheel')
    noise=torch.randn(actions.shape,generator=generator)*model.std
    if group=='arm':noise[:,:arm_start]=0.
    elif group=='base':noise[:,arm_start:]=0.
    elif group=='steer':
        assert arm_start==8
        noise[:,4:]=0.
    elif group=='wheel':
        assert arm_start==8
        noise[:,:4]=0.;noise[:,8:]=0.
    return actions+noise*scale


def gym_ranger_diagnostic(args):
    """Finite Ranger Gym evaluation/training, reusing the official PPO loop."""
    from isaacgym import gymapi
    import torch
    import hashlib
    import shutil
    import time
    import traceback
    import copy
    output=args.probe_output.resolve();output.mkdir(parents=True,exist_ok=False)
    shutil.copy2(__file__,output/'audit_snapshot.py')
    sha=lambda p:hashlib.sha256(Path(p).read_bytes()).hexdigest()
    protected_paths=[ROOT/'logs'/CHECKPOINTS[10000]]+[
        ROOT/p for p in ('ranger_unifp_vec_env.py','unifp_vec_env.py','unifp_observations.py',
            'unifp_force_curriculum.py','unifp_task_rewards.py','unifp_task_signals.py','unifp_domain_randomization.py',
            'robot_description/a1arm_description/urdf/a1arm_rgm3_original_movable.urdf',
            'UniFP/legged_gym/b2_gym_learn/ppo_cse_pf/actor_critic.py',
            'UniFP/legged_gym/b2_gym_learn/ppo_cse_pf/ppo.py',
            'UniFP/legged_gym/b2_gym_learn/ppo_cse_pf/rollout_storage.py',
            'UniFP/legged_gym/envs/b2/legged_robot_b2z1_pos_force.py',
            'UniFP/legged_gym/envs/b2/b2z1_pos_force_config.py')]
    protected={str(p):sha(p) for p in protected_paths}
    result=dict(diagnostic_only=True,mode=args.gym_force_mode,seed=args.ablation_seed,
        pass_probe=False,protected_sha256=protected,formal_training_resumed=False)
    env=None
    try:
        torch.set_num_threads(2)
        if args.gym_steer_drive_probe:
            assert args.gym_force_mode=='evaluate' and args.gym_ranger_nominal_training_source
            assert args.gym_ranger_fixed_com and args.gym_ranger_measure_forces
            assert args.replay_steps==1000 and args.replay_envs==32
            assert args.gym_action_noise_group in ('steer','wheel','base') and args.gym_action_noise_scale==1.
            assert output.parent==(OUT/'gym_steer_drive_20261025_v1').resolve()
        if args.gym_com_action_probe:
            assert args.gym_force_mode=='evaluate' and args.gym_ranger_fixed_com
            assert args.gym_ranger_official_shared and args.gym_ranger_budget_source
            assert args.replay_models_json and args.gym_ranger_init_before_prepare
        if args.gym_ranger_official_shared and args.gym_ranger_fixed_com:
            assert (args.gym_com_action_probe and args.gym_force_mode=='evaluate') or args.gym_ranger_nominal_training_source
        assert not (args.gym_ranger_resume and args.gym_ranger_history_source)
        source_path=args.gym_ranger_nominal_training_source or args.gym_ranger_budget_source or args.gym_ranger_alignment_source or args.gym_ranger_history_source or args.gym_ranger_resume or protected_paths[0]
        source=torch.load(source_path,map_location='cpu')
        if args.gym_ranger_nominal_training_source:
            stage_root=(OUT/'gym_nominal_com_train_20261025_v1').resolve()
            assert stage_root in output.parents or args.gym_steer_drive_probe
            assert not any((args.gym_ranger_budget_source,args.gym_ranger_alignment_source,args.gym_ranger_history_source,args.gym_ranger_resume))
            assert args.gym_ranger_official_shared and args.gym_ranger_force_max==60. and args.gym_ranger_init_before_prepare
            assert args.gym_force_mode in ('train','evaluate')
            if source_path.resolve()==(ROOT/'logs'/CHECKPOINTS[8000]).resolve():
                assert source['iterations']==8000 and source['global_policy_steps']==192000
                if args.gym_force_mode=='train':assert args.ablation_iterations in (1,200)
            else:
                allowed=[stage_root/f'train_200_{s}/joint_diagnostic.pt' for s in (140001,140002)]
                assert source_path.resolve() in allowed
                assert source.get('diagnostic_only') and source['iterations']==8200 and source['global_policy_steps']==196800
                assert source['config']['transport']['fixed_com'] and source['config']['source_iterations']==8000
                if args.gym_force_mode=='train':
                    assert source_path.resolve()==stage_root/f'train_200_{args.ablation_seed}/joint_diagnostic.pt'
                    assert args.ablation_iterations==800
            if args.gym_force_mode=='train':assert args.gym_ranger_fixed_com and args.ablation_seed in (140001,140002)
        if args.gym_ranger_budget_source:
            expected=OUT/'gym_ranger_20261024/official_shared_alignment_v1/experiment_v1'
            allowed=[(expected/f'train_shared_{s}/joint_diagnostic.pt').resolve() for s in (140001,140002)]
            assert source_path.resolve() in allowed
            assert not any((args.gym_ranger_resume,args.gym_ranger_alignment_source,args.gym_ranger_history_source))
            assert source.get('diagnostic_only') and source['iterations']==8200 and source['global_policy_steps']==196800
            assert args.gym_ranger_official_shared and args.gym_ranger_force_max==60.
            assert args.gym_ranger_init_before_prepare and (not args.gym_ranger_fixed_com or args.gym_com_action_probe)
            if args.gym_force_mode=='train':assert args.ablation_iterations==800
        if args.gym_ranger_alignment_source:
            assert source_path.resolve()==(ROOT/'logs'/CHECKPOINTS[8000]).resolve()
            assert source['iterations']==8000 and args.gym_ranger_force_max==60.
            assert args.gym_ranger_init_before_prepare and not args.gym_ranger_fixed_com
            if args.gym_force_mode=='train':assert args.ablation_iterations in (1,200)
        if args.gym_ranger_history_source:
            # Restricted two-stage history diagnostic; never resume production.
            assert args.gym_force_mode=='train'
            assert source['global_policy_steps']==24*source['iterations']
            if source['iterations']==8000:
                assert args.ablation_iterations==100
                assert source_path.resolve()==(ROOT/'logs'/CHECKPOINTS[8000]).resolve()
            elif source['iterations']==8100:
                assert args.ablation_iterations==100
                assert source.get('diagnostic_only') and source['iterations']==8100
                assert source['config']['source_iterations']==8000
                assert args.gym_ranger_force_max==60.
            else:
                assert args.ablation_iterations==400 and args.gym_ranger_force_max==60.
                assert source.get('diagnostic_only') and source['iterations']==8200
                assert source['config']['source_iterations']==8100
                assert source['config']['command_force_max_per_axis_n']==60.
                assert source['config']['external_force_max_per_axis_n']==60.
        if args.gym_ranger_resume:
            assert source.get('diagnostic_only') and args.gym_ranger_force_max==60.
            if args.gym_force_mode=='capture':
                assert source['iterations'] in (10200,10400)
                assert source['global_policy_steps']==24*source['iterations']
            else:
                assert source['iterations']==10200 and source['global_policy_steps']==244800
        protected[str(source_path)]=sha(source_path)
        n=128 if args.gym_force_mode in ('train','capture') else args.replay_envs
        env,ns=gym_ranger_backend(n,args.ablation_seed,args.gym_ranger_force_max,args.gym_ranger_measure_forces,args.gym_ranger_fixed_com,
            init_before_prepare=args.gym_ranger_init_before_prepare,official_shared=args.gym_ranger_official_shared)
        from legged_gym.b2_gym_learn.ppo_cse_pf.actor_critic import ActorCritic
        from legged_gym.b2_gym_learn.ppo_cse_pf.ppo import PPO
        model=ActorCritic(1856,294,12,58,14,actor_hidden_dims=[512,256,128],critic_hidden_dims=[512,256,128])
        algorithm=PPO(model,device='cpu',entropy_coef=.01,num_learning_epochs=5,num_mini_batches=4,
            learning_rate=1e-3,schedule='adaptive',gamma=.99,lam=.95,desired_kl=.01)
        algorithm.init_storage(n,24,[1856],[294],[12],[14])
        result.update(restoration=restore_diagnostic_learner(algorithm,source),transport=env.transport,
            source_iterations=source['iterations'],source_global_policy_steps=source['global_policy_steps'],
            train_envs=n,rollout=24,requested_iterations=args.ablation_iterations,
            dynamics=env.domain.summary(),force_max_per_axis_n=env.curriculum.command.max_force_n,
            command_force_max_per_axis_n=env.curriculum.command.max_force_n,
            external_force_max_per_axis_n=env.curriculum.external.max_force_n,
            dof_force_sensor_enabled=args.gym_ranger_measure_forces,source_checkpoint=str(source_path))
        env.global_policy_steps=int(source['global_policy_steps'])
        if args.gym_ranger_official_shared and args.gym_force_mode=='train':
            env.episode_length_buf[:]=torch.randint_like(env.episode_length_buf,high=env.shared_contract['max_episode_length'])
        torch.save(dict(state=env.state_snapshot(),observations=env.get_observations(),
            root_default=env.robot.data.default_root_state,masses=env.robot.root_physx_view.get_masses(),
            coms=env.robot.root_physx_view.get_coms(),inertias=env.robot.root_physx_view.get_inertias(),
            materials=env.robot.root_physx_view.get_material_properties(),motor_strength=env.domain.motor_strength.clone(),
            torch_rng_state=torch.get_rng_state()),output/'initial_state.pt')
        # Capture quantities before automatic reset, using the existing reward
        # call boundary so terminal samples keep their actual force and target.
        pre={}
        effort_stats=dict(samples=0,estimated_limit_hits=[0]*6,measured_abs_peak_nm=[0.]*6,
            measured_square_sum=[0.]*6,command_peak_abs_n=0.,external_peak_abs_n=0.,
            note='Estimated PD limit hits are not measured drive saturation; DOF sensors report total generalized force.')
        arm_ids=[env.robot.joint_names.index('arm_joint'+str(i)) for i in range(1,7)]
        arm_limits=torch.tensor([40.,40.,27.,7.,7.,7.])
        original_reward=env.rewards.compute
        def capture_reward(robot,feet,contacts_all,controller,actions,torques,
                           commands,goal,gripper_force_w,base_force_w,critic_frame,critic_slices):
            yaw=ns['yaw_quat'](robot.data.root_quat_w)
            ee_target=goal.goal_world+(gripper_force_w+ns['quat_apply_yaw'](robot.data.root_quat_w,commands[:,9:12]))/200.
            base_force=ns['quat_apply_inverse'](yaw,base_force_w)
            velocity_target=commands[:,:2]+(base_force[:,:2]+commands[:,12:14])/200.
            moving=(velocity_target[:,0].abs()>.1)|(velocity_target[:,1].abs()>.1)|(commands[:,2].abs()>.2)
            velocity_target=velocity_target*moving[:,None]
            pre.update(force_world=gripper_force_w.clone(),yaw=yaw.clone(),
                force_target_error=(robot.data.body_pos_w[:,env.gripper_id]-ee_target).norm(dim=-1).clone(),
                velocity_error=(velocity_target-robot.data.root_lin_vel_b[:,:2]).clone(),
                yaw_error=(commands[:,2]-robot.data.root_ang_vel_b[:,2]).clone())
            estimate=robot.data.applied_torque[:,arm_ids]
            effort_stats['samples']+=n
            effort_stats['estimated_limit_hits']=[a+int(b) for a,b in zip(effort_stats['estimated_limit_hits'],
                (estimate.abs()>=arm_limits*.999).sum(0).tolist())]
            effort_stats['command_peak_abs_n']=max(effort_stats['command_peak_abs_n'],float(commands[:,9:12].abs().max()))
            effort_stats['external_peak_abs_n']=max(effort_stats['external_peak_abs_n'],float(gripper_force_w.abs().max()))
            if args.gym_ranger_measure_forces:
                measured=robot.data.measured_dof_force[:,arm_ids].clone()
                assert torch.isfinite(measured).all()
                pre['measured_dof_force_nm']=measured
                pre['estimated_pd_effort_nm']=estimate.clone()
                effort_stats['measured_abs_peak_nm']=[max(a,b) for a,b in zip(effort_stats['measured_abs_peak_nm'],measured.abs().max(0).values.tolist())]
                effort_stats['measured_square_sum']=[a+b for a,b in zip(effort_stats['measured_square_sum'],measured.square().sum(0).tolist())]
            if args.gym_steer_drive_probe:
                # Passive post-physics, pre-reset capture. Never calls observe(),
                # changes simulator properties/targets, or draws random values.
                ids=controller.action_indices;wi=env.privileged.wheel_ids
                scaled=actions*env.domain.motor_strength
                q=robot.data.joint_pos[:,ids];dq=robot.data.joint_vel[:,ids]
                qt=controller.default_positions[ids].expand(n,-1).clone()
                qt[:,controller.position_action_indices]+=.25*scaled[:,controller.position_action_indices]
                vt=torch.zeros_like(dq);vt[:,4:8]=5.*scaled[:,4:8]
                pd=controller.kp[ids]*(qt-q)+controller.kd[ids]*(vt-dq)
                pre['drive_physics']=dict(joint_position_rad=q.clone(),joint_velocity_rad_s=dq.clone(),
                    position_target_rad=qt,velocity_target_rad_s=vt,
                    pd_estimate_post_state_unclamped_nm=pd,
                    pd_estimate_last_substep_clamped_nm=robot.data.applied_torque[:,ids].clone(),
                    measured_total_dof_force_nm=robot.data.measured_dof_force[:,ids].clone(),
                    base_lin_vel_b_m_s=robot.data.root_lin_vel_b.clone(),base_ang_vel_b_rad_s=robot.data.root_ang_vel_b.clone(),
                    wheel_body_quat_w=robot.data.body_quat_w[:,wi].clone(),wheel_body_vel_w=robot.data.body_vel_w[:,wi].clone(),
                    wheel_contact_force_w_n=feet.data.net_forces_w[:,wi].clone(),commands=commands.clone())
            return original_reward(robot,feet,contacts_all,controller,actions,torques,
                commands,goal,gripper_force_w,base_force_w,critic_frame,critic_slices)
        env.rewards.compute=capture_reward
        (output/'config.json').write_text(json.dumps(result,indent=2)+'\n')
        validations={str(p.resolve()):torch.load(p,map_location='cpu') for p in (args.replay_inputs or [])}
        result['fixed_validation_sha256']={p:sha(p) for p in validations}
        def metrics(m,data):
            with torch.inference_mode():
                pred=torch.cat([m.get_student_latent(batch) for batch in data['obs'].split(512)])
            return auxiliary_metrics(pred,data['target'])
        def evaluate():return {key:metrics(model,data) for key,data in validations.items()}
        initial={k:v.detach().clone() for k,v in model.state_dict().items()}
        initial_validation=evaluate()
        obs=env.get_observations()
        checks=dict(label_max_abs_n=0.,history_shift_max_abs=0.,reset_zero_checked=0,
            command_frame_max_abs=0.,fresh_timeout_checked=0)
        def checked_step(actions):
            previous=env.actor.history.clone()
            new,reward,done,info=env.step(actions)
            expected=ns['quat_apply_inverse'](pre['yaw'],pre['force_world'])*.01
            expected[done]=0.
            checks['label_max_abs_n']=max(checks['label_max_abs_n'],float((new['obs_pred'][:,6:9]-expected).abs().max())*100.)
            active=~done
            if active.any():
                checks['history_shift_max_abs']=max(checks['history_shift_max_abs'],
                    float((env.actor.history[active,:-1]-previous[active,1:]).abs().max()))
            if done.any():
                assert torch.count_nonzero(env.actor.history[done,:-1])==0
                assert torch.count_nonzero(new['obs_pred'][done,6:12])==0
                checks['reset_zero_checked']+=int(done.sum())
            command_diff=(env.actor.history[:,-1,-15:]-env.actor.commands*env.actor.command_scales).abs().max()
            checks['command_frame_max_abs']=max(checks['command_frame_max_abs'],float(command_diff))
            assert torch.equal(info['time_outs'],env.rewards.last_termination_masks['timeout'])
            checks['fresh_timeout_checked']+=1
            assert all(torch.isfinite(v).all() for v in new.values()) and torch.isfinite(reward).all()
            assert checks['label_max_abs_n']<1e-4
            assert checks['history_shift_max_abs']==0. and checks['command_frame_max_abs']<1e-6
            return new,reward,done,info
        start=time.perf_counter()
        if args.gym_force_mode=='capture':
            # A frozen stochastic behavior model collects genuine training
            # rollouts. No optimizer step occurs in this process.
            model.eval()
            rows=[]
            with torch.no_grad():
                for _ in range(args.force_capture_warmup):
                    obs,_,_,_=checked_step(model.act(obs['obs']))
                for block in range(args.force_capture_rollouts):
                    for step in range(24):
                        actions=algorithm.act(obs['obs'],obs['privileged_obs'],obs['obs_pred'])
                        obs,reward,done,info=checked_step(actions)
                        algorithm.process_env_step(reward,done,info)
                    algorithm.compute_returns(obs['privileged_obs'])
                    keys=('observations','privileged_observations','observation_preds','actions',
                        'rewards','dones','values','returns','advantages','actions_log_prob','mu','sigma')
                    tape={key:getattr(algorithm.storage,key).clone() for key in keys}
                    tape['last_privileged_observations']=obs['privileged_obs'].clone()
                    torch.save(tape,output/f'capture_{block:02d}.pt')
                    f=tape['observation_preds'][...,6:9]*100.
                    rows.append(dict(block=block,force_rms_n=float(f.square().mean().sqrt()),
                        nonzero_fraction=float((f.norm(dim=-1)>1.).float().mean()),
                        zero_fraction=float((f.norm(dim=-1)<.05).float().mean()),dones=int(tape['dones'].sum())))
                    algorithm.storage.clear()
                    print('RANGER_FROZEN_CAPTURE',args.ablation_seed,rows[-1],flush=True)
            assert all(torch.equal(v,initial[k]) for k,v in model.state_dict().items())
            result.update(frozen_model_unchanged=True,optimizer_steps_executed=0,captured_rollouts=rows,
                warmup_steps=args.force_capture_warmup,capture_steps=24*args.force_capture_rollouts,
                final_global_policy_steps=env.global_policy_steps)
        elif args.gym_force_mode=='train':
            assert args.replay_inputs, 'Freeze independent validation inputs before training'
            history=[]
            for iteration in range(1,args.ablation_iterations+1):
                dones=0;timeouts=0;reward_sum=0.;force_active=0;force_zero=0
                with torch.inference_mode():
                    for step in range(24):
                        actions=algorithm.act(obs['obs'],obs['privileged_obs'],obs['obs_pred'])
                        truth=obs['obs_pred'][:,6:9]*100.
                        force_active+=int((truth.norm(dim=-1)>1.).sum());force_zero+=int((truth.norm(dim=-1)<.05).sum())
                        obs,reward,done,info=checked_step(actions)
                        expected_reward=reward+algorithm.gamma*algorithm.transition.values.squeeze(1)*info['time_outs']
                        algorithm.process_env_step(reward,done,info)
                        assert torch.allclose(algorithm.storage.rewards[step,:,0],expected_reward,atol=1e-6,rtol=1e-6)
                        dones+=int(done.sum());timeouts+=int(info['time_outs'].sum());reward_sum+=float(reward.sum())
                    algorithm.compute_returns(obs['privileged_obs'])
                if iteration==1:
                    torch.save({key:getattr(algorithm.storage,key).clone() for key in
                        ('observations','privileged_observations','observation_preds','actions','rewards','dones','values','returns')},output/'first_rollout.pt')
                losses=algorithm.update()
                assert all(__import__('math').isfinite(float(v)) for v in losses[:3])
                row=dict(iteration=iteration,global_iteration=int(source['iterations'])+iteration,
                    global_policy_steps=env.global_policy_steps,value_loss=float(losses[0]),surrogate_loss=float(losses[1]),
                    official_logged_auxiliary_loss=float(losses[2]),learning_rate=algorithm.learning_rate,
                    mean_reward=reward_sum/(128*24),dones=dones,timeouts=timeouts,
                    force_active_samples=force_active,force_zero_samples=force_zero,total_samples=128*24)
                if iteration==1 or iteration%25==0 or iteration==args.ablation_iterations:
                    row['validation']=evaluate()
                    print('RANGER_GYM_TRAIN',args.ablation_seed,json.dumps(row),flush=True)
                if iteration%args.gym_ranger_save_interval==0 and iteration<args.ablation_iterations:
                    torch.save(dict(model_state_dict=model.state_dict(),optimizer_state_dict=algorithm.optimizer.state_dict(),
                        adaptation_optimizer_state_dict=algorithm.adaptation_module_optimizer.state_dict(),
                        iterations=int(source['iterations'])+iteration,global_policy_steps=env.global_policy_steps,
                        learning_rate=algorithm.learning_rate,diagnostic_only=True),output/f'joint_iter_{int(source["iterations"])+iteration:06d}.pt')
                history.append(row)
                (output/'progress.json').write_text(json.dumps(history,indent=2)+'\n')
            saved=dict(model_state_dict=model.state_dict(),optimizer_state_dict=algorithm.optimizer.state_dict(),
                adaptation_optimizer_state_dict=algorithm.adaptation_module_optimizer.state_dict(),
                iterations=int(source['iterations'])+args.ablation_iterations,global_policy_steps=env.global_policy_steps,
                num_envs=128,steps_per_env=24,learning_rate=algorithm.learning_rate,diagnostic_only=True,config=result)
            assert env.global_policy_steps==int(source['global_policy_steps'])+24*args.ablation_iterations
            for key in ('optimizer_state_dict','adaptation_optimizer_state_dict'):
                before={float(s['step']) for s in source[key]['state'].values() if 'step' in s}
                after={float(s['step']) for s in saved[key]['state'].values() if 'step' in s}
                assert len(before)==1 and after=={next(iter(before))+20*args.ablation_iterations},(key,before,after)
            torch.save(saved,output/'joint_diagnostic.pt')
            changes={prefix:float(sum((v-initial[k]).double().square().sum() for k,v in model.state_dict().items()
                if k.startswith(prefix)).sqrt()) for prefix in
                ('actor_body','critic_body','adaptation_encoder_module','adaptation_decoder_module')}
            assert all(v>0. for v in changes.values())
            assert all(torch.isfinite(v).all() for v in model.state_dict().values())
            assert all(torch.isfinite(v).all() for opt in (algorithm.optimizer,algorithm.adaptation_module_optimizer)
                for state in opt.state.values() for v in state.values() if isinstance(v,torch.Tensor))
            result.update(initial_validation=initial_validation,final_validation=evaluate(),history=history,
                module_change_l2=changes,completed_training_transitions=128*24*args.ablation_iterations,
                final_global_policy_steps=env.global_policy_steps)
        else:
            if args.replay_models_json:
                paths=json.loads(args.replay_models_json.read_text())
                model.load_state_dict(torch.load(paths[args.replay_model],map_location='cpu')['model_state_dict'])
            frozen_initial={k:v.detach().clone() for k,v in model.state_dict().items()}
            model.eval();model.requires_grad_(False)
            rows=[];inputs=[];targets=[];predictions=[];trace=[]
            # Isolate evaluation action sampling from task/noise RNG. No learner update.
            action_generator=torch.Generator(device='cpu').manual_seed(args.ablation_seed+190000)
            action_scale=args.gym_action_noise_scale
            if action_scale is None:action_scale=1. if args.gym_ranger_sample_actions else 0.
            result.update(evaluation_action_mode='sampled' if action_scale else 'mean',
                evaluation_action_noise_scale=action_scale,evaluation_action_noise_group=args.gym_action_noise_group,
                evaluation_action_generator_seed=args.ablation_seed+190000)
            executed=[]
            with torch.inference_mode():
                for step in range(args.replay_steps):
                    pred=model.get_student_latent(obs['obs'])
                    predictions.append(pred.clone());targets.append(obs['obs_pred'].clone())
                    if step%8==0:inputs.append(obs['obs'].clone())
                    actions=model.act_inference(obs)
                    if args.gym_ranger_sample_actions or args.gym_action_noise_scale is not None:
                        actions=diagnostic_action_noise(actions,model,action_generator,args,8)
                    executed.append(actions.clone())
                    obs,reward,done,info=checked_step(actions)
                    snap=info['pre_reset_state']
                    error=snap['position_error_m']
                    rows.append(dict(step=step,dones=int(done.sum()),timeouts=int(info['time_outs'].sum()),
                        ee_error_mean_m=float(error.mean()),root_height_mean_m=float(snap['base_height_m'].mean()),
                        ee_force_target_error_mean_m=float(pre['force_target_error'].mean()),
                        base_xy_mse=float(pre['velocity_error'].square().mean()),yaw_mse=float(pre['yaw_error'].square().mean()),
                        roll_abs_max=float(snap['roll_abs_rad'].max()),pitch_abs_max=float(snap['pitch_abs_rad'].max())))
                    if step%8==0:trace.append(dict(step=step,actions=actions.clone(),state=snap,
                        root=env.robot.data.root_pos_w.clone(),target=obs['obs_pred'].clone(),pre=copy.deepcopy(pre)))
                    if args.gym_steer_drive_probe and step%8==0:trace[-1]['dones']=done.clone()
                    if (step+1)%400==0: print('RANGER_GYM_REPLAY',args.ablation_seed,step+1,rows[-1],flush=True)
            assert all(torch.equal(v,frozen_initial[k]) for k,v in model.state_dict().items())
            target=torch.cat(targets);pred=torch.cat(predictions)
            validation=dict(obs=torch.cat(inputs),target=torch.stack(targets)[::8].reshape(-1,12),
                seed=args.ablation_seed,environments=n,sampling_stride=8,split='complete held-out environments and independent simulation')
            assert len(validation['obs'])==len(validation['target'])
            torch.save(validation,output/'validation.pt')
            torch.save(dict(target=target,prediction=pred,trace=trace,executed_actions=torch.stack(executed)),output/'replay_trace.pt')
            (output/'steps.jsonl').write_text(''.join(json.dumps(v)+'\n' for v in rows))
            result.update(force_metrics=auxiliary_metrics(pred,target),zero_force_metrics=auxiliary_metrics(torch.zeros_like(pred),target),
                model_on_fixed_inputs=metrics(model,validation),replay_steps=args.replay_steps,
                non_timeout_terminations=sum(r['dones']-r['timeouts'] for r in rows),
                timeouts=sum(r['timeouts'] for r in rows),ee_error_mean_m=sum(r['ee_error_mean_m'] for r in rows)/len(rows),
                ee_force_target_error_mean_m=sum(r['ee_force_target_error_mean_m'] for r in rows)/len(rows),
                base_xy_rmse_m_s=(sum(r['base_xy_mse'] for r in rows)/len(rows))**.5,
                yaw_rmse_rad_s=(sum(r['yaw_mse'] for r in rows)/len(rows))**.5,
                root_height_mean_m=sum(r['root_height_mean_m'] for r in rows)/len(rows),
                frozen_model_unchanged=True,force_active_samples=int(((target[:,6:9]*100.).norm(dim=-1)>1.).sum()),
                total_samples=len(target))
        for path,digest in protected.items(): assert sha(path)==digest
        result.update(pass_probe=True,checks=checks,elapsed_s=time.perf_counter()-start,
            protected_unchanged=True,force_curriculum=env.curriculum.summary(),effort_diagnostic=effort_stats)
        (output/'result.json').write_text(json.dumps(result,indent=2,allow_nan=False)+'\n')
        print('RANGER_GYM_COMPLETE',str(output),flush=True)
    except Exception as exc:
        result.update(error=str(exc),traceback=traceback.format_exc())
        (output/'failure.json').write_text(json.dumps(result,indent=2)+'\n')
        raise
    finally:
        if env is not None:env.close()


def run_gym_ranger_history(args):
    """Matched 8000-source histories: 100 rounds 15/60, then 100 rounds 60."""
    import hashlib
    import os
    import shutil
    import subprocess
    import time
    def sha(p):return hashlib.sha256(Path(p).read_bytes()).hexdigest()
    root=args.probe_output.resolve();root.mkdir(parents=True,exist_ok=False)
    extend=args.gym_ranger_history_extend
    prior=OUT/'gym_ranger_20261024'/('force_history_v1' if extend else 'com_init_training_v1')
    previous=json.loads((prior/'plan.json').read_text())
    protected=dict(previous['protected_sha256'])
    source=ROOT/'logs'/CHECKPOINTS[8000]
    for p in (source,source.parent/'config.json',source.parent/'metrics.json',source.parent/'launch.json'):
        protected[str(p)]=sha(p)
    historical={str(p):sha(p) for p in prior.rglob('*') if p.is_file()}
    if extend:
        assert json.loads((prior/'status.json').read_text())['state']=='complete'
        assert json.loads((prior/'completion_verification.json').read_text())['pass_verification']
        older=json.loads((Path(previous['prior'])/'plan.json').read_text())
        historical={**older['historical_sha256'],**previous['historical_sha256'],**historical}
    for p,h in {**protected,**historical}.items():assert sha(p)==h,p
    monitor=previous['monitor_inputs']
    holdout=previous['holdout_inputs'] if extend else [str(prior/f'holdout_formal_seed{s}/validation.pt') for s in (136601,136602)]
    frozen=dict(frozen_before_training_unix=time.time(),sha256={p:sha(p) for p in monitor+holdout},
        monitor_inputs=monitor,holdout_inputs=holdout,holdout_used_during_training=False,
        reuse='Existing complete independent 32-environment runs, recorded before this experiment')
    (root/'frozen_validation.json').write_text(json.dumps(frozen,indent=2)+'\n')
    py='/home/sorry/.cache/unifp/isaacgym_preview4/torch231/bin/python'
    jobs=[];models={'source8000':str(source),'formal10000':str(ROOT/'logs'/CHECKPOINTS[10000])}
    def job(name,mode,seed,force,extra=()):
        jobs.append(dict(name=name,mode=mode,seed=seed,force=force,command=[py,str(Path(__file__).resolve()),
            '--gym_ranger_diagnostic','--gym_force_mode',mode,'--ablation_seed',str(seed),
            '--probe_output',str(root/name),'--gym_ranger_force_max',str(force),
            '--gym_ranger_init_before_prepare','--gym_ranger_measure_forces',*extra]))
    finals=[]
    if extend:
        import torch
        previous_models=json.loads((prior/'models.json').read_text())
        source_checks={}
        for seed in (137001,137002):
            for force in (60,15):
                start=f'phase2_f{force}_seed{seed}';path=Path(previous_models[start])
                ck=torch.load(path,map_location='cpu')
                assert ck['diagnostic_only'] and ck['iterations']==8200 and ck['global_policy_steps']==196800
                assert ck['config']['source_iterations']==8100
                steps={k:sorted({float(s['step']) for s in ck[k]['state'].values()}) for k in
                    ('optimizer_state_dict','adaptation_optimizer_state_dict')}
                assert all(v==[164000.] for v in steps.values())
                protected[str(path)]=sha(path);models[start]=str(path)
                source_checks[start]=dict(sha256=sha(path),iterations=8200,global_policy_steps=196800,adam_steps=steps)
                name=f'phase3_f{force}_seed{seed}';finals.append(name)
                models[name]=str(root/name/'joint_diagnostic.pt')
                job(name,'train',seed+2000,60,('--gym_ranger_history_source',str(path),
                    '--gym_ranger_save_interval','100','--ablation_iterations','400','--replay_inputs',*monitor))
        (root/'source_verification.json').write_text(json.dumps(source_checks,indent=2)+'\n')
    else:
        for seed in (137001,137002):
            for force in (15,60):
                name=f'phase1_f{force}_seed{seed}';path=root/name/'joint_diagnostic.pt'
                models[name]=str(path)
                job(name,'train',seed,force,('--gym_ranger_history_source',str(source),
                    '--ablation_iterations','100','--replay_inputs',*monitor))
        for seed in (137001,137002):
            for force in (15,60):
                name=f'phase2_f{force}_seed{seed}';finals.append(name)
                models[name]=str(root/name/'joint_diagnostic.pt')
                job(name,'train',seed+1000,60,('--gym_ranger_history_source',models[f'phase1_f{force}_seed{seed}'],
                    '--ablation_iterations','100','--replay_inputs',*monitor))
    (root/'models.json').write_text(json.dumps(models,indent=2)+'\n')
    for seed in (136601,136602):
        for name in ([] if extend else ['source8000'])+finals:
            job(f'replay_{name}_seed{seed}','evaluate',seed,60,
                ('--replay_models_json',str(root/'models.json'),'--replay_model',name))
    plan=dict(scope='Only first-stage force amplitude differs between paired histories',
        source=str(source),source_iterations=8000,source_global_policy_steps=192000,
        train_seeds=[137001,137002],phase2_seed_offset=1000,phase_iterations=100,
        train_envs=128,rollout=24,validation_envs=32,replay_steps=2000,
        monitor_inputs=monitor,holdout_inputs=holdout,holdout_seeds=[136601,136602],
        final_models=finals,prior=str(prior),protected_sha256=protected,historical_sha256=historical,
        continuation=extend,additional_iterations=400 if extend else 200,
        continuation_seed_offset=2000 if extend else None,
        checkpoint_iterations=[8300,8400,8500,8600] if extend else [8100,8200],
        audit_sha256=sha(__file__),jobs=jobs,formal_training_resumed=False,
        unchanged='Correct initialization, random COM and other dynamics, noise, commands/goals, pushes, official PPO/networks/reward/auxiliary losses and restored Adams',
        phase_boundary='Both branches restart simulation with matched seed; model and both Adam states continue',
        limitations=['100-round force histories do not reproduce the old 2000-round 15 N history',
            'Joint policies generate different trajectories after force intervention; this is not paired-sample supervision',
            'Both start with a Lab-trained zero-force policy; not native Gym pretraining',
            'Evaluation uses mature 60 N task counter, including source8000 model, without updating weights'])
    if extend:
        plan.update(scope='Continue both force histories by the same fixed 400-round 60 N budget',
            source_iterations=8200,source_global_policy_steps=196800,phase_iterations=400,
            cumulative_diagnostic_iterations=600,phase_boundary='Paired fresh simulation seed; model and both restored Adams continue, no intermediate simulation restart')
        plan['limitations']+=['Reused evaluation histories were scored in earlier diagnostics; not a previously unseen blind test',
            'At cumulative 600 rounds, switched history has 500 rounds of 60 N exposure, direct history has 600']
    (root/'plan.json').write_text(json.dumps(plan,indent=2)+'\n');shutil.copy2(__file__,root/'audit_snapshot.py')
    status=dict(state='running',completed_jobs=0,total_jobs=len(jobs))
    def save():
        status['updated_unix']=time.time();tmp=root/'status.tmp'
        tmp.write_text(json.dumps(status,indent=2)+'\n');tmp.replace(root/'status.json')
    env=os.environ.copy();env.update(OMNI_KIT_ACCEPT_EULA='Y',RANGER_ASSET_VERSION='v3_original',
        OMP_NUM_THREADS='2',MKL_NUM_THREADS='2',OPENBLAS_NUM_THREADS='2',MAX_JOBS='2',PYTHONUNBUFFERED='1')
    env['LD_LIBRARY_PATH']='/home/sorry/.cache/unifp/isaacgym_preview4/py38/lib:'+env.get('LD_LIBRARY_PATH','')
    env['PATH']='/home/sorry/.cache/unifp/isaacgym_preview4/py38/bin:'+env['PATH']
    child=None
    try:
        for item in jobs:
            assert sha(__file__)==plan['audit_sha256']
            for p,h in frozen['sha256'].items():assert sha(p)==h,p
            status.update(current_job=item['name'],current_iteration=None,job_started_unix=time.time());save()
            print('HISTORY_JOB_START',item['name'],flush=True)
            with (root/(item['name']+'.log')).open('w') as log:
                child=subprocess.Popen(item['command'],cwd=ROOT,env=env,stdout=log,stderr=subprocess.STDOUT)
                status['pid']=child.pid;save()
                while child.poll() is None:
                    progress=root/item['name']/'progress.json'
                    if progress.exists():
                        try:status['current_iteration']=json.loads(progress.read_text())[-1]['iteration']
                        except (json.JSONDecodeError,IndexError):pass
                    save();time.sleep(1.)
                assert child.returncode==0,f"{item['name']} failed; see log"
            r=json.loads((root/item['name']/'result.json').read_text())
            assert r['pass_probe'] and r['transport']['rigid_property_initialization']=='before_prepare'
            assert r['command_force_max_per_axis_n']==r['external_force_max_per_axis_n']==item['force']
            status['completed_jobs']+=1;save();print('HISTORY_JOB_COMPLETE',item['name'],flush=True)
        for p,h in {**protected,**historical,**frozen['sha256']}.items():assert sha(p)==h,p
        status.update(state='experiments_complete',current_job=None,pid=None);save()
    except BaseException as exc:
        if child is not None and child.poll() is None:child.terminate();child.wait(timeout=30)
        status.update(state='failed',error=str(exc));save();raise


def summarize_gym_ranger_history(root):
    """Same-input cross scores and separate closed-loop scores, float64 checked."""
    import contextlib
    import hashlib
    import io
    import math
    import numpy as np
    import torch
    from legged_gym.b2_gym_learn.ppo_cse_pf.actor_critic import ActorCritic
    torch.set_num_threads(2)
    assert not (root/'results.json').exists()
    plan=json.loads((root/'plan.json').read_text());prior=Path(plan['prior'])
    extend=plan.get('continuation',False)
    frozen=json.loads((root/'frozen_validation.json').read_text())
    assert json.loads((root/'status.json').read_text())['state']=='experiments_complete'
    sha=lambda p:hashlib.sha256(Path(p).read_bytes()).hexdigest()
    for p,h in {**plan['protected_sha256'],**plan['historical_sha256'],**frozen['sha256']}.items():assert sha(p)==h,p
    paths=json.loads((root/'models.json').read_text())
    reference=Path(json.loads((prior/'plan.json').read_text())['prior']) if extend else prior
    for seed in (133001,133002):paths[f'prior10000_plus200_seed{seed}']=str(reference/f'train_seed{seed}/joint_diagnostic.pt')
    if extend:
        for name in plan['final_models']:
            for iteration in (8300,8400,8500):
                paths[f'{name}_iter{iteration}']=str(root/name/f'joint_iter_{iteration:06d}.pt')
    models={};model_checks={};checks=[];predictions={}
    for name,path in paths.items():
        ck=torch.load(path,map_location='cpu')
        with contextlib.redirect_stdout(io.StringIO()):
            model=ActorCritic(1856,294,12,58,14,actor_hidden_dims=[512,256,128],critic_hidden_dims=[512,256,128])
        model.load_state_dict(ck['model_state_dict']);model.eval();model.requires_grad_(False);models[name]=model
        steps={k:sorted({float(v['step']) for v in ck[k]['state'].values()}) for k in
            ('optimizer_state_dict','adaptation_optimizer_state_dict')}
        assert all(v==[20.*ck['iterations']] for v in steps.values())
        assert ck['global_policy_steps']==24*ck['iterations']
        assert all(torch.isfinite(v).all() for v in model.state_dict().values())
        assert all(torch.isfinite(v).all() for k in steps for s in ck[k]['state'].values() for v in s.values() if isinstance(v,torch.Tensor))
        model_checks[name]=dict(sha256=sha(path),iterations=ck['iterations'],adam_steps=steps,finite=True)
    def verified(p,y):
        m=auxiliary_metrics(p,y);pn=p[:,6:9].numpy().astype(np.float64)*100.;yn=y[:,6:9].numpy().astype(np.float64)*100.
        active=np.linalg.norm(yn,axis=1)>1.;zero=np.linalg.norm(yn,axis=1)<.05
        independent=dict(force_rmse_per_axis_n=float(np.sqrt(np.mean((pn-yn)**2))),
            active_vector_error_n=float(np.linalg.norm(pn[active]-yn[active],axis=1).mean()),
            zero_estimate_norm_n=float(np.linalg.norm(pn[zero],axis=1).mean()))
        assert all(abs(m[k]-v)<1e-4 for k,v in independent.items());checks.append(independent);return m
    def cross(label,data):
        x=torch.cat([d['obs'] for d in data]);y=torch.cat([d['target'] for d in data])
        with torch.inference_mode():p={n:torch.cat([m.get_student_latent(b) for b in x.split(512)]) for n,m in models.items()}
        predictions[label]=dict(target=y,predictions=p)
        return dict(samples=len(y),models={n:verified(v,y) for n,v in p.items()},zero=verified(torch.zeros_like(y),y))
    fixed={}
    for label,files in (('monitor',plan['monitor_inputs']),('holdout',plan['holdout_inputs'])):
        data=[torch.load(p,map_location='cpu') for p in files]
        fixed[label]=dict(merged=cross(label,data),per_seed={str(d['seed']):cross(label+'_'+str(d['seed']),[d]) for d in data})
    closed={}
    for name in ['source8000']+plan['final_models']:
        pp=[];yy=[];allrows=[];per_seed={}
        for seed in plan['holdout_seeds']:
            folder=(prior if extend and name=='source8000' else root)/f'replay_{name}_seed{seed}'
            r=json.loads((folder/'result.json').read_text())
            assert r['pass_probe'] and r['frozen_model_unchanged']
            tape=torch.load(folder/'replay_trace.pt',map_location='cpu');p,y=tape['prediction'],tape['target']
            m=verified(p,y)
            for k in ('force_rmse_per_axis_n','active_vector_error_n','zero_estimate_norm_n'):assert abs(m[k]-r['force_metrics'][k])<1e-5
            d=torch.load(folder/'validation.pt',map_location='cpu')
            with torch.inference_mode():again=torch.cat([models[name].get_student_latent(b) for b in d['obs'].split(512)])
            assert torch.allclose(again,p.reshape(2000,32,12)[::8].reshape(-1,12),atol=1e-5,rtol=1e-5)
            rows=[json.loads(v) for v in (folder/'steps.jsonl').read_text().splitlines()];assert len(rows)==2000
            pp.append(p);yy.append(y);allrows.extend(rows);per_seed[str(seed)]=dict(force=m,zero=verified(torch.zeros_like(y),y))
        y=torch.cat(yy)
        closed[name]=dict(force=verified(torch.cat(pp),y),zero=verified(torch.zeros_like(y),y),per_seed=per_seed,
            ee_force_target_error_mean_m=sum(v['ee_force_target_error_mean_m'] for v in allrows)/len(allrows),
            base_xy_rmse_m_s=math.sqrt(sum(v['base_xy_mse'] for v in allrows)/len(allrows)),
            yaw_rmse_rad_s=math.sqrt(sum(v['yaw_mse'] for v in allrows)/len(allrows)),
            non_timeout_terminations=sum(v['dones']-v['timeouts'] for v in allrows))
    training={};pair_checks={}
    for item in plan['jobs']:
        if item['mode']!='train':continue
        folder=root/item['name'];r=json.loads((folder/'result.json').read_text())
        count=400 if extend else 100
        assert r['pass_probe'] and len(r['history'])==count and r['completed_training_transitions']==3072*count
        phase1=item['name'].startswith('phase1')
        assert r['source_iterations']==(8200 if extend else (8000 if phase1 else 8100))
        assert r['final_global_policy_steps']==24*(8600 if extend else (8100 if phase1 else 8200))
        assert r['fixed_validation_sha256']=={p:frozen['sha256'][p] for p in plan['monitor_inputs']}
        assert frozen['frozen_before_training_unix']<(folder/'config.json').stat().st_mtime
        training[item['name']]=dict(restoration=r['restoration'],module_change_l2=r['module_change_l2'],checks=r['checks'],
            transitions=r['completed_training_transitions'],elapsed_s=r['elapsed_s'],force_curriculum=r['force_curriculum'],
            value_loss_max=max(v['value_loss'] for v in r['history']),
            non_timeout_terminations=sum(v['dones']-v['timeouts'] for v in r['history']))
    for phase in (('phase3',) if extend else ('phase1','phase2')):
        for seed in plan['train_seeds']:
            a,b=[torch.load(root/f'{phase}_f{f}_seed{seed}/initial_state.pt',map_location='cpu') for f in (15,60)]
            fields=('masses','coms','inertias','materials','motor_strength','root_default','torch_rng_state')
            assert all(torch.equal(a[k],b[k]) for k in fields)
            for k in a['state']:assert torch.equal(a['state'][k],b['state'][k])
            for k in a['observations']:assert torch.equal(a['observations'][k],b['observations'][k])
            pair_checks[f'{phase}_{seed}']=dict(randomization_and_initial_state_equal=True,initial_observations_equal=True)
    result=dict(fixed=fixed,closed=closed,training=training,pair_checks=pair_checks,model_checks=model_checks,
        independent_metric_checks=len(checks),protected_verified=len(plan['protected_sha256']),
        historical_verified=len(plan['historical_sha256']),holdout_not_used_during_training=True,
        formal_training_resumed=False,limitations=plan['limitations'])
    if extend:
        result['prior_closed']=json.loads((prior/'results.json').read_text())['closed']
        result['continuation']=True
    torch.save(predictions,root/'cross_predictions.pt')
    (root/'results.json').write_text(json.dumps(result,indent=2,allow_nan=False)+'\n')
    print('HISTORY_SUMMARY_COMPLETE',len(models),len(checks),flush=True)


def run_gym_ranger_shared(args):
    """Finite shared-source comparison; all learning uses the existing runner."""
    import hashlib
    import os
    import shutil
    import subprocess
    import time
    def sha(p):return hashlib.sha256(Path(p).read_bytes()).hexdigest()
    root=args.probe_output.resolve();root.mkdir(parents=True,exist_ok=False)
    protection=json.loads((root.parent/'protection.json').read_text())
    protected=protection['protected_sha256'];historical=protection['historical_sha256']
    for relative in ('UniFP/legged_gym/utils/isaacgym_utils.py','UniFP/legged_gym/envs/base/legged_robot_config.py'):
        p=ROOT/relative;protected[str(p)]=sha(p)
    for p,h in {**protected,**historical}.items():assert sha(p)==h,p
    source=ROOT/'logs'/CHECKPOINTS[8000]
    models={'source':str(source)}
    for domain in ('adapted','shared'):
        for seed in (140001,140002):models[f'{domain}{seed}']=str(root/f'train_{domain}_{seed}'/'joint_diagnostic.pt')
    (root/'models.json').write_text(json.dumps(models,indent=2)+'\n')
    py='/home/sorry/.cache/unifp/isaacgym_preview4/torch231/bin/python'
    jobs=[]
    def job(name,mode,seed,domain,extra=()):
        command=[py,str(Path(__file__).resolve()),'--gym_ranger_diagnostic','--gym_force_mode',mode,
            '--ablation_seed',str(seed),'--probe_output',str(root/name),'--gym_ranger_force_max','60',
            '--gym_ranger_alignment_source',str(source),'--gym_ranger_measure_forces',*extra]
        if domain=='shared':command.append('--gym_ranger_official_shared')
        jobs.append(dict(name=name,mode=mode,seed=seed,domain=domain,command=command))
    for domain in ('adapted','shared'):
        for seed in (141501,141502):job(f'monitor_{domain}_{seed}','evaluate',seed,domain)
        for seed in (141601,141602):job(f'test_source_{domain}_{seed}','evaluate',seed,domain)
    monitor=[str(root/f'monitor_{domain}_{seed}'/'validation.pt')
             for domain in ('adapted','shared') for seed in (141501,141502)]
    test=[str(root/f'test_source_{domain}_{seed}'/'validation.pt')
          for domain in ('adapted','shared') for seed in (141601,141602)]
    for seed in (140001,140002):
        for domain in ('adapted','shared'):
            job(f'train_{domain}_{seed}','train',seed,domain,('--ablation_iterations','200','--replay_inputs',*monitor))
    for domain in ('adapted','shared'):
        for seed in (141601,141602):
            for name in models:
                if name!='source':job(f'test_{name}_{domain}_{seed}','evaluate',seed,domain,
                    ('--replay_models_json',str(root/'models.json'),'--replay_model',name))
    plan=dict(scope='Portable task-method bundle: released methods vs existing Ranger adaptation',
        source=str(source),source_iterations=8000,source_global_policy_steps=192000,
        train_seeds=[140001,140002],monitor_seeds=[141501,141502],holdout_seeds=[141601,141602],
        domains=['adapted','shared'],train_envs=128,validation_envs=32,rollout=24,iterations=200,
        replay_steps=2000,monitor_inputs=monitor,test_inputs=test,holdout_used_during_training=False,
        paired_trajectories=False,reason='Source methods change RNG consumption and initial episode lengths',
        formal_training_resumed=False,protected_sha256=protected,historical_sha256=historical,
        audit_sha256=sha(__file__),jobs=jobs)
    (root/'plan.json').write_text(json.dumps(plan,indent=2)+'\n');shutil.copy2(__file__,root/'audit_snapshot.py')
    status=dict(state='running',completed_jobs=0,total_jobs=len(jobs))
    def save():
        status['updated_unix']=time.time();tmp=root/'status.tmp'
        tmp.write_text(json.dumps(status,indent=2)+'\n');tmp.replace(root/'status.json')
    env=os.environ.copy();env.update(OMNI_KIT_ACCEPT_EULA='Y',RANGER_ASSET_VERSION='v3_original',
        OMP_NUM_THREADS='2',MKL_NUM_THREADS='2',OPENBLAS_NUM_THREADS='2',MAX_JOBS='2',PYTHONUNBUFFERED='1')
    env['LD_LIBRARY_PATH']='/home/sorry/.cache/unifp/isaacgym_preview4/py38/lib:'+env.get('LD_LIBRARY_PATH','')
    env['PATH']='/home/sorry/.cache/unifp/isaacgym_preview4/py38/bin:'+env['PATH']
    child=None
    try:
        for item in jobs:
            assert sha(__file__)==plan['audit_sha256'],'Source changed during experiment'
            if item['mode']=='train' and not (root/'frozen_validation.json').exists():
                frozen=dict(frozen_before_training_unix=time.time(),sha256={p:sha(p) for p in monitor+test},
                    monitor_inputs=monitor,holdout_used_during_training=False)
                (root/'frozen_validation.json').write_text(json.dumps(frozen,indent=2)+'\n')
            status.update(current_job=item['name'],current_iteration=None,job_started_unix=time.time());save()
            print('SHARED_JOB_START',item['name'],flush=True)
            with (root/(item['name']+'.log')).open('w') as log:
                child=subprocess.Popen(item['command'],cwd=ROOT,env=env,stdout=log,stderr=subprocess.STDOUT)
                status['pid']=child.pid;save()
                while child.poll() is None:
                    progress=root/item['name']/'progress.json'
                    if progress.exists():
                        try:
                            rows=json.loads(progress.read_text());status['current_iteration']=rows[-1]['iteration'] if rows else 0
                        except json.JSONDecodeError:pass
                    save();time.sleep(1.)
                assert child.returncode==0,f"{item['name']} failed; see log"
            r=json.loads((root/item['name']/'result.json').read_text())
            assert r['pass_probe'] and r['protected_unchanged']
            assert r['command_force_max_per_axis_n']==r['external_force_max_per_axis_n']==60.
            status['completed_jobs']+=1;save();print('SHARED_JOB_COMPLETE',item['name'],flush=True)
        for p,h in {**protected,**historical,**frozen['sha256']}.items():assert sha(p)==h,p
        status.update(state='experiments_complete',current_job=None,pid=None);save()
    except BaseException as exc:
        if child is not None and child.poll() is None:child.terminate();child.wait(timeout=30)
        status.update(state='failed',error=str(exc));save();raise


def summarize_gym_ranger_shared(root):
    """Cross-domain estimates and closed-loop control, with float64 checks."""
    import contextlib
    import hashlib
    import io
    import math
    import numpy as np
    import torch
    from legged_gym.b2_gym_learn.ppo_cse_pf.actor_critic import ActorCritic
    torch.set_num_threads(2)
    assert not (root/'results.json').exists()
    plan=json.loads((root/'plan.json').read_text());frozen=json.loads((root/'frozen_validation.json').read_text())
    status=json.loads((root/'status.json').read_text());assert status['state']=='experiments_complete'
    def sha(p):return hashlib.sha256(Path(p).read_bytes()).hexdigest()
    protected={**plan['protected_sha256'],**plan['historical_sha256'],**frozen['sha256']}
    for p,h in protected.items():assert sha(p)==h,p
    paths=json.loads((root/'models.json').read_text());models={};checks={}
    for name,path in list(paths.items()):
        if name!='source':
            for it in (8050,8100,8150):paths[f'{name}_iter{it}']=str(Path(path).parent/f'joint_iter_{it:06d}.pt')
    for name,path in paths.items():
        ck=torch.load(path,map_location='cpu')
        with contextlib.redirect_stdout(io.StringIO()):
            model=ActorCritic(1856,294,12,58,14,actor_hidden_dims=[512,256,128],critic_hidden_dims=[512,256,128])
        model.load_state_dict(ck['model_state_dict']);model.eval();model.requires_grad_(False);models[name]=model
        steps={k:sorted({float(v['step']) for v in ck[k]['state'].values() if 'step' in v})
               for k in ('optimizer_state_dict','adaptation_optimizer_state_dict')}
        assert all(v==[float(20*ck['iterations'])] for v in steps.values())
        assert ck['global_policy_steps']==24*ck['iterations']
        assert all(torch.isfinite(v).all() for v in model.state_dict().values())
        assert all(torch.isfinite(v).all() for k in steps for state in ck[k]['state'].values()
                   for v in state.values() if isinstance(v,torch.Tensor))
        checks[name]=dict(sha256=sha(path),iterations=ck['iterations'],adam_steps=steps,finite=True)
    numerical=[];predictions={}
    def verified(p,y):
        result=auxiliary_metrics(p,y)
        pn=p[:,6:9].numpy().astype(np.float64)*100.;yn=y[:,6:9].numpy().astype(np.float64)*100.
        active=np.linalg.norm(yn,axis=1)>1.;zero=np.linalg.norm(yn,axis=1)<.05
        independent=dict(force_rmse_per_axis_n=float(np.sqrt(np.mean((pn-yn)**2))),
            active_vector_error_n=float(np.linalg.norm(pn[active]-yn[active],axis=1).mean()),
            zero_estimate_norm_n=float(np.linalg.norm(pn[zero],axis=1).mean()))
        assert all(abs(result[k]-v)<1e-4 for k,v in independent.items())
        numerical.append(independent);result['rmse_vs_zero_ratio']=result['force_rmse_per_axis_n']/float(np.sqrt(np.mean(yn**2)))
        return result
    def cross(label,folders):
        data=[torch.load(f/'validation.pt',map_location='cpu') for f in folders]
        x=torch.cat([d['obs'] for d in data]);y=torch.cat([d['target'] for d in data])
        with torch.inference_mode():p={n:torch.cat([m.get_student_latent(b) for b in x.split(512)]) for n,m in models.items()}
        predictions[label]=dict(target=y,predictions=p)
        return dict(samples=len(y),models={n:verified(v,y) for n,v in p.items()},zero=verified(torch.zeros_like(y),y))
    fixed={}
    for domain in plan['domains']:
        for split,seeds,prefix in (('monitor',plan['monitor_seeds'],'monitor'),('test',plan['holdout_seeds'],'test_source')):
            folders=[root/f'{prefix}_{domain}_{s}' for s in seeds]
            fixed[f'{domain}_{split}']=dict(merged=cross(f'{domain}_{split}',folders),
                per_seed={str(s):cross(f'{domain}_{split}_{s}',[f]) for s,f in zip(seeds,folders)})
    closed={};trace_checks={}
    for domain in plan['domains']:
        closed[domain]={}
        for name in json.loads((root/'models.json').read_text()):
            parts=[];per_seed={}
            for seed in plan['holdout_seeds']:
                f=root/(f'test_source_{domain}_{seed}' if name=='source' else f'test_{name}_{domain}_{seed}')
                r=json.loads((f/'result.json').read_text());assert r['pass_probe'] and r['frozen_model_unchanged']
                tape=torch.load(f/'replay_trace.pt',map_location='cpu');p=tape['prediction'];y=tape['target']
                force=verified(p,y);zero=verified(torch.zeros_like(p),y)
                for k in ('force_rmse_per_axis_n','active_vector_error_n','zero_estimate_norm_n'):
                    assert abs(force[k]-r['force_metrics'][k])<1e-5
                d=torch.load(f/'validation.pt',map_location='cpu')
                with torch.inference_mode():again=torch.cat([models[name].get_student_latent(b) for b in d['obs'].split(512)])
                assert torch.allclose(again,p.reshape(2000,32,12)[::8].reshape(-1,12),atol=1e-5,rtol=1e-5)
                rows=[json.loads(v) for v in (f/'steps.jsonl').read_text().splitlines()];assert len(rows)==2000
                control={k:sum(v[k] for v in rows)/len(rows) for k in
                    ('ee_error_mean_m','ee_force_target_error_mean_m','base_xy_mse','yaw_mse','root_height_mean_m')}
                control.update(non_timeout_terminations=sum(v['dones']-v['timeouts'] for v in rows),timeouts=sum(v['timeouts'] for v in rows))
                per_seed[str(seed)]=dict(force=force,zero=zero,control=control)
                parts.append(dict(p=p,y=y,control=control));trace_checks[str(f)]=r['checks']
            control={k:(sum(v['control'][k] for v in parts) if k in ('non_timeout_terminations','timeouts') else
                        sum(v['control'][k] for v in parts)/len(parts)) for k in parts[0]['control']}
            control['base_xy_rmse_m_s']=math.sqrt(control.pop('base_xy_mse'));control['yaw_rmse_rad_s']=math.sqrt(control.pop('yaw_mse'))
            p=torch.cat([v['p'] for v in parts]);y=torch.cat([v['y'] for v in parts])
            closed[domain][name]=dict(force=verified(p,y),zero=verified(torch.zeros_like(p),y),control=control,per_seed=per_seed)
    training={}
    for domain in plan['domains']:
        for seed in plan['train_seeds']:
            f=root/f'train_{domain}_{seed}';r=json.loads((f/'result.json').read_text())
            assert r['pass_probe'] and len(r['history'])==200 and r['completed_training_transitions']==614400
            assert r['source_iterations']==8000 and r['final_global_policy_steps']==196800
            assert set(r['fixed_validation_sha256'])==set(plan['monitor_inputs'])
            assert all(frozen['sha256'][p]==h for p,h in r['fixed_validation_sha256'].items())
            assert frozen['frozen_before_training_unix']<(f/'config.json').stat().st_mtime
            training[f'{domain}{seed}']=dict(checks=r['checks'],changes=r['module_change_l2'],force=r['force_curriculum'],
                initial_validation=r['initial_validation'],final_validation=r['final_validation'],restoration=r['restoration'])
    for p,h in protected.items():assert sha(p)==h,p
    result=dict(fixed=fixed,closed=closed,training=training,models=checks,trace_checks=trace_checks,
        independent_float64_metric_checks=len(numerical),protected_unchanged=len(plan['protected_sha256']),
        historical_unchanged=len(plan['historical_sha256']),frozen_validation_unchanged=len(frozen['sha256']),
        formal_training_resumed=False,limitations=['Portable-method bundle cannot isolate one causal difference',
            'Two seeds and 200 rounds are a finite diagnostic, not full convergence',
            'Morphology, drives, COM target, reset/observation packing and pretraining origin remain different',
            'Same source/seed/budget; trajectories and RNG consumption are not paired'])
    torch.save(predictions,root/'cross_predictions.pt')
    (root/'results.json').write_text(json.dumps(result,indent=2,allow_nan=False)+'\n')
    status.update(state='complete',summary=str(root/'results.json'))
    (root/'status.json').write_text(json.dumps(status,indent=2)+'\n')
    print('SHARED_SUMMARY_COMPLETE',str(root),flush=True)


def run_gym_ranger_init_training(args):
    """Finite repaired-initialization validation; reuse the historical control."""
    import hashlib
    import os
    import shutil
    import subprocess
    import time
    def sha(p):
        h=hashlib.sha256()
        with Path(p).open('rb') as f:
            for block in iter(lambda:f.read(1<<20),b''):h.update(block)
        return h.hexdigest()
    root=args.probe_output.resolve();root.mkdir(parents=True,exist_ok=False)
    base=OUT/'gym_ranger_20261024';old=base/'force60_joint_v4'
    prior=json.loads((base/'com_only_v1/plan.json').read_text())
    protected=prior['protected_sha256']
    historical=dict(prior['historical_sha256'])
    for folder in (old,base/'com_only_v1',base/'com_init_repair_adapter_v3',
                   base/'com_init_contact_v3',base/'com_init_repair_preflight_v1'):
        historical.update({str(p):sha(p) for p in folder.rglob('*') if p.is_file()})
    for p,h in {**protected,**historical}.items():assert sha(p)==h,p
    models={'formal':str(ROOT/'logs'/CHECKPOINTS[10000])}
    for s in (133001,133002):
        r=json.loads((old/f'train_seed{s}/result.json').read_text())
        assert r['pass_probe'] and r['source_iterations']==10000
        assert r['completed_training_transitions']==614400 and r['force_max_per_axis_n']==60.
        models[f'legacy{s}']=str(old/f'train_seed{s}/joint_diagnostic.pt')
        models[f'repaired{s}']=str(root/f'train_seed{s}/joint_diagnostic.pt')
    (root/'models.json').write_text(json.dumps(models,indent=2)+'\n')
    py='/home/sorry/.cache/unifp/isaacgym_preview4/torch231/bin/python'
    jobs=[]
    def job(name,mode,seed,extra=()):
        jobs.append(dict(name=name,mode=mode,seed=seed,command=[py,str(Path(__file__).resolve()),
            '--gym_ranger_diagnostic','--gym_force_mode',mode,'--ablation_seed',str(seed),
            '--probe_output',str(root/name),'--gym_ranger_force_max','60',
            '--gym_ranger_init_before_prepare','--gym_ranger_measure_forces',*extra]))
    for s in (136501,136502):job(f'validation_seed{s}','evaluate',s)
    for s in (136601,136602):job(f'holdout_formal_seed{s}','evaluate',s)
    monitor=[str(root/f'validation_seed{s}/validation.pt') for s in (136501,136502)]
    for s in (133001,133002):job(f'train_seed{s}','train',s,
        ('--ablation_iterations','200','--replay_inputs',*monitor))
    for s in (136601,136602):
        for name in models:
            if name!='formal':job(f'replay_{name}_seed{s}','evaluate',s,
                ('--replay_models_json',str(root/'models.json'),'--replay_model',name))
    plan=dict(scope='Only rigid-property initialization timing; random COM remains enabled',
        old_experiment=str(old),source_iterations=10000,source_global_policy_steps=240000,
        train_seeds=[133001,133002],monitor_seeds=[136501,136502],holdout_seeds=[136601,136602],
        train_envs=128,validation_envs=32,rollout=24,iterations=200,replay_steps=2000,
        monitor_inputs=monitor,holdout_used_during_training=False,formal_training_resumed=False,
        intervention='Write the same randomized body properties before prepare_sim instead of after',
        unchanged='Random COM and all other randomization, noise, two 60 N force ranges, official networks/PPO/losses/reward/Adam restoration',
        historical_control_limit='Saved control, not a new simultaneous run; closed-loop trajectories need not match',
        protected_sha256=protected,historical_sha256=historical,audit_sha256=sha(__file__),jobs=jobs)
    (root/'plan.json').write_text(json.dumps(plan,indent=2)+'\n')
    shutil.copy2(__file__,root/'audit_snapshot.py')
    status=dict(state='running',completed_jobs=0,total_jobs=len(jobs))
    def save():
        status['updated_unix']=time.time()
        tmp=root/'status.tmp';tmp.write_text(json.dumps(status,indent=2)+'\n');tmp.replace(root/'status.json')
    env=os.environ.copy();env.update(OMNI_KIT_ACCEPT_EULA='Y',RANGER_ASSET_VERSION='v3_original',
        OMP_NUM_THREADS='2',MKL_NUM_THREADS='2',OPENBLAS_NUM_THREADS='2',MAX_JOBS='2',PYTHONUNBUFFERED='1')
    env['LD_LIBRARY_PATH']='/home/sorry/.cache/unifp/isaacgym_preview4/py38/lib:'+env.get('LD_LIBRARY_PATH','')
    env['PATH']='/home/sorry/.cache/unifp/isaacgym_preview4/py38/bin:'+env['PATH']
    child=None
    try:
        for item in jobs:
            assert sha(__file__)==plan['audit_sha256'],'Source changed during the experiment'
            if item['mode']=='train' and not (root/'frozen_validation.json').exists():
                paths=monitor+[str(root/f'holdout_formal_seed{s}/validation.pt') for s in (136601,136602)]
                frozen=dict(frozen_before_training_unix=time.time(),sha256={p:sha(p) for p in paths},
                    monitor_inputs=monitor,holdout_used_during_training=False)
                (root/'frozen_validation.json').write_text(json.dumps(frozen,indent=2)+'\n')
            status.update(current_job=item['name'],current_iteration=None,job_started_unix=time.time());save()
            print('INIT_TRAIN_JOB_START',item['name'],flush=True)
            with (root/(item['name']+'.log')).open('w') as log:
                child=subprocess.Popen(item['command'],cwd=ROOT,env=env,stdout=log,stderr=subprocess.STDOUT)
                status['pid']=child.pid;save()
                while child.poll() is None:
                    progress=root/item['name']/'progress.json'
                    if progress.exists():
                        try:
                            rows=json.loads(progress.read_text());status['current_iteration']=rows[-1]['iteration'] if rows else 0
                        except json.JSONDecodeError:pass
                    save();time.sleep(1.)
                assert child.returncode==0,f"{item['name']} failed; see {item['name']}.log"
            r=json.loads((root/item['name']/'result.json').read_text())
            assert r['pass_probe'] and r['transport']['rigid_property_initialization']=='before_prepare'
            assert r['command_force_max_per_axis_n']==r['external_force_max_per_axis_n']==60.
            status['completed_jobs']+=1;save()
            print('INIT_TRAIN_JOB_COMPLETE',item['name'],flush=True)
        for p,h in {**protected,**historical,**frozen['sha256']}.items():assert sha(p)==h,p
        status.update(state='experiments_complete',current_job=None,pid=None);save()
    except BaseException as exc:
        if child is not None and child.poll() is None:child.terminate();child.wait(timeout=30)
        status.update(state='failed',error=str(exc));save();raise


def summarize_gym_ranger_init_training(root):
    """Common-input estimates, own-trajectory control, and independent checks."""
    import contextlib
    import hashlib
    import io
    import math
    import numpy as np
    import torch
    from legged_gym.b2_gym_learn.ppo_cse_pf.actor_critic import ActorCritic
    torch.set_num_threads(2)
    assert not (root/'results.json').exists()
    plan=json.loads((root/'plan.json').read_text());old=Path(plan['old_experiment'])
    frozen=json.loads((root/'frozen_validation.json').read_text())
    assert json.loads((root/'status.json').read_text())['state']=='experiments_complete'
    def sha(p):
        h=hashlib.sha256()
        with Path(p).open('rb') as f:
            for block in iter(lambda:f.read(1<<20),b''):h.update(block)
        return h.hexdigest()
    for p,h in {**plan['protected_sha256'],**plan['historical_sha256'],**frozen['sha256']}.items():assert sha(p)==h,p
    paths=json.loads((root/'models.json').read_text())
    for s in plan['train_seeds']:
        for it in (10050,10100,10150):paths[f'repaired{s}_iter{it}']=str(root/f'train_seed{s}/joint_iter_{it:06d}.pt')
    models={};model_checks={}
    for name,path in paths.items():
        ck=torch.load(path,map_location='cpu')
        with contextlib.redirect_stdout(io.StringIO()):
            model=ActorCritic(1856,294,12,58,14,actor_hidden_dims=[512,256,128],critic_hidden_dims=[512,256,128])
        model.load_state_dict(ck['model_state_dict']);model.eval();model.requires_grad_(False);models[name]=model
        steps={k:sorted({float(s['step']) for s in ck[k]['state'].values() if 'step' in s})
            for k in ('optimizer_state_dict','adaptation_optimizer_state_dict')}
        assert all(v==[float(20*ck['iterations'])] for v in steps.values())
        assert ck['global_policy_steps']==24*ck['iterations']
        assert all(torch.isfinite(v).all() for v in model.state_dict().values())
        assert all(torch.isfinite(v).all() for k in steps for s in ck[k]['state'].values()
            for v in s.values() if isinstance(v,torch.Tensor))
        model_checks[name]=dict(sha256=sha(path),iterations=ck['iterations'],adam_steps=steps,finite=True)
    numerical_checks=[]
    def verified(p,y):
        m=auxiliary_metrics(p,y)
        pn=p[:,6:9].numpy().astype(np.float64)*100.;yn=y[:,6:9].numpy().astype(np.float64)*100.
        active=np.linalg.norm(yn,axis=1)>1.;zero=np.linalg.norm(yn,axis=1)<.05
        independent=dict(force_rmse_per_axis_n=float(np.sqrt(np.mean((pn-yn)**2))),
            active_vector_error_n=float(np.linalg.norm(pn[active]-yn[active],axis=1).mean()),
            zero_estimate_norm_n=float(np.linalg.norm(pn[zero],axis=1).mean()))
        assert all(abs(m[k]-v)<1e-4 for k,v in independent.items())
        m['rmse_vs_zero_ratio']=m['force_rmse_per_axis_n']/float(np.sqrt(np.mean(yn**2)))
        numerical_checks.append(independent);return m
    predictions={}
    def cross(label,data):
        x=torch.cat([d['obs'] for d in data]);y=torch.cat([d['target'] for d in data])
        with torch.inference_mode():p={n:torch.cat([m.get_student_latent(b) for b in x.split(512)]) for n,m in models.items()}
        predictions[label]=dict(target=y,predictions=p)
        return dict(samples=len(y),models={n:verified(v,y) for n,v in p.items()},zero=verified(torch.zeros_like(y),y))
    fixed={}
    for label,folders in (
        ('repaired_monitor',[root/f'validation_seed{s}' for s in plan['monitor_seeds']]),
        ('repaired_holdout',[root/f'holdout_formal_seed{s}' for s in plan['holdout_seeds']]),
        ('legacy_validation',[old/f'validation_seed{s}' for s in (133501,133502)])):
        data=[torch.load(f/'validation.pt',map_location='cpu') for f in folders]
        fixed[label]=dict(merged=cross(label,data),per_seed={str(d['seed']):cross(label+'_'+str(d['seed']),[d]) for d in data})
    closed={};cross_behavior={};trace_checks={}
    primary=json.loads((root/'models.json').read_text())
    for name in primary:
        parts=[];per_seed={};tapes=[]
        for seed in plan['holdout_seeds']:
            folder=root/(f'holdout_formal_seed{seed}' if name=='formal' else f'replay_{name}_seed{seed}')
            r=json.loads((folder/'result.json').read_text());assert r['pass_probe'] and r['frozen_model_unchanged']
            t=torch.load(folder/'replay_trace.pt',map_location='cpu');p,y=t['prediction'],t['target']
            force=verified(p,y);zero=verified(torch.zeros_like(y),y)
            for k in ('force_rmse_per_axis_n','active_vector_error_n','zero_estimate_norm_n'):
                assert abs(force[k]-r['force_metrics'][k])<1e-5
            d=torch.load(folder/'validation.pt',map_location='cpu');tapes.append(d)
            with torch.inference_mode():again=torch.cat([models[name].get_student_latent(b) for b in d['obs'].split(512)])
            assert torch.allclose(again,p.reshape(2000,32,12)[::8].reshape(-1,12),atol=1e-5,rtol=1e-5)
            rows=[json.loads(v) for v in (folder/'steps.jsonl').read_text().splitlines()];assert len(rows)==2000
            control={k:sum(v[k] for v in rows)/len(rows) for k in
                ('ee_error_mean_m','ee_force_target_error_mean_m','base_xy_mse','yaw_mse','root_height_mean_m')}
            control.update(non_timeout_terminations=sum(v['dones']-v['timeouts'] for v in rows),timeouts=sum(v['timeouts'] for v in rows))
            per_seed[str(seed)]=dict(force=force,zero=zero,control=control)
            parts.append(dict(p=p,y=y,control=control))
            trace_checks[str(folder)]=dict(sparse_forward=True,sha256=sha(folder/'replay_trace.pt'),checks=r['checks'])
        p=torch.cat([v['p'] for v in parts]);y=torch.cat([v['y'] for v in parts])
        control={k:(sum(v['control'][k] for v in parts) if k in ('non_timeout_terminations','timeouts') else
            sum(v['control'][k] for v in parts)/len(parts)) for k in parts[0]['control']}
        control['base_xy_rmse_m_s']=math.sqrt(control.pop('base_xy_mse'));control['yaw_rmse_rad_s']=math.sqrt(control.pop('yaw_mse'))
        closed[name]=dict(force=verified(p,y),zero=verified(torch.zeros_like(y),y),control=control,per_seed=per_seed)
        cross_behavior[name]=cross('behavior_'+name,tapes)
    training={}
    for seed in plan['train_seeds']:
        folder=root/f'train_seed{seed}';r=json.loads((folder/'result.json').read_text())
        assert r['pass_probe'] and len(r['history'])==200 and r['completed_training_transitions']==614400
        assert r['source_iterations']==10000 and r['source_global_policy_steps']==240000 and r['final_global_policy_steps']==244800
        assert set(r['fixed_validation_sha256'])==set(plan['monitor_inputs'])
        assert all(frozen['sha256'][p]==h for p,h in r['fixed_validation_sha256'].items())
        assert frozen['frozen_before_training_unix']<(folder/'config.json').stat().st_mtime
        new=torch.load(folder/'initial_state.pt',map_location='cpu');previous=torch.load(old/f'train_seed{seed}/initial_state.pt',map_location='cpu')
        paired={}
        for key in ('masses','coms','inertias','root_default'):
            assert torch.equal(new[key],previous[key]),(seed,key)
            paired[key]=0.
        old_config=json.loads((old/f'train_seed{seed}/config.json').read_text())
        dynamics_equal=old_config['dynamics']==r['dynamics'];assert dynamics_equal
        missing=[k for k in ('materials','motor_strength','torch_rng_state') if k not in previous]
        state_differences={k:float((v.double()-previous['state'][k].double()).abs().max())
            for k,v in new['state'].items() if isinstance(v,torch.Tensor)}
        observation_differences={k:float((v.double()-previous['observations'][k].double()).abs().max())
            for k,v in new['observations'].items()}
        tape=torch.load(folder/'first_rollout.pt',map_location='cpu')
        old_tape=torch.load(old/f'train_seed{seed}/first_rollout.pt',map_location='cpu')
        first_frame_differences={k:float((tape[k][0].double()-old_tape[k][0].double()).abs().max())
            for k in ('observations','actions','observation_preds')}
        training[str(seed)]=dict(initial_randomization_max_difference=paired,
            dynamics_summary_equal=dynamics_equal,historical_missing_tensor_fields=missing,
            initial_state_max_difference=state_differences,initial_observation_max_difference=observation_differences,
            first_rollout_first_frame_max_difference=first_frame_differences,
            restoration=r['restoration'],module_change_l2=r['module_change_l2'],checks=r['checks'],
            transitions=r['completed_training_transitions'],elapsed_s=r['elapsed_s'],
            value_loss_max=max(v['value_loss'] for v in r['history']),
            non_timeout_terminations=sum(v['dones']-v['timeouts'] for v in r['history']),
            force_curriculum=r['force_curriculum'],effort=r['effort_diagnostic'])
    result=dict(fixed=fixed,closed_repaired_domain=closed,cross_behavior=cross_behavior,training=training,
        model_checks=model_checks,numerical_metric_checks=len(numerical_checks),trace_checks=trace_checks,
        protected_verified=len(plan['protected_sha256']),historical_verified=len(plan['historical_sha256']),
        frozen_validation_verified=True,holdout_not_used_during_training=True,formal_training_resumed=False,
        limitations=['Two seeds and 200 iterations test early adaptation only',
            'Historical control; corrected geometry changes trajectories and reset/RNG after initialization',
            'Historical initial snapshots omit full material/motor/RNG tensors; compare available tensors and saved dynamics summaries only',
            'Overlapping histories are correlated; no random adjacent-window split or iid confidence claims',
            'Repaired closed loop uses each controller own trajectories and zero baseline; no matched physical tape',
            'Lab-source 10000 checkpoint adaptation, not native Gym training from scratch'])
    torch.save(predictions,root/'cross_predictions.pt')
    (root/'results.json').write_text(json.dumps(result,indent=2,allow_nan=False)+'\n')
    print('INIT_TRAIN_SUMMARY_COMPLETE',len(models),len(trace_checks),len(numerical_checks),flush=True)


def run_gym_ranger_amplitude(args):
    """Sequential finite experiment queue; reuse the completed 15 N control."""
    import os
    import time
    import hashlib
    import shutil
