                    m=fixed['nominal_new'][f'{branch}{seed}_{node}']['all'];text+=f'|{seed}|{branch}|{node}|{m["force_rmse_per_axis_n"]:.3f}|{m["active_vector_error_n"]:.3f}|{m["zero_estimate_norm_n"]:.3f}|\n'
