        original=(root/'project_report_before.txt').read_text();prefix=updated.split('\n\n### 8.75 ')[0]
        pattern=r'<!-- gym-(?:com-action|nominal-training)-current:start -->.*?<!-- gym-(?:com-action|nominal-training)-current:end -->'
