def gym_residual_repro(args):
    """Replay one unchanged environment and detect the existing mean-action gap."""
    import contextlib
    import io
    import torch
    from legged_gym.b2_gym_learn.ppo_cse_pf.actor_critic import ActorCritic
    torch.set_num_threads(1)
    source = OUT / 'gym_joint_replay_control_20261025_v1'
    plan = json.loads((source / 'analysis_plan.json').read_text())
    data = torch.load(source / 'm140001_s153101_mean_initial/data.pt', map_location='cpu', weights_only=False)
    with contextlib.redirect_stdout(io.StringIO()):
        model = ActorCritic(1856, 294, 12, 58, 14, actor_hidden_dims=[512, 256, 128], critic_hidden_dims=[512, 256, 128])
    model.load_state_dict(torch.load(plan['models']['140001_initial'], map_location='cpu', weights_only=False)['model_state_dict'])
    model.eval().requires_grad_(False)
    mask = data['full_history'].clone()
    mask[:, 1:] = False
    with torch.inference_mode():
        prediction = model.get_student_latent(data['obs'][mask])[:, 6:9].double() * 100
    truth = data['target'][mask][:, 6:9].double() * 100
    rmse = float((prediction - truth).square().mean().sqrt())
    zero = float(truth.square().mean().sqrt())
    print(json.dumps(dict(samples=len(truth), environment=0, force_rmse_per_axis_n=rmse,
        constant_zero_rmse_per_axis_n=zero, symptom_reproduced=rmse > zero)), flush=True)
    assert rmse <= zero, 'Existing mean-action estimation gap reproduced; expected diagnostic failure, no new accuracy threshold.'


def gym_residual_strata(args):
    """Stratify frozen retained traces without simulation, fitting, or updates."""
    import ast
    import contextlib
    import hashlib
    import io
    import inspect
    import os
    import shutil
    import numpy as np
    import torch
    from legged_gym.b2_gym_learn.ppo_cse_pf.actor_critic import ActorCritic
    torch.set_num_threads(1)
    os.sched_setaffinity(0, {min(os.sched_getaffinity(0))})
    root = args.probe_output.resolve()
    assert root.parent == OUT.resolve() and root.name.startswith('gym_residual_strata_')
    assert not (root / 'status.json').exists()
    root.mkdir(exist_ok=True)
    source = OUT / 'gym_joint_replay_control_20261025_v1'
    physical = OUT / 'gym_paired_force_20261025_v1'
    policies = ('initial', 'replay_sample', 'replay_mean')
    inputs, checks, models, states = {}, [], {}, {}

    def sha(path):
        result = hashlib.sha256()
        with Path(path).open('rb') as stream:
            for block in iter(lambda: stream.read(8388608), b''):
                result.update(block)
        return result.hexdigest()

    def write(name, value):
        (root / name).write_text(json.dumps(value, indent=2, allow_nan=False) + '\n')

    def read(path, tensor=False):
        inputs[str(path)] = sha(path)
        return torch.load(path, map_location='cpu', weights_only=False) if tensor else json.loads(Path(path).read_text())

    plan = read(source / 'analysis_plan.json')
    config = dict(diagnostic_only=True, training_started=False, simulation_started=False, optimizer_steps=0,
        source=str(source), physical_source=str(physical), models=plan['models'],
        source_model_sha256=plan['source_sha256'], seeds=[140001, 140002],
        hypotheses=['Behavior-conditioned residual false positives persist',
                    'Force incremental response remains attenuated', 'Loading/unloading history dominates residual error'],
        thresholds=dict(active_force_norm_n=1., zero_force_norm_n=.05, full_history_frames=32,
            base_speed_m_s=.1, base_yaw_rate_rad_s=.2, force_change_tolerance_n=.0001),
        feature_cuts='Pooled initial-policy mean/sample complete histories, fixed tertiles; paired physical cuts use zero-force source tapes only',
        masks='Own: full history and reset-aware zero age; paired: common censor mask of all eight branches, at least 32 recorded frames',
        limitations=['Exploratory association is not causal attribution; no new train/test split or fitted correction',
            'Own arm position/speed/PD discrepancy use noisy observation proxies; paired arm features use recorded physics',
            'Initial motor factors used only before first reset; actual implicit torque saturation is not inferred',
            'Two related pretrained seeds; windows and repeated environment streams are not independent trials'])
    write('plan.json', config)
    write('status.json', dict(state='running', training_started=False, simulation_started=False))
    shutil.copy2(__file__, root / 'audit_snapshot.py')
    for path in list(ROOT.glob('*.py')) + list(Path(inspect.getfile(ActorCritic)).parent.glob('*.py')):
        inputs[str(path)] = sha(path)
    formal = ROOT / 'logs' / CHECKPOINTS[10000]
    inputs[str(formal)] = sha(formal)
    for key, path in plan['models'].items():
        assert sha(path) == plan['source_sha256'][path]
        inputs[path] = sha(path)
        with contextlib.redirect_stdout(io.StringIO()):
            model = ActorCritic(1856, 294, 12, 58, 14, actor_hidden_dims=[512, 256, 128], critic_hidden_dims=[512, 256, 128])
        model.load_state_dict(torch.load(path, map_location='cpu', weights_only=False)['model_state_dict'])
        model.eval().requires_grad_(False)
        models[key] = model
        states[key] = {k: v.clone() for k, v in model.state_dict().items()}
    evidence = read(source / 'cross_predictions.pt', True)
    paired_predictions = read(source / 'paired_force_predictions.pt', True)
    original = read(source / 'results.json')
    phase_names = ('sustained_zero_32_63', 'sustained_zero_64_127', 'sustained_zero_128_plus',
                   'active_changing', 'active_held32', 'zero_recent', 'intermediate')

    def age_of(flag, reset):
        age = np.zeros(flag.shape[1], dtype=np.int64)
        result = []
        for flag_row, reset_row in zip(flag, reset):
            age = np.where(flag_row, np.where(reset_row, 1, age + 1), 0)
            result.append(age.copy())
        return np.stack(result)

    def rms(value):
        return np.sqrt(np.mean(np.asarray(value, dtype=np.float64) ** 2, axis=-1))

    def motion(xy, yaw):
        return np.where(np.abs(yaw) > .2, 2, np.where(np.linalg.norm(xy, axis=-1) > .1, 1, 0))

    def metric(prediction, truth, sustained, selected):
        prediction, truth, sustained = prediction[selected], truth[selected], sustained[selected]
        if not len(truth):
            return dict(samples=0)
        error = prediction - truth
        norm = np.linalg.norm(truth, axis=-1)
        active, zero = norm > 1., norm < .05
        return dict(samples=len(truth), force_rmse_per_axis_n=float(rms(error.reshape(-1))[()]),
            constant_zero_rmse_per_axis_n=float(np.sqrt(np.mean(truth ** 2))),
            axis_rmse_n=np.sqrt(np.mean(error ** 2, axis=0)).tolist(),
            error_mean_yaw_n=error.mean(0).tolist(), active_samples=int(active.sum()),
            active_vector_error_n=float(np.linalg.norm(error[active], axis=-1).mean()) if active.any() else None,
            active_zero_baseline_n=float(norm[active].mean()) if active.any() else None,
            zero_samples=int(zero.sum()), zero_estimate_norm_n=float(np.linalg.norm(prediction[zero], axis=-1).mean()) if zero.any() else None,
            sustained_zero_samples=int(sustained.sum()),
            sustained_zero_norm_n=float(np.linalg.norm(prediction[sustained], axis=-1).mean()) if sustained.any() else None)

    own = []
    for job in plan['jobs']:
        folder = source / job['name']
        data, control, initial = [read(folder / f, True) for f in ('data.pt', 'control.pt', 'initial_state.pt')]
        saved = evidence[job['name']]
        mask = data['full_history']
        assert torch.equal(mask.nonzero(), saved['valid_index'])
        assert torch.equal(data['target'][mask], saved['target'])
        assert torch.equal(data['sustained_zero'][mask], saved['sustained_zero'])
        # Rebuild FIFO exactly once per saved frame; resets precede the append.
        history = data['initial_history'].reshape(32, 32, 58).clone()
        ages = torch.ones(32, dtype=torch.long)
        valid, cursor = [], 0
        for step in range(1000):
            done = data['done'][step]
            history[done] = 0
            history[:, :-1] = history[:, 1:].clone()
            history[:, -1] = data['frame'][step]
            ages = torch.where(done, torch.ones_like(ages), ages + 1)
            if step >= 64 and step % 8 == 0:
                assert torch.equal(history.flatten(1).clamp(-100, 100), data['obs'][cursor])
                assert torch.equal(data['all_target'][step], data['target'][cursor])
                valid.append(ages >= 32)
                cursor += 1
        assert torch.equal(torch.stack(valid), mask)
        x = data['obs'][mask]
        chosen = torch.linspace(0, len(x) - 1, 64).long()
        for policy in policies:
            with torch.inference_mode():
                prediction = models[f"{job['training_seed']}_{policy}"].get_student_latent(x[chosen])
            delta = float((prediction - saved['predictions'][policy][chosen]).abs().max()) * 100
            assert delta < .005
            checks.append(dict(job=job['name'], model=policy, forward_max_delta_n=delta))
        times = data['times'].numpy()
        slots = saved['valid_index'].numpy()
        sample_time, sample_env = times[slots[:, 0]], slots[:, 1]
        frame = data['frame'].double().numpy()[sample_time, sample_env]
        truth_all = data['all_target'][:, :, 6:9].double().numpy() * 100
        done = data['done'].numpy()
        zero_age = age_of(np.linalg.norm(truth_all, axis=-1) < .05, done)
        assert np.array_equal(zero_age[sample_time, sample_env] >= 32, saved['sustained_zero'].numpy())
        force = data['force_world'].double().numpy()
        stable = np.linalg.norm(np.diff(force, axis=0, prepend=force[0:1]), axis=-1) <= .0001
        force_age = age_of(stable, done)[sample_time, sample_env]
        zero_age = zero_age[sample_time, sample_env]
        truth = saved['target'][:, 6:9].double().numpy() * 100
        norm = np.linalg.norm(truth, axis=-1)
        phase = np.full(len(truth), 6)
        phase[(norm < .05) & (zero_age < 32)] = 5
        phase[(norm > 1) & (force_age < 32)] = 3
        phase[(norm > 1) & (force_age >= 32)] = 4
        phase[(zero_age >= 32) & (zero_age < 64)] = 0
        phase[(zero_age >= 64) & (zero_age < 128)] = 1
        phase[zero_age >= 128] = 2
        commands = control['commands'].double().numpy()[sample_time, sample_env]
        xy = control['base_velocity'].double().numpy()[sample_time, sample_env, :2]
        yaw_rate = control['base_angular_velocity'].double().numpy()[sample_time, sample_env, 2]
        before_reset = ~np.maximum.accumulate(done, axis=0)[sample_time, sample_env]
        features = dict(arm_position_observed_rms_rad=rms(frame[:, 9:15]),
            arm_speed_observed_rms_rad_s=rms(frame[:, 23:29] / .05),
            arm_action_rms=rms(frame[:, 37:43]), steer_action_rms=rms(frame[:, 29:33]),
            drive_action_rms=rms(frame[:, 33:37]),
            arm_pd_position_observed_proxy_rad=rms(.25 * frame[:, 37:43] - frame[:, 9:15]),
            base_speed_m_s=np.linalg.norm(xy, axis=-1), base_yaw_rate_abs_rad_s=np.abs(yaw_rate),
            commanded_force_norm_n=np.linalg.norm(commands[:, 9:12], axis=-1),
            base_push_force_norm_n=np.linalg.norm(control['base_force_world'].numpy()[sample_time, sample_env], axis=-1),
            base_mass_kg=initial['masses'].numpy()[sample_env, 0],
            friction=initial['materials'].numpy()[sample_env, 0, 0])
        for name, interval in [('arm_motor', slice(8, 14)), ('steer_motor', slice(0, 4)), ('drive_motor', slice(4, 8))]:
            features[name] = np.where(before_reset, initial['motor_strength'].numpy()[sample_env, interval].mean(-1), np.nan)
        predictions = {p: saved['predictions'][p][:, 6:9].double().numpy() * 100 for p in policies}
        own.append(dict(job=job, truth=truth, predictions=predictions, features=features, phase=phase,
                        sustained=saved['sustained_zero'].numpy(), motion=motion(xy, yaw_rate)))
        for policy in policies:
            got = metric(predictions[policy], truth, saved['sustained_zero'].numpy(), np.ones(len(truth), bool))
            expected = original['per_replay'][job['name']]['cross'][policy]
            for key in ('force_rmse_per_axis_n', 'active_vector_error_n', 'sustained_zero_norm_n'):
                assert abs(got[key] - expected[key]) < 1e-7
        print('RESIDUAL_OWN_VERIFIED', job['name'], flush=True)
    feature_names = list(own[0]['features'])
    cuts = {}
    for name in feature_names:
        values = np.concatenate([r['features'][name] for r in own if r['job']['policy'] == 'initial'])
        cuts[name] = np.quantile(values[np.isfinite(values)], [1/3, 2/3]).tolist()
    write('own_feature_cuts.json', cuts)
    own_results = {}
    for seed in (140001, 140002):
        for behavior in ('mean', 'sample'):
            for trajectory in policies:
                records = [r for r in own if r['job']['training_seed'] == seed and r['job']['behavior'] == behavior and r['job']['policy'] == trajectory]
                truth, sustained, phase, movement = [np.concatenate([r[k] for r in records]) for k in ('truth', 'sustained', 'phase', 'motion')]
                features = {f: np.concatenate([r['features'][f] for r in records]) for f in feature_names}
                for policy in policies:
                    prediction = np.concatenate([r['predictions'][policy] for r in records])
                    row = dict(all=metric(prediction, truth, sustained, np.ones(len(truth), bool)),
                        phases={name: metric(prediction, truth, sustained, phase == i) for i, name in enumerate(phase_names)},
                        motion={name: metric(prediction, truth, sustained, movement == i) for i, name in enumerate(('stationary', 'straight', 'turning'))},
                        sustained_zero_features={})
                    for name, value in features.items():
                        bins = np.digitize(value, cuts[name])
                        row['sustained_zero_features'][name] = [metric(prediction, truth, sustained,
                            sustained & np.isfinite(value) & (bins == i)) for i in range(3)]
                    own_results[f'{seed}/{behavior}/{trajectory}/{policy}'] = row
    write('own_strata.json', own_results)

    physical_plan = read(physical / 'plan.json')
    groups = {}
    for seed in (140001, 140002):
        for behavior in ('mean', 'steer'):
            jobs = [j for j in physical_plan['jobs'] if j['model_seed'] == seed and j['behavior'] == behavior]
            tapes = {j['branch']: read(physical / j['name'] / 'tape.pt', True) for j in jobs}
            common = ~torch.stack([v['censored'] for v in tapes.values()]).any(0).numpy()
            masks = read(physical / f'masks_{seed}_{behavior}.pt', True)
            assert np.array_equal(common, masks['common_valid'].numpy())
            common &= np.arange(512)[:, None] >= 31
            base = tapes['source']
            for branch, data in tapes.items():
                assert torch.equal(data['actions'], base['actions'])
                assert torch.equal(data['actual_target_q'], base['actual_target_q'])
                frames = torch.cat([data['initial_history'].reshape(32, 32, 58).transpose(0, 1), data['frame']], 0)
                rebuilt = torch.stack([frames[int(t)+1:int(t)+33].transpose(0, 1).reshape(32, 1856) for t in data['sparse_times']]).clamp(-100, 100)
                assert torch.equal(rebuilt, data['sparse_obs'])
                positions = torch.linspace(0, rebuilt.numel() // 1856 - 1, 32).long()
                for policy in policies:
                    with torch.inference_mode():
                        prediction = models[f'{seed}_{policy}'].get_student_latent(rebuilt.reshape(-1, 1856)[positions])
                    expected = paired_predictions[f'{seed}/{behavior}'][branch][policy][data['sparse_times']].reshape(-1, 12)[positions]
                    delta = float((prediction - expected).abs().max()) * 100
                    assert delta < .005
                    checks.append(dict(group=f'{seed}/{behavior}/{branch}', model=policy, forward_max_delta_n=delta))
            q, dq = base['q'].numpy(), base['dq'].numpy()
            arm_home = np.array([0., 1., -1.5, 0., 0., 0.])
            features = dict(arm_speed_rms_rad_s=rms(dq[:, :, 8:]), arm_home_distance_rad=rms(q[:, :, 8:] - arm_home),
                arm_target_discrepancy_rad=rms(base['actual_target_q'].numpy()[:, :, 8:] - q[:, :, 8:]),
                steer_speed_rms_rad_s=rms(dq[:, :, :4]), drive_speed_rms_rad_s=rms(dq[:, :, 4:8]),
                base_yaw_rate_abs_rad_s=np.abs(base['root_vel'].numpy()[:, :, 5]),
                commanded_force_norm_n=np.linalg.norm(base['commands'].numpy()[:, :, 9:12], axis=-1))
            groups[f'{seed}/{behavior}'] = dict(tapes=tapes, common=common, features=features)
    physical_cuts = {f: np.quantile(np.concatenate([g['features'][f][g['common']] for g in groups.values()]), [1/3, 2/3]).tolist() for f in features}
    write('physical_feature_cuts.json', physical_cuts)
    intervals = dict(pre_zero=(96, 160), loading=(160, 192), settling=(192, 224), plateau=(224, 288),
        unloading=(288, 320), recovery_0_31=(320, 352), recovery_32_63=(352, 384),
        recovery_64_127=(384, 448), recovery_128_191=(448, 512))

    def world(data, prediction):
        q = data['root_quat'].double().numpy()
        w, x, y, z = np.moveaxis(q, -1, 0)
        angle = np.arctan2(2*(w*z+x*y), 1-2*(y*y+z*z))
        c, s = np.cos(angle), np.sin(angle)
        return np.stack([c*prediction[:, :, 0]-s*prediction[:, :, 1], s*prediction[:, :, 0]+c*prediction[:, :, 1], prediction[:, :, 2]], -1)

    physical_results = {}
    for group, g in groups.items():
        tapes, common = g['tapes'], g['common']
        source_tape = tapes['source']
        for policy in policies:
            predictions = {b: world(d, paired_predictions[group][b][policy][:, :, 6:9].double().numpy()*100) for b, d in tapes.items()}
            truths = {b: d['force_world'].double().numpy() for b, d in tapes.items()}
            base_error = predictions['source'] - truths['source']

            def response(mask):
                count = int(mask.sum())
                if not count:
                    return dict(samples_per_direction=0)
                errors, residuals, biases, cross_terms, directions = [], [], [], [], {}
                for branch in ('x+1', 'x-1', 'y+1', 'y-1', 'z+1', 'z-1'):
                    delta = (predictions[branch] - predictions['source'])[mask]
                    delta_truth = (truths[branch] - truths['source'])[mask]
                    residual = delta - delta_truth
                    bias = base_error[mask]
                    error = (predictions[branch] - truths[branch])[mask]
                    denominator = np.sum(delta_truth ** 2)
                    directions[branch] = float(np.sum(delta * delta_truth) / denominator) if denominator > 0 else None
                    np.testing.assert_allclose(error, bias + residual, atol=1e-10, rtol=1e-10)
                    errors.append(error); residuals.append(residual); biases.append(bias); cross_terms.append(2 * bias * residual)
                error, residual, bias, cross = [np.concatenate(x) for x in (errors, residuals, biases, cross_terms)]
                absolute_mse, bias_mse, response_mse, interaction = [float(np.mean(x ** 2)) for x in (error, bias, residual)] + [float(cross.mean())]
                assert abs(absolute_mse - bias_mse - response_mse - interaction) < 1e-7
                gains = [v for v in directions.values() if v is not None]
                return dict(samples_per_direction=count, direction_gain=directions,
                    mean_direction_gain=float(np.mean(gains)) if gains else None,
                    absolute_force_rmse_per_axis_n=absolute_mse**.5, baseline_error_rmse_per_axis_n=bias_mse**.5,
                    incremental_residual_rmse_per_axis_n=response_mse**.5,
                    baseline_error_mse_n2=bias_mse, incremental_residual_mse_n2=response_mse,
                    interaction_n2=interaction, mse_identity_error_n2=abs(absolute_mse-bias_mse-response_mse-interaction),
                    force_induced_zero_response_norm_n=float(np.linalg.norm(np.concatenate([(predictions[b]-predictions['source'])[mask] for b in ('x+1','x-1','y+1','y-1','z+1','z-1')]), axis=-1).mean()))

            phases = {}
            for name, (start, stop) in intervals.items():
                mask = common & (np.arange(512)[:, None] >= start) & (np.arange(512)[:, None] < stop)
                answer = response(mask)
                answer['source_prediction_norm_n'] = float(np.linalg.norm(predictions['source'][mask], axis=-1).mean()) if mask.any() else None
                answer['loaded_or_recovered_prediction_norm_n'] = float(np.linalg.norm(np.concatenate([predictions[b][mask] for b in ('x+1','x-1','y+1','y-1','z+1','z-1')]), axis=-1).mean()) if mask.any() else None
                phases[name] = answer
            np.testing.assert_allclose(phases['plateau']['mean_direction_gain'], original['physical_response'][group][policy]['mean_direction_gain'], atol=2e-6)
            plateau = common & (np.arange(512)[:, None] >= 224) & (np.arange(512)[:, None] < 288)
            strata = {f: [response(plateau & (np.digitize(v, physical_cuts[f]) == i)) for i in range(3)] for f, v in g['features'].items()}
            symmetric = {}
            for axis in 'xyz':
                delta = (predictions[axis+'+1'] - predictions[axis+'-1'])[plateau] / 2
                truth = (truths[axis+'+1'] - truths[axis+'-1'])[plateau] / 2
                symmetric[axis] = float(np.sum(delta*truth)/np.sum(truth**2)) if len(truth) else None
            physical_results[f'{group}/{policy}'] = dict(phases=phases, plateau_features=strata, symmetric_gain=symmetric)
            print('RESIDUAL_PHYSICAL_VERIFIED', group, policy, flush=True)
    write('physical_strata.json', physical_results)
    for key, model in models.items():
        assert all(torch.equal(value, states[key][name]) for name, value in model.state_dict().items())
        assert all(not p.requires_grad and p.grad is None for p in model.parameters())
    for path, expected in inputs.items():
        assert sha(path) == expected, path
    if (root / 'audit_before.py').exists():
        definitions = lambda p: {n.name: ast.dump(n, include_attributes=False) for n in ast.parse(Path(p).read_text()).body if isinstance(n, (ast.FunctionDef, ast.ClassDef))}
        old, current = definitions(root / 'audit_before.py'), definitions(__file__)
        assert all(current[name] == value for name, value in old.items())
    write('input_sha256.json', inputs)
    write('verification.json', dict(all_passed=True, models_frozen=6, optimizer_steps=0,
        simulation_started=False, training_started=False, own_trajectories=len(own), physical_trajectories=32,
        existing_metrics_reproduced=True, forward_checks=checks, source_files_unchanged=len(inputs),
        old_functions_unchanged=True, decomposition_identity_checked=True))
    write('results.json', dict(own='own_strata.json', physical='physical_strata.json', protocol=config,
        limitations=config['limitations']))
    write('status.json', dict(state='complete', training_started=False, simulation_started=False, optimizer_steps=0))
    print('RESIDUAL_STRATA_COMPLETE', root, flush=True)


def summarize_gym_residual_strata(args):
    """Write a compact quantitative summary and an exportable residual figure."""
    import numpy as np
    import matplotlib
    matplotlib.use('Agg')
    import matplotlib.pyplot as plt
    root = args.probe_output.resolve()
    assert not (root / 'summary.json').exists()
    read = lambda name: json.loads((root / name).read_text())
    assert read('verification.json')['all_passed']
    own, physical = read('own_strata.json'), read('physical_strata.json')
    policies = ('initial', 'replay_sample', 'replay_mean')
    summary = dict(persistent_zero={}, fixed_input_persistent_zero={}, mean_motion={}, paired_mean={},
        plateau_gain_ranges={}, single_dynamics_cause_identified=False,
        feature_note_zh='base_push_force_norm_n在原始分层输出中实际对应记录的base_force_world范数，不代表速度型推扰事件；其切点均为0，不能据此判断推扰作用。电机分层排除了首次reset之后的数据。',
        conclusion_zh='均值覆盖主要降低行为相关基线误报；真实受力增量不足仍广泛存在。持续零力与平台残差不支持仅以卸力过渡或某一个当前已测状态解释。',
        next_step_zh='优先在保持50%均值回放配比及其它条件不变时，做预定节点的有限延长验证；同时监测两行为域、零力、增量增益和控制。尚无依据直接关闭某个动力学随机项。')
    for seed in (140001, 140002):
        seed_key = str(seed)
        summary['persistent_zero'][seed_key] = {}
        summary['fixed_input_persistent_zero'][seed_key] = {}
        summary['paired_mean'][seed_key] = {}
        for policy in policies:
            answer = own[f'{seed}/mean/{policy}/{policy}']
            fixed = own[f'{seed}/mean/initial/{policy}']
            summary['persistent_zero'][seed_key][policy] = {k: v for k, v in answer['phases'].items() if k.startswith('sustained_zero')}
            summary['fixed_input_persistent_zero'][seed_key][policy] = {k: v for k, v in fixed['phases'].items() if k.startswith('sustained_zero')}
            row = physical[f'{seed}/mean/{policy}']
            summary['paired_mean'][seed_key][policy] = dict(plateau=row['phases']['plateau'],
                pre_zero=row['phases']['pre_zero'], late_recovery=row['phases']['recovery_128_191'],
                symmetric_gain=row['symmetric_gain'])
        summary['mean_motion'][seed_key] = own[f'{seed}/mean/replay_mean/replay_mean']['motion']
        for behavior in ('mean', 'steer'):
            row = physical[f'{seed}/{behavior}/replay_mean']
            summary['plateau_gain_ranges'][f'{seed}/{behavior}'] = {
                name: dict(gain_min=min(v['mean_direction_gain'] for v in values if v['samples_per_direction']),
                    gain_max=max(v['mean_direction_gain'] for v in values if v['samples_per_direction']),
                    samples=[v['samples_per_direction'] for v in values])
                for name, values in row['plateau_features'].items()}
    (root / 'summary.json').write_text(json.dumps(summary, indent=2, ensure_ascii=False, allow_nan=False)+'\n')
    fig, axes = plt.subplots(2, 2, figsize=(12, 8))
    labels = ['Initial', 'Sample replay', 'Mean replay']
    colors = ['#737373', '#e08d3c', '#2685aa']
    positions = np.arange(2)
    for i, policy in enumerate(policies):
        values = [summary['persistent_zero'][str(seed)][policy]['sustained_zero_128_plus']['sustained_zero_norm_n'] for seed in (140001, 140002)]
        axes[0, 0].bar(positions + (i-1)*.24, values, width=.24, label=labels[i], color=colors[i])
    axes[0, 0].set(xticks=positions, xticklabels=['140001', '140002'], ylabel='Mean predicted force norm (N)',
        title='Own mean-action rollout: zero force for >=128 frames')
    axes[0, 0].legend(fontsize=8)
    for i, (field, label) in enumerate([('baseline_error_rmse_per_axis_n', 'Zero-force baseline error'),
                                      ('incremental_residual_rmse_per_axis_n', 'Incremental response error')]):
        values = [summary['paired_mean'][str(seed)][policy]['plateau'][field] for seed in (140001, 140002) for policy in ('initial', 'replay_mean')]
        axes[0, 1].bar(np.arange(4)+(i-.5)*.35, values, width=.35, label=label)
    axes[0, 1].set(xticks=np.arange(4), xticklabels=['S1 initial', 'S1 mean', 'S2 initial', 'S2 mean'],
        ylabel='RMSE (N/axis)', title='Same-action plateau: separate error terms')
    axes[0, 1].legend(fontsize=8)
    for i, (behavior, marker) in enumerate([('mean', 'o'), ('steer', '^')]):
        for j, seed in enumerate((140001, 140002)):
            values = [physical[f'{seed}/{behavior}/{p}']['phases']['plateau']['mean_direction_gain'] for p in policies]
            axes[1, 0].plot(range(3), values, marker=marker, linestyle='-' if j == 0 else '--', label=f'{seed} / {behavior}')
    axes[1, 0].axhline(1, color='black', linestyle=':', linewidth=1)
    axes[1, 0].set(xticks=range(3), xticklabels=labels, ylim=(0, 1.05), ylabel='Six-direction mean gain (ideal 1)',
        title='Same-action force response remains attenuated')
    axes[1, 0].legend(fontsize=8)
    for i, seed in enumerate((140001, 140002)):
        values = [summary['mean_motion'][str(seed)][state]['sustained_zero_norm_n'] for state in ('stationary', 'straight', 'turning')]
        axes[1, 1].bar(np.arange(3)+(i-.5)*.35, values, width=.35, label=str(seed))
    axes[1, 1].set(xticks=range(3), xticklabels=['Base near still', 'Translating', 'Rotating'],
        ylabel='Sustained-zero prediction norm (N)', title='Mean-replay candidates: residual spans base states')
    axes[1, 1].legend(fontsize=8)
    for ax in axes.flat:
        ax.grid(axis='y', alpha=.2)
        ax.set_axisbelow(True)
    fig.tight_layout()
    fig.savefig(root / 'residual_summary.png', dpi=160)
    plt.close(fig)
    print('RESIDUAL_SUMMARY_COMPLETE', root, flush=True)


def gym_replay_extension_train(args):
    """Resume the audited 50% mean replay learner; change only its budget."""
    edits = [
        ("source['iterations']==9000 and source['global_policy_steps']==216000", "source['iterations']==9200 and source['global_policy_steps']==220800", 1),
        ("bank_path=Path(plan['mean_banks'][str(seed)])", "bank_path=Path(plan['replay_banks'][str(seed)]['mean'])", 1),
        ("keep=bank['full_history'];bank_x", "keep=torch.load(plan['common_masks'][str(seed)],map_location='cpu');assert keep.dtype==torch.bool and torch.all(~keep|bank['full_history']);bank_x", 1),
        ("job['policy']=='mixed'", "job['policy']=='replay_mean'", 2),
        ("iteration==1 and job['policy']=='sample_only'", "False", 1),
        ("generator=torch.Generator().manual_seed(job['seed']+210000);bank_indices=[]", "generator=torch.Generator().manual_seed(job['seed']+210000)\n        for _ in range(plan['previous_auxiliary_updates']):torch.randint(len(bank_x),(384,),generator=generator)\n        bank_indices=[]", 1),
        ('g=torch.Generator().set_state(torch.get_rng_state());permutations.append(torch.randperm(3072,generator=g))\n            yield from original_generator(batches,epochs)',
         "batch_seed=job['seed']+220000+plan['previous_iterations']+len(permutations);g=torch.Generator().manual_seed(batch_seed);permutations.append(torch.randperm(3072,generator=g))\n            ambient=torch.get_rng_state();torch.manual_seed(batch_seed);iterator=original_generator(batches,epochs)\n            try:first=next(iterator)\n            finally:torch.set_rng_state(ambient)\n            assert torch.equal(first[0],alg.storage.observations.flatten(0,1)[permutations[-1][:768]])\n            yield first\n            yield from iterator", 1),
        ("iterations=9000+iteration", "iterations=9200+iteration", 1),
        ("learning_rate=alg.learning_rate,diagnostic_only=True", "learning_rate=alg.learning_rate,replay_generator_state=generator.get_state(),minibatch_index_offset=plan['previous_iterations']+iteration,rng_state=torch.get_rng_state(),diagnostic_only=True", 1),
        ("env.global_policy_steps==220800", "env.global_policy_steps==225600", 1),
    ]
    gym_replay_control_function(gym_joint_coverage_train, edits, '<replay_extension_train>')(args)


