def summarize_gym_replay_extension(args):
    """Reuse independent closed-loop scoring and verify resumed Adam/draw state."""
    import ast
    import hashlib
    import inspect
    import textwrap
    import torch
    root=args.probe_output.resolve()
    read=lambda p:json.loads(Path(p).read_text())
    load=lambda p:torch.load(p,map_location='cpu',weights_only=False)
    plan=read(root/'plan.json')
    source=textwrap.dedent(inspect.getsource(summarize_gym_coverage_closed_loop))
    source=source.split("    text='''",1)[0]
    edits=[
        ("plan=read(root/'plan.json')", "plan=read(root/'analysis_plan.json')", 1),
        ("policies=('initial','sample_only','mixed')", "policies=('initial','add50','add100','add200')", 1),
        ('149101','155101',2), ('149102','155102',2),
        ("    for seed in (140001,140002):\n        for behavior in ('mean','steer'):", "    old_physical=torch.load(OUT/'gym_joint_replay_control_20261025_v1/paired_force_predictions.pt',map_location='cpu',weights_only=False)\n    for seed in (140001,140002):\n        for behavior in ('mean','steer'):", 1),
        ("d['prediction']['9000']", "old_physical[f'{seed}/{behavior}'][j['branch']]['replay_mean']", 1),
    ]
    for before,after,count in edits:
        assert source.count(before)==count,(before,source.count(before),count)
        source=source.replace(before,after)
    namespace={};exec(compile(source,'<replay_extension_independent_scorer>','exec'),globals(),namespace)
    namespace['summarize_gym_coverage_closed_loop'](args)
    checks={}
    for job in plan['training_jobs']:
        folder=root/job['name'];seed=job['model_seed'];initial=load(plan['models'][f'{seed}_initial'])
        r=read(folder/'result.json');assert r['all_passed'] and r['ppo_updates']==4000 and r['auxiliary_updates']==4000
        assert all(v['independent_tensors'] for v in r['restoration'].values())
        assert r['checks']['labels']==4800 and r['checks']['history']==4800 and r['checks']['timeouts']==4800
        order=load(folder/'sample_order.pt');permutations=order['minibatch_permutations']
        expected=torch.stack([torch.randperm(3072,generator=torch.Generator().manual_seed(job['seed']+220000+200+i)) for i in range(200)])
        assert torch.equal(permutations,expected)
        bank_count=int(load(plan['common_masks'][str(seed)]).sum());g=torch.Generator().manual_seed(job['seed']+210000)
        for _ in range(4000):torch.randint(bank_count,(384,),generator=g)
        expected=torch.stack([torch.randint(bank_count,(384,),generator=g) for _ in range(4000)])
        assert torch.equal(expected,order['bank_indices'])
        for node in (50,100,200):
            ck=load(folder/f'joint_iter_{node:04d}.pt')
            assert ck['iterations']==9200+node and ck['global_policy_steps']==220800+24*node
            for key in ('optimizer_state_dict','adaptation_optimizer_state_dict'):
                assert ck[key]['state'].keys()==initial[key]['state'].keys()
                for pid,st in ck[key]['state'].items():
                    assert float(st['step'])==float(initial[key]['state'][pid]['step'])+node*20
                    assert all(torch.isfinite(t).all() for t in st.values() if isinstance(t,torch.Tensor))
            assert ck['adaptation_optimizer_state_dict']['param_groups']==initial['adaptation_optimizer_state_dict']['param_groups']
            assert ck['optimizer_state_dict']['param_groups'][0]['lr']==ck['learning_rate']
            assert ck['minibatch_index_offset']==200+node
            assert all(torch.isfinite(t).all() for t in ck['model_state_dict'].values())
        assert torch.equal(ck['replay_generator_state'],g.get_state())
        deltas={module:float(sum((v-initial['model_state_dict'][k]).double().square().sum() for k,v in ck['model_state_dict'].items() if k.startswith(module)).sqrt())
            for module in ('actor_body','critic_body','adaptation_encoder_module','adaptation_decoder_module')}
        assert all(v>0 for v in deltas.values())
        checks[str(seed)]=dict(ppo_updates=4000,auxiliary_updates=4000,permutations_verified=200,replay_draws_verified=4000,continuation_draw_offset=4000,bank_samples=bank_count,restoration=r['restoration'],checks=r['checks'],module_delta_l2=deltas)
    definitions=lambda p:{n.name:ast.dump(n,include_attributes=False) for n in ast.parse(Path(p).read_text()).body if isinstance(n,(ast.FunctionDef,ast.ClassDef))}
    old=definitions(root/'audit_before.py');new=definitions(__file__);assert all(new[k]==v for k,v in old.items())
    sha=lambda p:hashlib.sha256(Path(p).read_bytes()).hexdigest()
    for p,h in read(root/'protected_sha256.json').items():assert sha(p)==h,p
    for p,h in read(root/'frozen_holdout_sha256.json').items():assert sha(p)==h,p
    result=dict(all_passed=True,training=checks,old_functions_unchanged=len(old),evaluation_optimizer_steps=0,total_new_ppo_updates=8000,total_new_auxiliary_updates=8000,formal_training_resumed=False,physics_restart=True)
    (root/'completion_verification.json').write_text(json.dumps(result,indent=2)+'\n')
    (root/'status.json').write_text(json.dumps(dict(state='complete',formal_training_resumed=False,iterations_added_per_seed=200,diagnostic_iteration=9400),indent=2)+'\n')
    print('REPLAY_EXTENSION_COMPLETE',root,flush=True)


