def run_gym_replay_refresh(args):
    """Freeze fresh banks and new holdouts, then paired bounded joint updates."""
    import ast
    import datetime
    import hashlib
    import os
    import subprocess
    import torch
    root=args.probe_output.resolve();assert root==(OUT/'gym_replay_refresh_20261026_v1').resolve()
    read=lambda p:json.loads(Path(p).read_text())
    def write(p,v):Path(p).write_text(json.dumps(v,indent=2,allow_nan=False)+'\n')
    def sha(p):
        h=hashlib.sha256()
        with Path(p).open('rb') as f:
            for chunk in iter(lambda:f.read(8388608),b''):h.update(chunk)
        return h.hexdigest()
    previous=OUT/'gym_replay_extension_20261026_v1';old_plan=read(previous/'plan.json')
    assert read(previous/'completion_verification.json')['all_passed']
    for p,h in read(root/'protected_sha256.json').items():assert sha(p)==h,p
    defs=lambda p:{n.name:ast.dump(n,include_attributes=False) for n in ast.parse(Path(p).read_text()).body if isinstance(n,(ast.FunctionDef,ast.ClassDef))}
    old=defs(root/'audit_before.py');new=defs(__file__);assert all(new[k]==v for k,v in old.items())
    if not (root/'plan.json').exists():
        models={};jobs=[];banks=[];training=[];replay={};masks={}
        for seed in (140001,140002):
            models[f'{seed}_initial']=old_plan['models'][f'{seed}_initial']
            for policy in ('replay_old','replay_fresh'):
                models[f'{seed}_{policy}']=str(root/f'train_{seed}_{policy}/joint_iter_0200.pt')
                training.append(dict(name=f'train_{seed}_{policy}',model_seed=seed,seed=152001+seed-140001,policy=policy,replay_behavior=policy.split('_')[1]))
            sim=146001+seed-140001
            name=f'bank_m{seed}_s{sim}_mean'
            banks.append(dict(name=name,model_seed=f'{seed}_initial',training_seed=seed,seed=sim,behavior='mean',policy='initial',envs=128,split='training_bank'))
            replay[str(seed)]=dict(old=old_plan['replay_banks'][str(seed)]['mean'],fresh=str(root/name/'data.pt'))
            masks[str(seed)]=str(root/f'common_mask_{seed}.pt')
            for sim in (157101,157102):
                for behavior in ('mean','sample'):
                    for policy in ('initial','replay_old','replay_fresh'):
                        jobs.append(dict(name=f'm{seed}_s{sim}_{behavior}_{policy}',model_seed=f'{seed}_{policy}',training_seed=seed,seed=sim,behavior=behavior,policy=policy,envs=32,split='validation'))
        snapshot=root/'execution_snapshot.py';snapshot.write_text('__file__ = '+repr(str(Path(__file__).resolve()))+'\n'+Path(__file__).read_text())
        plan=dict(diagnostic_only=True,formal_training_resumed=False,created_local=datetime.datetime.now().astimezone().isoformat(),
            iterations=200,nodes=[50,100,200],collection_steps=1000,bank_collection_steps=2400,models=models,jobs=jobs,bank_jobs=banks,training_jobs=training,
            gym_python=old_plan['gym_python'],launch_environment=old_plan['launch_environment'],replay_banks=replay,common_masks=masks,
            source_sha256={p:sha(p) for k,p in models.items() if k.endswith('_initial')},bank_sha256={v['old']:sha(v['old']) for v in replay.values()},
            execution_snapshot_sha256=sha(snapshot),old_functions_ast_unchanged=len(old),
            comparison='Only frozen mean-corpus behavior changes: old9000 vs frozen9200. Same simulation seeds and2400steps; common full-history slot mask; no adaptive refresh during training.',
            learning='4branches x200iterations;128env x24step; original PPO and4aux tasks/weights;384current+384replay; same draws and minibatch schedule within each pair; independent restored bothAdam',
            validation='8initial157101/157102 mean/sample32env x1000step holdouts frozen before all4updates;16final own-loop tapes cross-scored by all3models; intermediate nodes fixed-input scores',
            dynamics='nominalCOM; retain noise,mass/inertia/friction/motor randomization,commands,goals,pushes; original per-axis +/-60N command/external course',
            limitations=['Two related pretrained sources, not independent from-scratch replications','New/old bank actions and states diverge, so not identical physical trajectories','Old/new training-bank scores are in-sample diagnostics, never held-out evidence','Common old/new complete-history mask may differ from8.85; both paired branches retrained','Same initialization and sample index order, not same on-policy trajectories after model divergence'])
        write(root/'plan.json',plan)
    plan=read(root/'plan.json');assert sha(root/'execution_snapshot.py')==plan['execution_snapshot_sha256']
    env=os.environ.copy();env.update(plan['launch_environment'])
    bootstrap="import os; a=os.sched_getaffinity(0); os.sched_setaffinity(0,{min(a)}); from isaacgym import gymapi; import torch; os.sched_setaffinity(0,a); import runpy,sys; sys.argv=["+repr(str(root/'execution_snapshot.py'))+"]+sys.argv[1:]; runpy.run_path("+repr(str(root/'execution_snapshot.py'))+",run_name='__main__')"
    for i,j in enumerate(plan['bank_jobs']):
        folder=root/j['name']
        if not folder.exists():
            with (root/(j['name']+'.log')).open('x') as log:
                child=subprocess.Popen([plan['gym_python'],'-c',bootstrap,'--gym_replay_refresh_collect','--probe_output',str(root),'--coverage_job',j['name']],env=env,stdout=log,stderr=subprocess.STDOUT)
                write(root/'status.json',dict(state='running',phase='bank_collection',current=j['name'],pid=child.pid,completed=i,total_jobs=30,formal_training_resumed=False))
                code=child.wait()
            assert code==0,(j['name'],code)
        assert read(folder/'result.json')['all_passed'];seed=str(j['training_seed'])
        old_bank=torch.load(plan['replay_banks'][seed]['old'],map_location='cpu',weights_only=False)
        fresh=torch.load(folder/'data.pt',map_location='cpu',weights_only=False)
        common=old_bank['full_history']&fresh['full_history'];assert int(common.sum())>0 and common.shape==(292,128)
        mask_path=Path(plan['common_masks'][seed])
        if mask_path.exists():assert torch.equal(torch.load(mask_path,weights_only=False),common)
        else:torch.save(common,mask_path)
        old_init=torch.load(Path(plan['replay_banks'][seed]['old']).parent/'initial_state.pt',map_location='cpu',weights_only=False)
        new_init=torch.load(folder/'initial_state.pt',map_location='cpu',weights_only=False)
        for key in ('masses','coms','inertias','materials','motor_strength','rng'):assert torch.equal(old_init[key],new_init[key]),key
        assert read(folder/'result.json')['source_sha256']==plan['source_sha256'][plan['models'][j['model_seed']]]
        plan['bank_sha256'][str(folder/'data.pt')]=sha(folder/'data.pt')
        plan.setdefault('bank_samples',{})[seed]=int(common.sum())
        write(root/'plan.json',plan);print('REFRESH_BANK_READY',j['name'],int(common.sum()),flush=True)
        del old_bank,fresh,old_init,new_init
    bank_hashes={p:sha(p) for v in plan['replay_banks'].values() for p in v.values()}
    bank_hashes.update({p:sha(p) for p in plan['common_masks'].values()})
    if (root/'frozen_bank_sha256.json').exists():assert bank_hashes==read(root/'frozen_bank_sha256.json')
    else:write(root/'frozen_bank_sha256.json',bank_hashes)
    edits=[('gym_joint_coverage_20261025_v1','gym_replay_refresh_20261026_v1',1),
           ('--gym_joint_coverage_train','--gym_replay_refresh_train',1)]
    gym_replay_control_function(run_gym_joint_coverage,edits,'<refresh_paired_queue>')(args)


def summarize_gym_replay_refresh(args):
    """Independent scorer plus matched bank and update-budget verification."""
    import ast
    import hashlib
    import inspect
    import textwrap
    import torch
    root=args.probe_output.resolve();read=lambda p:json.loads(Path(p).read_text())
    load=lambda p:torch.load(p,map_location='cpu',weights_only=False)
    sha=lambda p:hashlib.sha256(Path(p).read_bytes()).hexdigest()
    plan=read(root/'plan.json')
    source=textwrap.dedent(inspect.getsource(summarize_gym_coverage_closed_loop)).split("    text='''",1)[0]
    edits=[("plan=read(root/'plan.json')","plan=read(root/'analysis_plan.json')",1),
      ("policies=('initial','sample_only','mixed')","policies=('initial','replay_old','replay_fresh')",1),
      ('149101','157101',2),('149102','157102',2),
      ("    for seed in (140001,140002):\n        for behavior in ('mean','steer'):","    old_physical=load_physical_reference()\n    for seed in (140001,140002):\n        for behavior in ('mean','steer'):",1),
      ("d['prediction']['9000']","old_physical[f'{seed}/{behavior}'][j['branch']]['replay_mean']",1)]
    for before,after,count in edits:
        assert source.count(before)==count,(before,source.count(before),count)
        source=source.replace(before,after)
    namespace={};scope=dict(globals());scope['load_physical_reference']=lambda:load(OUT/'gym_joint_replay_control_20261025_v1/paired_force_predictions.pt')
    source=source.replace("constant_zero_rmse_per_axis_n=float(np.sqrt(np.mean(t*t))),",
        "force_rmse_xyz_n=np.sqrt(np.mean((f-t)**2,axis=0)).tolist(),zero_mean_vector_n=f[zero].mean(0).tolist() if zero.any() else None,constant_zero_rmse_per_axis_n=float(np.sqrt(np.mean(t*t))),",1)
    exec(compile(source,'<refresh_independent_scorer>','exec'),scope,namespace);namespace['summarize_gym_coverage_closed_loop'](args)
    from legged_gym.b2_gym_learn.ppo_cse_pf.actor_critic import ActorCritic
    import contextlib
    import io
    bank_scores={};bank_predictions={}
    for seed in (140001,140002):
        bank_scores[str(seed)]={};bank_predictions[str(seed)]={}
        for kind in ('old','fresh'):
            d=load(plan['replay_banks'][str(seed)][kind]);mask=load(plan['common_masks'][str(seed)]);x=d['obs'][mask];y=d['target'][mask];zero=d['sustained_zero'][mask]
            bank_scores[str(seed)][kind]={};bank_predictions[str(seed)][kind]={'target':y,'sustained_zero':zero,'predictions':{}}
            for policy in ('initial','replay_old','replay_fresh'):
                with contextlib.redirect_stdout(io.StringIO()):m=ActorCritic(1856,294,12,58,14,actor_hidden_dims=[512,256,128],critic_hidden_dims=[512,256,128])
                m.load_state_dict(load(plan['models'][f'{seed}_{policy}'])['model_state_dict']);m.eval();m.requires_grad_(False)
                with torch.inference_mode():p=torch.cat([m.get_student_latent(v) for v in x.split(512)])
                row=auxiliary_metrics(p,y);row.update(sustained_zero_norm_n=float((p[zero,6:9]*100).norm(dim=-1).mean()),samples=len(y),in_training_corpus=True)
                bank_scores[str(seed)][kind][policy]=row;bank_predictions[str(seed)][kind]['predictions'][policy]=p
    torch.save(bank_predictions,root/'bank_predictions.pt')
    (root/'bank_scores.json').write_text(json.dumps(bank_scores,indent=2,allow_nan=False)+'\n')
    checks={};pair_checks={}
    for job in plan['training_jobs']:
        folder=root/job['name'];seed=job['model_seed'];initial=load(plan['models'][f'{seed}_initial']);r=read(folder/'result.json')
        assert r['all_passed'] and r['ppo_updates']==4000 and r['auxiliary_updates']==4000 and r['bank_auxiliary_calls']==4000
        assert all(v['independent_tensors'] for v in r['restoration'].values())
        assert r['checks']['labels']==4800 and r['checks']['history']==4800 and r['checks']['timeouts']==4800
        order=load(folder/'sample_order.pt');expected=torch.stack([torch.randperm(3072,generator=torch.Generator().manual_seed(job['seed']+220000+200+i)) for i in range(200)])
        assert torch.equal(order['minibatch_permutations'],expected)
        g=torch.Generator().manual_seed(job['seed']+210000);count=plan['bank_samples'][str(seed)]
        for _ in range(4000):torch.randint(count,(384,),generator=g)
        expected=torch.stack([torch.randint(count,(384,),generator=g) for _ in range(4000)])
        assert torch.equal(order['bank_indices'],expected)
        for node in (50,100,200):
            ck=load(folder/f'joint_iter_{node:04d}.pt');assert ck['iterations']==9200+node and ck['global_policy_steps']==220800+24*node
            for k in ('optimizer_state_dict','adaptation_optimizer_state_dict'):
                assert ck[k]['state'].keys()==initial[k]['state'].keys()
                for pid,st in ck[k]['state'].items():
                    assert float(st['step'])==float(initial[k]['state'][pid]['step'])+node*20
                    assert all(torch.isfinite(t).all() for t in st.values() if isinstance(t,torch.Tensor))
            assert ck['adaptation_optimizer_state_dict']['param_groups']==initial['adaptation_optimizer_state_dict']['param_groups']
            assert all(torch.isfinite(t).all() for t in ck['model_state_dict'].values())
        assert torch.equal(ck['replay_generator_state'],g.get_state())
        checks[job['name']]=dict(ppo_updates=4000,auxiliary_updates=4000,verified_permutations=200,verified_draws=4000,restoration=r['restoration'],bank_samples=count,checks=r['checks'])
    for seed in (140001,140002):
        a=root/f'train_{seed}_replay_old';b=root/f'train_{seed}_replay_fresh'
        def same(x,y):
            if torch.is_tensor(x):return torch.equal(x,y)
            if isinstance(x,dict):return x.keys()==y.keys() and all(same(v,y[k]) for k,v in x.items())
            return x==y
        assert same(load(a/'initial_state.pt'),load(b/'initial_state.pt'))
        assert same(load(a/'first_rollout.pt'),load(b/'first_rollout.pt'))
        assert same(load(a/'first_ppo_model.pt'),load(b/'first_ppo_model.pt'))
        assert same(load(a/'sample_order.pt'),load(b/'sample_order.pt'))
        pair_checks[str(seed)]=dict(same_initial_properties_observations_rng=True,same_first_rollout=True,same_first_ppo=True,same_minibatch_order=True,same_bank_draws=True)
    for name in ('protected_sha256.json','frozen_holdout_sha256.json','frozen_bank_sha256.json'):
        for p,h in read(root/name).items():assert sha(p)==h,p
    definitions=lambda p:{n.name:ast.dump(n,include_attributes=False) for n in ast.parse(Path(p).read_text()).body if isinstance(n,(ast.FunctionDef,ast.ClassDef))}
    old=definitions(root/'audit_before.py');new=definitions(__file__);assert all(new[k]==v for k,v in old.items())
    result=dict(all_passed=True,training=checks,pairs=pair_checks,old_functions_unchanged=len(old),evaluation_optimizer_steps=0,total_new_ppo_updates=16000,total_new_auxiliary_updates=16000,formal_training_resumed=False)
    (root/'completion_verification.json').write_text(json.dumps(result,indent=2)+'\n')
    (root/'status.json').write_text(json.dumps(dict(state='complete',formal_training_resumed=False,iterations_added_per_branch=200,diagnostic_iteration=9400),indent=2)+'\n')
    print('REPLAY_REFRESH_COMPLETE',root,flush=True)


def analyze_gym_replay_retention(args):
    """Summarize checked metrics and verify saved predictions independently."""
    import hashlib
    import numpy as np
    import torch
    root=args.probe_output.resolve();read=lambda p:json.loads(Path(p).read_text())
    load=lambda p:torch.load(p,map_location='cpu',weights_only=False)
    results=read(root/'results.json');coverage=read(root/'coverage_scores.json')
    assert read(root/'completion_verification.json')['all_passed']
    policies=('initial','replay_old','replay_fresh','replay_retained');seeds=('140001','140002')
    def average(rows):
        return {k:float(np.mean([r[k] for r in rows])) for k,v in rows[0].items() if isinstance(v,(int,float)) and all(r[k] is not None for r in rows)}
    summary=dict(averaging='First merge the two simulation seeds within each model, then arithmetic mean across two related pretrained models; no independent-window confidence intervals',fixed={},closed={},old_holdout={},banks={},physical={},controls={})
    for behavior in ('mean','sample'):
        summary['fixed'][behavior]={p:average([results['merged'][s][behavior]['initial']['cross'][p] for s in seeds]) for p in policies}
        summary['closed'][behavior]={p:average([results['merged'][s][behavior][p]['force'] for s in seeds]) for p in policies}
        summary['old_holdout'][behavior]={p:average([coverage[s]['old_holdout_'+behavior][p] for s in seeds]) for p in policies}
        summary['controls'][behavior]={p:average([results['merged'][s][behavior][p]['controls']['all_steps'] for s in seeds]) for p in policies}
    for kind in ('old','fresh'):
        summary['banks'][kind]={p:average([coverage[s]['training_bank_'+kind][p] for s in seeds]) for p in policies}
    for behavior in ('mean','steer'):
        summary['physical'][behavior]={}
        for p in policies:
            rows=[results['physical_response'][s+'/'+behavior][p] for s in seeds]
            summary['physical'][behavior][p]=dict(mean_direction_gain=float(np.mean([r['mean_direction_gain'] for r in rows])),delta_force_rmse_per_axis_n=float(np.mean([r['delta_force_rmse_per_axis_n'] for r in rows])),plateau_rmse_per_axis_n=float(np.mean([r['plateau']['force_rmse_per_axis_n'] for r in rows])))
    checks=0
    def verify(p,y,z,row):
        nonlocal checks
        f=p.numpy().astype(np.float64)[:,6:9]*100;t=y.numpy().astype(np.float64)[:,6:9]*100
        a=np.linalg.norm(t,axis=1)>1;zero=np.linalg.norm(t,axis=1)<.05
        values=dict(force_rmse_per_axis_n=np.sqrt(np.mean((f-t)**2)),constant_zero_rmse_per_axis_n=np.sqrt(np.mean(t*t)),active_vector_error_n=np.linalg.norm((f-t)[a],axis=1).mean(),zero_estimate_norm_n=np.linalg.norm(f[zero],axis=1).mean(),sustained_zero_norm_n=np.linalg.norm(f[z.numpy()],axis=1).mean())
        for k,v in values.items():assert np.isclose(v,row[k],rtol=1e-9,atol=1e-9),(k,v,row[k]);checks+=1
        np.testing.assert_allclose(np.sqrt(np.mean((f-t)**2,axis=0)),row['force_rmse_xyz_n'],rtol=1e-9,atol=1e-9);checks+=1
        np.testing.assert_allclose(f[zero].mean(0),row['zero_mean_vector_n'],rtol=1e-9,atol=1e-9);checks+=1
    tapes=load(root/'cross_predictions.pt')
    for name,d in tapes.items():
        for p,pred in d['predictions'].items():verify(pred,d['target'],d['sustained_zero'],results['per_replay'][name]['cross'][p])
    for s,datasets in load(root/'coverage_predictions.pt').items():
        for name,d in datasets.items():
            for p,pred in d['predictions'].items():verify(pred,d['target'],d['sustained_zero'],coverage[s][name][p])
    (root/'summary.json').write_text(json.dumps(summary,indent=2,allow_nan=False)+'\n')
    (root/'metric_recalculation.json').write_text(json.dumps(dict(all_passed=True,numpy_float64_checks=checks,closed_loop_tapes=len(tapes),coverage_domains_per_model=4,evaluation_optimizer_steps=0,formal_training_resumed=False),indent=2)+'\n')
    import matplotlib
    matplotlib.use('Agg')
    import matplotlib.pyplot as plt
    labels=['9200 start','9400 old','9400 fresh','9400 retained'];colors=['#7b8794','#ca6157','#5089be','#299b79']
    fig,axes=plt.subplots(2,3,figsize=(15,8))
    panels=[('fixed','mean','force_rmse_per_axis_n','New fixed mean histories / RMSE (N/axis)'),('closed','mean','force_rmse_per_axis_n','Own mean closed loop / RMSE (N/axis)'),('closed','mean','sustained_zero_norm_n','Own mean sustained-zero norm (N)'),('old_holdout','mean','force_rmse_per_axis_n','Old independent mean histories / RMSE'),('closed','sample','force_rmse_per_axis_n','Own sampled closed loop / RMSE'),('physical','mean','mean_direction_gain','Old same-action force gain / ideal 1')]
    for ax,(section,behavior,key,title) in zip(axes.flat,panels):
        values=[summary[section][behavior][p][key] for p in policies];ax.bar(range(4),values,color=colors);ax.set_xticks(range(4),labels,rotation=18,ha='right');ax.set_title(title,fontsize=10);ax.grid(axis='y',alpha=.2);ax.set_axisbelow(True)
        for i,v in enumerate(values):ax.text(i,v,f'{v:.3f}',ha='center',va='bottom',fontsize=9)
        if key=='mean_direction_gain':ax.axhline(1,color='gray',ls='--');ax.set_ylim(0,1.08)
    fig.suptitle('UniFP Ranger / retained old + fresh replay / two related model sources',fontsize=13);fig.tight_layout();fig.savefig(root/'retention_comparison.png',dpi=160);plt.close(fig)
    print('RETENTION_ANALYSIS_COMPLETE',checks,json.dumps(summary['closed']['mean'],ensure_ascii=False),flush=True)


def gym_replay_retention_train(args):
    """Retain both frozen behaviors at the already audited replay budget."""
    edits=[
      ("job['policy'] in ('replay_old','replay_fresh')", "job['policy'] in ('replay_old','replay_fresh','replay_retained')", 1),
      ("    gym_replay_control_function(gym_joint_coverage_train,edits,'<refresh_bank_joint_train>')(args)",
       "    edits.extend([\n"
       "      ('del bank\\n    env=None', \"del bank\\n    fresh_path=Path(plan['replay_banks'][str(seed)]['fresh']);assert sha(fresh_path)==plan['bank_sha256'][str(fresh_path)]\\n    fresh=torch.load(fresh_path,map_location='cpu');assert torch.all(~keep|fresh['full_history'])\\n    fresh_x=fresh['obs'][keep];fresh_y=fresh['target'][keep];del fresh\\n    env=None\", 1),\n"
       "      ('return torch.cat((x[:384],bank_x[idx])),torch.cat((y[:384],bank_y[idx]))', 'return torch.cat((x[:384],bank_x[idx[:192]],fresh_x[idx[192:]])),torch.cat((y[:384],bank_y[idx[:192]],fresh_y[idx[192:]]))', 1),\n"
       "    ])\n"
       "    gym_replay_control_function(gym_joint_coverage_train,edits,'<retained_banks_joint_train>')(args)", 1),
    ]
    gym_replay_control_function(gym_replay_refresh_train,edits,'<retained_banks_extension>')(args)


def run_gym_replay_retention(args):
    """Reuse the holdout barrier and sequential GPU queue unchanged."""
    edits=[('gym_joint_coverage_20261025_v1','gym_replay_retention_20261026_v1',1),
           ('--gym_joint_coverage_train','--gym_replay_retention_train',1)]
    gym_replay_control_function(run_gym_joint_coverage,edits,'<retention_queue>')(args)


def summarize_gym_replay_retention(args):
    """Cross-score four candidates, old holdouts, and physical force records."""
    import ast
    import contextlib
    import hashlib
    import inspect
    import io
    import textwrap
    import torch
    root=args.probe_output.resolve();read=lambda p:json.loads(Path(p).read_text())
    load=lambda p:torch.load(p,map_location='cpu',weights_only=False)
    sha=lambda p:hashlib.sha256(Path(p).read_bytes()).hexdigest()
    plan=read(root/'analysis_plan.json');policies=('initial','replay_old','replay_fresh','replay_retained')
    source=textwrap.dedent(inspect.getsource(summarize_gym_coverage_closed_loop)).split("    text='''",1)[0]
    edits=[("plan=read(root/'plan.json')","plan=read(root/'analysis_plan.json')",1),
      ("policies=('initial','sample_only','mixed')","policies=('initial','replay_old','replay_fresh','replay_retained')",1),
      ('149101','159101',2),('149102','159102',2),
      ("    for seed in (140001,140002):\n        for behavior in ('mean','steer'):","    old_physical=load_physical_reference()\n    for seed in (140001,140002):\n        for behavior in ('mean','steer'):",1),
      ("d['prediction']['9000']","old_physical[f'{seed}/{behavior}'][j['branch']]['replay_mean']",1),
      ("preds[j['branch']]={p:predict(models[f'{seed}_{p}'],x.flatten(0,1)).reshape(512,32,12) for p in policies}",
       "preds[j['branch']]={p:(retention_physical[f'{seed}/{behavior}'][j['branch']][p] if p!='replay_retained' else predict(models[f'{seed}_{p}'],x.flatten(0,1)).reshape(512,32,12)) for p in policies}",1)]
    for before,after,count in edits:
        assert source.count(before)==count,(before,source.count(before),count)
        source=source.replace(before,after)
    source=source.replace('constant_zero_rmse_per_axis_n=float(np.sqrt(np.mean(t*t))),',
        'force_rmse_xyz_n=np.sqrt(np.mean((f-t)**2,axis=0)).tolist(),zero_mean_vector_n=f[zero].mean(0).tolist() if zero.any() else None,constant_zero_rmse_per_axis_n=float(np.sqrt(np.mean(t*t))),',1)
    namespace={};scope=dict(globals());scope['load_physical_reference']=lambda:load(OUT/'gym_joint_replay_control_20261025_v1/paired_force_predictions.pt')
    scope['retention_physical']=load(OUT/'gym_replay_refresh_20261026_v1/paired_force_predictions.pt')
    exec(compile(source,'<retention_independent_scorer>','exec'),scope,namespace);namespace['summarize_gym_coverage_closed_loop'](args)
    from legged_gym.b2_gym_learn.ppo_cse_pf.actor_critic import ActorCritic
    def score(pred,y,z):
        p=pred.double();y=y.double();f=p[:,6:9]*100;t=y[:,6:9]*100;active=t.norm(dim=-1)>1;zero=t.norm(dim=-1)<.05
        return dict(samples=len(y),force_rmse_per_axis_n=float((f-t).square().mean().sqrt()),force_rmse_xyz_n=(f-t).square().mean(0).sqrt().tolist(),
            constant_zero_rmse_per_axis_n=float(t.square().mean().sqrt()),active_vector_error_n=float((f[active]-t[active]).norm(dim=-1).mean()),
            zero_estimate_norm_n=float(f[zero].norm(dim=-1).mean()),zero_mean_vector_n=f[zero].mean(0).tolist(),
            sustained_zero_norm_n=float(f[z].norm(dim=-1).mean()),sustained_zero_samples=int(z.sum()))
    scores={};predictions={}
    for seed in (140001,140002):
        datasets={}
        for kind in ('old','fresh'):
            d=load(plan['replay_banks'][str(seed)][kind]);mask=load(plan['common_masks'][str(seed)])
            datasets['training_bank_'+kind]=tuple(d[k][mask] for k in ('obs','target','sustained_zero'))
        old_plan=read(OUT/'gym_joint_replay_control_20261025_v1/plan.json')
        for behavior in ('mean','sample'):
            ds=[load(OUT/'gym_joint_replay_control_20261025_v1'/j['name']/'data.pt') for j in old_plan['jobs'] if j['training_seed']==seed and j['policy']=='initial' and j['behavior']==behavior]
            datasets['old_holdout_'+behavior]=tuple(torch.cat([d[k][d['full_history']] for d in ds]) for k in ('obs','target','sustained_zero'))
        scores[str(seed)]={};predictions[str(seed)]={}
        for policy in policies:
            with contextlib.redirect_stdout(io.StringIO()):m=ActorCritic(1856,294,12,58,14,actor_hidden_dims=[512,256,128],critic_hidden_dims=[512,256,128])
            m.load_state_dict(load(plan['models'][f'{seed}_{policy}'])['model_state_dict']);m.eval();m.requires_grad_(False)
            for name,(x,y,z) in datasets.items():
                with torch.inference_mode():p=torch.cat([m.get_student_latent(v) for v in x.split(512)])
                scores[str(seed)].setdefault(name,{})[policy]=score(p,y,z)
                predictions[str(seed)].setdefault(name,dict(target=y,sustained_zero=z,predictions={}))['predictions'][policy]=p
    (root/'coverage_scores.json').write_text(json.dumps(scores,indent=2,allow_nan=False)+'\n');torch.save(predictions,root/'coverage_predictions.pt')
    training_checks={}
    def same(a,b):
        if torch.is_tensor(a):return torch.equal(a,b)
        if isinstance(a,dict):return a.keys()==b.keys() and all(same(v,b[k]) for k,v in a.items())
        if isinstance(a,(tuple,list)):return len(a)==len(b) and all(same(x,y) for x,y in zip(a,b))
        return a==b
    for job in plan['training_jobs']:
        seed=job['model_seed'];folder=root/job['name'];initial=load(plan['models'][f'{seed}_initial']);r=read(folder/'result.json')
        assert r['all_passed'] and r['ppo_updates']==4000 and r['auxiliary_updates']==4000 and r['bank_auxiliary_calls']==4000
        assert all(v['independent_tensors'] for v in r['restoration'].values())
        assert all(r['checks'][k]==4800 for k in ('labels','history','timeouts'))
        order=load(folder/'sample_order.pt');g=torch.Generator().manual_seed(job['seed']+210000);count=plan['bank_samples'][str(seed)]
        for _ in range(4000):torch.randint(count,(384,),generator=g)
        draws=torch.stack([torch.randint(count,(384,),generator=g) for _ in range(4000)]);assert torch.equal(order['bank_indices'],draws)
        expected=torch.stack([torch.randperm(3072,generator=torch.Generator().manual_seed(job['seed']+220000+200+i)) for i in range(200)])
        assert torch.equal(order['minibatch_permutations'],expected)
        references=[]
        for policy in ('replay_old','replay_fresh'):
            old_folder=Path(plan['models'][f'{seed}_{policy}']).parent
            for name in ('initial_state.pt','first_rollout.pt','first_ppo_model.pt','sample_order.pt'):assert same(load(folder/name),load(old_folder/name)),(seed,policy,name)
            references.append(policy)
        for node in (50,100,200):
            ck=load(folder/f'joint_iter_{node:04d}.pt');assert ck['iterations']==9200+node and ck['global_policy_steps']==220800+24*node
            assert all(torch.isfinite(v).all() for v in ck['model_state_dict'].values())
            for key in ('optimizer_state_dict','adaptation_optimizer_state_dict'):
                assert ck[key]['state'].keys()==initial[key]['state'].keys()
                for pid,st in ck[key]['state'].items():
                    assert float(st['step'])==float(initial[key]['state'][pid]['step'])+node*20
                    assert all(torch.isfinite(v).all() for v in st.values() if torch.is_tensor(v))
            assert ck['adaptation_optimizer_state_dict']['param_groups']==initial['adaptation_optimizer_state_dict']['param_groups']
        assert torch.equal(ck['replay_generator_state'],g.get_state())
        training_checks[str(seed)]=dict(ppo_updates=4000,auxiliary_updates=4000,same_initial_first_rollout_first_ppo_and_orders_as=references,
            batch=dict(current=384,old=192,fresh=192),restoration=r['restoration'],checks=r['checks'],verified_permutations=200,verified_replay_draws=4000)
    for name in ('protected_sha256.json','frozen_holdout_sha256.json','frozen_bank_sha256.json'):
        for p,h in read(root/name).items():assert sha(p)==h,p
    definitions=lambda p:{n.name:ast.dump(n,include_attributes=False) for n in ast.parse(Path(p).read_text()).body if isinstance(n,(ast.FunctionDef,ast.ClassDef))}
    old=definitions(root/'audit_before.py');new=definitions(__file__);assert all(new[k]==v for k,v in old.items())
    result=dict(all_passed=True,training=training_checks,old_functions_unchanged=len(old),evaluation_optimizer_steps=0,total_new_ppo_updates=8000,total_new_auxiliary_updates=8000,formal_training_resumed=False)
    (root/'completion_verification.json').write_text(json.dumps(result,indent=2)+'\n')
    (root/'status.json').write_text(json.dumps(dict(state='complete',formal_training_resumed=False,iterations_added_per_branch=200,diagnostic_iteration=9400),indent=2)+'\n')
    print('REPLAY_RETENTION_COMPLETE',root,flush=True)


def summarize_gym_current_force(args):
    """Separate no-force baseline and physical force increments, without fitting."""
    import ast
    import contextlib
    import hashlib
    import io
    import shutil
    import numpy as np
    import torch
    from legged_gym.b2_gym_learn.ppo_cse_pf.actor_critic import ActorCritic
    torch.set_num_threads(2)
    root=args.probe_output.resolve();assert root==(OUT/'gym_current_force_20261026_v1').resolve()
    read=lambda p:json.loads(Path(p).read_text())
    load=lambda p:torch.load(p,map_location='cpu',weights_only=False)
    def write(p,v):Path(p).write_text(json.dumps(v,indent=2,allow_nan=False)+'\n')
    def sha(p):
        h=hashlib.sha256()
        with Path(p).open('rb') as f:
            for b in iter(lambda:f.read(8388608),b''):h.update(b)
        return h.hexdigest()
    plan=read(root/'plan.json');assert read(root/'status.json')['state']=='experiments_complete'
    assert not (root/'results.json').exists()
    policies=plan['protocol']['scoring_policies'];models={};checks=0;metric_checks=0;forward=[];groups={}
    for seed,paths in plan['models'].items():
        for policy,path in paths.items():
            assert sha(path)==plan['source_sha256'][path]
            with contextlib.redirect_stdout(io.StringIO()):m=ActorCritic(1856,294,12,58,14,actor_hidden_dims=[512,256,128],critic_hidden_dims=[512,256,128])
            m.load_state_dict(load(path)['model_state_dict']);m.eval().requires_grad_(False);models[seed,policy]=m
    def world(d,v):
        q=d['root_quat'].double().numpy();w,x,y,z=np.moveaxis(q,-1,0)
        yaw=np.arctan2(2*(w*z+x*y),1-2*(y*y+z*z));c=np.cos(yaw);s=np.sin(yaw)
        v=np.asarray(v,dtype=np.float64)
        return np.stack((c*v[...,0]-s*v[...,1],s*v[...,0]+c*v[...,1],v[...,2]),-1)
    def metric(p,y,mask):
        nonlocal metric_checks
        f=np.asarray(p,dtype=np.float64)[mask];t=np.asarray(y,dtype=np.float64)[mask]
        if not len(f):return dict(samples=0)
        norm=np.linalg.norm(t,axis=-1);active=norm>1;zero=norm<.05
        rmse=float(np.sqrt(np.mean((f-t)**2)))
        assert abs(rmse-float((torch.from_numpy(f)-torch.from_numpy(t)).square().mean().sqrt()))<1e-9
        metric_checks+=1
        return dict(samples=len(f),force_rmse_per_axis_n=rmse,force_rmse_xyz_n=np.sqrt(np.mean((f-t)**2,axis=0)).tolist(),
            constant_zero_rmse_per_axis_n=float(np.sqrt(np.mean(t*t))),
            active_vector_error_n=float(np.linalg.norm((f-t)[active],axis=-1).mean()) if active.any() else None,
            active_samples=int(active.sum()),zero_samples=int(zero.sum()),
            zero_estimate_norm_n=float(np.linalg.norm(f[zero],axis=-1).mean()) if zero.any() else None,
            zero_mean_vector_n=f[zero].mean(0).tolist() if zero.any() else None)
    def describe(v,mask):
        a=np.asarray(v,dtype=np.float64)[mask]
        return dict(samples=len(a),mean=float(a.mean()),p50=float(np.median(a)),p90=float(np.quantile(a,.9)),maximum=float(a.max())) if len(a) else dict(samples=0)
    def equal(a,b):
        if torch.is_tensor(a):return torch.equal(a,b)
        if isinstance(a,dict):return a.keys()==b.keys() and all(equal(v,b[k]) for k,v in a.items())
        return a==b
    times=np.arange(512)[:,None]
    phases={k:(times>=v[0])&(times<v[1]) for k,v in plan['protocol']['phases'].items()}
    force_branches=[a+sign for a in 'xyz' for sign in ('+1','-1')]
    for seed in plan['models']:
        for behavior in ('mean','steer'):
            jobs=[j for j in plan['jobs'] if str(j['model_seed'])==seed and j['behavior']==behavior]
            tapes={};source_job=next(j for j in jobs if j['branch']=='source');source_initial=load(root/source_job['name']/'initial_state.pt')
            for j in jobs:
                folder=root/j['name'];r=read(folder/'result.json');assert r['all_passed'] and r['models_frozen'] and r['optimizer_steps']==0
                assert r['tape_sha256']==sha(folder/'tape.pt')
                assert r['source_sha256']=={p:plan['source_sha256'][p] for p in plan['models'][seed].values()}
                assert equal(load(folder/'initial_state.pt'),source_initial);checks+=1
                d=load(folder/'tape.pt');tapes[j['branch']]=d
                assert torch.equal(d['censored'],d['done'].cummax(0).values);checks+=1
                # One recorded frame per real step; no second observe() call.
                frames=torch.cat((d['initial_history'].reshape(32,32,58).transpose(0,1),d['frame']),0)
                rebuilt=torch.stack([frames[int(s)+1:int(s)+33].transpose(0,1).reshape(32,1856) for s in d['sparse_times']])
                assert torch.equal(rebuilt,d['sparse_obs']);checks+=1
                assert torch.equal(d['frame'][:,:,29:43],d['actions'].clamp(-100,100).masked_fill(d['done'][:,:,None],0.));checks+=1
                rotated=world(d,d['target'][:,:,6:9].double().numpy()*100);expected=d['force_world'].double().numpy().copy();expected[d['done'].numpy()]=0
                assert np.abs(rotated-expected).max()<1e-4;checks+=1
                for policy in policies:
                    with torch.inference_mode():p=torch.cat([models[seed,policy].get_student_latent(x) for x in rebuilt.flatten(0,1).split(512)])
                    delta=float((p-d['prediction'][policy][d['sparse_times']].flatten(0,1)).abs().max())*100
                    assert delta<.005,(j['name'],policy,delta)
                    forward.append(dict(job=j['name'],policy=policy,sparse_forward_max_delta_n=delta));checks+=1
            base=tapes['source'];common=~torch.stack([d['censored'] for d in tapes.values()]).any(0).numpy()
            torch.save(dict(common_valid=torch.from_numpy(common),phase_masks={k:torch.from_numpy(common&v) for k,v in phases.items()}),root/f'masks_{seed}_{behavior}.pt')
            for d in tapes.values():
                assert torch.equal(d['actions'],base['actions']) and torch.equal(d['actual_target_q'],base['actual_target_q'])
                assert torch.equal(d['frame'][:,:,43:],base['frame'][:,:,43:]);checks+=2
            # Recreate source actions using the same independent steering stream.
            slots=base['sparse_times'];obs_before=torch.cat((base['initial_history'][None],base['sparse_obs'][:-1]),0)
            action_times=torch.cat((torch.zeros(1,dtype=torch.long),slots[:-1]+1))
            with torch.inference_mode():expected_actions=models[seed,'initial'].act_inference({'obs':obs_before.flatten(0,1)}).reshape(-1,32,14)
            if behavior=='steer':
                gen=torch.Generator().manual_seed(source_job['test_seed']+190000)
                noise=torch.stack([torch.randn((32,14),generator=gen)*models[seed,'initial'].std for _ in range(512)])
                noise[:,:,4:]=0.;expected_actions=expected_actions+noise[action_times]
            action_delta=float((expected_actions-base['actions'][action_times]).abs().max());assert action_delta<.0003;checks+=1
            group=dict(model_seed=int(seed),test_seed=source_job['test_seed'],behavior=behavior,
                common_samples={k:int((common&v).sum()) for k,v in phases.items()},
                censored_environments=int((~common[-1]).sum()),source_action_max_delta=action_delta,cases={},response={},symmetry={},physical={})
            for branch,d in tapes.items():
                group['cases'][branch]={};group['response'][branch]={}
                for phase,interval in phases.items():
                    mask=common&interval;group['cases'][branch][phase]={};group['response'][branch][phase]={}
                    for policy in policies:
                        pred=d['prediction'][policy][:,:,6:9].double().numpy()*100
                        truth=d['target'][:,:,6:9].double().numpy()*100
                        group['cases'][branch][phase][policy]=metric(pred,truth,mask)
                        delta=(world(d,pred)-world(base,base['prediction'][policy][:,:,6:9].double().numpy()*100))[mask]
                        actual=(d['force_world']-base['force_world']).double().numpy()[mask]
                        if not len(delta):group['response'][branch][phase][policy]=dict(samples=0);continue
                        denominator=float(np.sum(actual*actual));gain=float(np.sum(delta*actual)/denominator) if denominator else None
                        dr=float(np.sqrt(np.mean((delta-actual)**2)))
                        np.testing.assert_allclose(dr,float((torch.from_numpy(delta)-torch.from_numpy(actual)).square().mean().sqrt()),rtol=1e-12,atol=1e-12);metric_checks+=1
                        group['response'][branch][phase][policy]=dict(samples=len(delta),force_direction_gain=gain,delta_force_rmse_per_axis_n=dr,
                            delta_vector_error_n=float(np.linalg.norm(delta-actual,axis=-1).mean()),prediction_delta_norm_n=float(np.linalg.norm(delta,axis=-1).mean()),
                            mean_prediction_delta_world_n=delta.mean(0).tolist(),mean_truth_delta_world_n=actual.mean(0).tolist())
                    physical=dict(arm_q_delta_rms_rad=np.sqrt(np.mean((d['q'][:,:,8:].double().numpy()-base['q'][:,:,8:].double().numpy())**2,axis=-1)),
                        arm_dq_delta_rms_rad_s=np.sqrt(np.mean((d['dq'][:,:,8:].double().numpy()-base['dq'][:,:,8:].double().numpy())**2,axis=-1)),
                        ee_delta_m=np.linalg.norm(d['ee_pos'].double().numpy()-base['ee_pos'].double().numpy(),axis=-1),
                        base_delta_m=np.linalg.norm(d['root_pos'].double().numpy()-base['root_pos'].double().numpy(),axis=-1))
                    group['physical'].setdefault(branch,{})[phase]={k:describe(v,mask) for k,v in physical.items()}
                mask=common&(times<160)
                group['physical'][branch]['pre_intervention_max']=dict(root_position_m=float((d['root_pos']-base['root_pos'])[mask].abs().max()),
                    joint_position_rad=float((d['q']-base['q'])[mask].abs().max()))
            mask=common&phases['plateau'];group['aggregate']={}
            for policy in policies:
                p=np.concatenate([tapes[b]['prediction'][policy][:,:,6:9].double().numpy()[mask]*100 for b in force_branches])
                y=np.concatenate([tapes[b]['target'][:,:,6:9].double().numpy()[mask]*100 for b in force_branches])
                plateau=metric(p,y,np.ones(len(p),dtype=bool));responses=[group['response'][b]['plateau'][policy] for b in force_branches]
                group['aggregate'][policy]=dict(plateau=plateau,mean_direction_gain=float(np.mean([v['force_direction_gain'] for v in responses])),
                    delta_force_rmse_per_axis_n=float(np.sqrt(np.mean([v['delta_force_rmse_per_axis_n']**2 for v in responses]))),
                    source_plateau=group['cases']['source']['plateau'][policy],pre_zero=group['cases']['source']['pre_zero'][policy],
                    recovery_zero=group['cases']['source']['recovery_zero'][policy],recovery_before_push=group['cases']['source']['recovery_before_push'][policy],recovery_after_push=group['cases']['source']['recovery_after_push'][policy])
                group['symmetry'][policy]={}
                for axis in 'xyz':
                    plus,minus=tapes[axis+'+1'],tapes[axis+'-1']
                    pw=world(plus,plus['prediction'][policy][:,:,6:9].double().numpy()*100);mw=world(minus,minus['prediction'][policy][:,:,6:9].double().numpy()*100)
                    odd=((pw-mw)/2)[mask];even=((pw+mw)/2-world(base,base['prediction'][policy][:,:,6:9].double().numpy()*100))[mask]
                    truth=((plus['force_world']-minus['force_world']).double().numpy()/2)[mask]
                    group['symmetry'][policy][axis]=dict(gain=float(np.sum(odd*truth)/np.sum(truth*truth)),delta_rmse_per_axis_n=float(np.sqrt(np.mean((odd-truth)**2))),even_delta_norm_n=float(np.linalg.norm(even,axis=-1).mean()))
            groups[f'{seed}/{behavior}']=group
            print('CURRENT_FORCE_ANALYZED',seed,behavior,'plateau_samples',int(mask.sum()),flush=True)
    summary={}
    for behavior in ('mean','steer'):
        summary[behavior]={}
        for policy in policies:
            rows=[g['aggregate'][policy] for g in groups.values() if g['behavior']==behavior]
            row={k:float(np.mean([r[k] for r in rows])) for k in ('mean_direction_gain','delta_force_rmse_per_axis_n')}
            for phase in ('plateau','source_plateau','pre_zero','recovery_zero','recovery_before_push','recovery_after_push'):
                row[phase]={k:float(np.mean([r[phase][k] for r in rows])) for k in ('force_rmse_per_axis_n','constant_zero_rmse_per_axis_n','active_vector_error_n','zero_estimate_norm_n') if all(r[phase][k] is not None for r in rows)}
            row['direction_gain']={b:float(np.mean([g['response'][b]['plateau'][policy]['force_direction_gain'] for g in groups.values() if g['behavior']==behavior])) for b in force_branches}
            summary[behavior][policy]=row
    write(root/'results.json',dict(groups=groups,summary=summary,protocol=plan['protocol'],note='Summary is arithmetic mean of two related model/test pairs; no confidence interval; all force increments in world frame after each own yaw rotation.'))
    write(root/'summary.json',summary)
    for p,h in read(root/'protected_sha256.json').items():assert sha(p)==h,p
    definitions=lambda p:{n.name:ast.dump(n,include_attributes=False) for n in ast.parse(Path(p).read_text()).body if isinstance(n,(ast.FunctionDef,ast.ClassDef))}
    old=definitions(root/'audit_before.py');new=definitions(__file__);assert all(new[k]==v for k,v in old.items())
    write(root/'independent_verification.json',dict(all_passed=True,history_label_action_initial_checks=checks,numpy_torch_metric_checks=metric_checks,sparse_forward_checks=forward,
        old_functions_ast_unchanged=len(old),protected_files=len(read(root/'protected_sha256.json')),optimizer_steps=0,formal_training_resumed=False))
    shutil.copy2(__file__,root/'analysis_snapshot.py')
    import matplotlib
    matplotlib.use('Agg')
    import matplotlib.pyplot as plt
    fig,axes=plt.subplots(2,3,figsize=(15,8));labels=['9200 start','9400 old','9400 fresh','9400 retained'];colors=['#7b8794','#ca6157','#5089be','#299b79']
    for row,behavior in zip(axes,('mean','steer')):
        panels=[([summary[behavior][p]['source_plateau']['zero_estimate_norm_n'] for p in policies],'Zero-force reference / predicted norm (N)'),([summary[behavior][p]['mean_direction_gain'] for p in policies],'Same-action force gain / ideal 1'),([summary[behavior][p]['plateau']['force_rmse_per_axis_n'] for p in policies],'Six-direction plateau RMSE (N/axis)')]
        for ax,(values,title) in zip(row,panels):
            ax.bar(range(4),values,color=colors);ax.set_xticks(range(4),labels,rotation=18,ha='right');ax.set_title(behavior+' / '+title,fontsize=10);ax.grid(axis='y',alpha=.2);ax.set_axisbelow(True)
            for i,v in enumerate(values):ax.text(i,v,f'{v:.3f}',ha='center',va='bottom',fontsize=9)
        row[1].axhline(1,color='gray',ls='--');row[1].set_ylim(0,1.08)
    fig.suptitle('Frozen 9200 behavior / same actions / actual 0 or +/-60N / no updates');fig.tight_layout();fig.savefig(root/'current_force_comparison.png',dpi=160);plt.close(fig)
    write(root/'status.json',dict(state='analysis_complete',completed=len(plan['jobs']),total=len(plan['jobs']),training_started=False,optimizer_steps=0,formal_training_resumed=False))
    print('CURRENT_FORCE_SUMMARY_COMPLETE',json.dumps(summary),flush=True)


