def run_gym_current_force(args):
    """Bounded physical-only queue; never initialize a learner or optimizer."""
    import ast
    import hashlib
    import os
    import subprocess
    import time
    root=args.probe_output.resolve();assert root==(OUT/'gym_current_force_20261026_v1').resolve()
    read=lambda p:json.loads(Path(p).read_text())
    def write(p,v):Path(p).write_text(json.dumps(v,indent=2,allow_nan=False)+'\n')
    def sha(p):
        h=hashlib.sha256()
        with Path(p).open('rb') as f:
            for b in iter(lambda:f.read(8388608),b''):h.update(b)
        return h.hexdigest()
    plan=read(root/'plan.json');assert read(root/'status.json')['state']=='prepared'
    protected=read(root/'protected_sha256.json')
    for p,h in protected.items():assert sha(p)==h,p
    definitions=lambda p:{n.name:ast.dump(n,include_attributes=False) for n in ast.parse(Path(p).read_text()).body if isinstance(n,(ast.FunctionDef,ast.ClassDef))}
    old=definitions(root/'audit_before.py');new=definitions(__file__);assert all(new[k]==v for k,v in old.items())
    snapshot=root/'execution_snapshot.py';assert not snapshot.exists()
    snapshot.write_text('__file__ = '+repr(str(Path(__file__).resolve()))+'\n'+Path(__file__).read_text())
    snapshot_sha=sha(snapshot)
    write(root/'execution_config.json',dict(snapshot_sha256=snapshot_sha,old_functions_ast_unchanged=len(old),optimizer_steps=0))
    # Import-clock workaround only; restore all original CPUs before physics.
    bootstrap="import os,runpy; cpus=os.sched_getaffinity(0); os.sched_setaffinity(0,{min(cpus)}); from isaacgym import gymapi; import torch; os.sched_setaffinity(0,cpus); runpy.run_path("+repr(str(snapshot))+",run_name='__main__')"
    env=os.environ.copy();env.update(plan['launch_environment']);started=time.monotonic()
    def status(state,**kw):write(root/'status.json',dict(state=state,elapsed_s=time.monotonic()-started,total=len(plan['jobs']),training_started=False,optimizer_steps=0,formal_training_resumed=False,**kw))
    try:
        for i,j in enumerate(plan['jobs']):
            assert sha(snapshot)==snapshot_sha
            command=[plan['python'],'-c',bootstrap,'--gym_current_force_worker','--probe_output',str(root),'--paired_force_job',j['name']]
            with (root/(j['name']+'.log')).open('x') as log:
                child=subprocess.Popen(command,env=env,stdout=log,stderr=subprocess.STDOUT)
                status('running',completed=i,current=j['name'],pid=child.pid)
                code=child.wait()
            assert code==0,(j['name'],code)
            r=read(root/j['name']/'result.json');assert r['all_passed'] and r['optimizer_steps']==0 and r['models_frozen']
            assert r['tape_sha256']==sha(root/j['name']/'tape.pt')
            print('CURRENT_FORCE_DONE',i+1,len(plan['jobs']),j['name'],flush=True)
        for p,h in protected.items():assert sha(p)==h,p
        status('experiments_complete',completed=len(plan['jobs']))
    except Exception as exc:
        import traceback
        status('failed',error=str(exc),traceback=traceback.format_exc());raise


def gym_nominal_base_mass_backend(*args, **kwargs):
    """Restore base mass before prepare; retain draws and mass-ratio inertia."""
    edits=[
        ("assert not (init_before_prepare and sim_prepared), 'Rigid properties must be initialized before prepare_sim'",
         "assert init_before_prepare and not sim_prepared\n            values[:,body_names.index('base_link')]=baseline_mass[:,body_names.index('base_link')]",1),
        ("return RangerGym(),ns",
         "env=RangerGym()\n    env.transport['base_mass_intervention']=dict(before_prepare=True,baseline_mass_kg=baseline_mass[:,body_names.index('base_link')].tolist(),baseline_inertia=baseline_inertia[:,body_names.index('base_link')].tolist(),rule='Original random draws retained; base mass restored in-place before existing inertia mass-ratio calculation')\n    return env,ns",1),
    ]
    return gym_replay_control_function(gym_ranger_backend,edits,'<nominal_base_mass_backend>')(*args,**kwargs)


def verify_gym_base_mass_initial(initial, env, root, job, plan):
    """Reject changes outside base mass/inertia and truthful critic mass field."""
    import torch
    original=torch.load(Path(plan['random_root'])/job['source']/'initial_state.pt',map_location='cpu')
    def equal(a,b):
        if isinstance(a,dict):return a.keys()==b.keys() and all(equal(a[k],b[k]) for k in a)
        return torch.equal(a,b)
    transport=env.transport;meta=transport['base_mass_intervention'];base=transport['body_names'].index('base_link')
    keep=[i for i in range(initial['masses'].shape[1]) if i!=base]
    mass=torch.tensor(meta['baseline_mass_kg']);inertia=torch.tensor(meta['baseline_inertia'])
    assert torch.equal(initial['masses'][:,base],mass)
    assert torch.allclose(initial['inertias'][:,base],inertia,rtol=2e-6,atol=1e-6)
    assert torch.equal(initial['masses'][:,keep],original['masses'][:,keep])
    assert torch.equal(initial['inertias'][:,keep],original['inertias'][:,keep])
    ratio=original['masses'][:,base]/mass
    assert torch.allclose(original['inertias'][:,base],inertia*ratio[:,None],rtol=2e-6,atol=1e-6)
    assert bool(((original['masses'][:,base]-mass>=0)&(original['masses'][:,base]-mass<=15)).all())
    assert torch.count_nonzero(env.domain.mass_deltas[:,0])==0
    deviations={}
    def close(a,b,path):
        if isinstance(a,dict):
            assert a.keys()==b.keys()
            for k in a:close(a[k],b[k],path+'/'+k)
        elif a.is_floating_point():
            delta=float((a-b).abs().max());deviations[path]=delta
            assert delta<1e-5,(path,delta)
        else:assert equal(a,b),path
    for key in initial:
        if key not in ('masses','inertias','observations'):close(initial[key],original[key],key)
    for key in ('obs','obs_pred'):close(initial['observations'][key],original['observations'][key],key)
    a=initial['observations']['privileged_obs'].reshape(32,3,98).clone()
    b=original['observations']['privileged_obs'].reshape(32,3,98).clone()
    # Critic frame begins with the 12-dimensional supervision target.
    assert torch.count_nonzero(a[:,:,12])==0
    a[:,:,12]=b[:,:,12];close(a,b,'privileged_obs_except_base_mass')
    assert float((initial['root_position']-original['root_position']).abs().max())<1e-7
    for key in ('coms','materials','motor_strength','rng','root_velocity','all_joint_position','all_joint_velocity'):
        assert equal(initial[key],original[key]),key
    result=dict(all_passed=True,base_body=base,nominal_base_mass_kg=mass.tolist(),
        random_base_added_mass_kg=(original['masses'][:,base]-mass).tolist(),before_prepare=meta['before_prepare'],
        other_properties_joint_state_root_velocity_rng_exact=True,root_position_tolerance_m=1e-7,initial_float_max_differences=deviations,original_inertia_ratio_verified=True,
        truthful_critic_mass_field_only=True,source_actions=str(Path(plan['random_root'])/job['source']/'tape.pt'))
    (root/job['name']/'mass_initial_verification.json').write_text(json.dumps(result,indent=2)+'\n')


