def verify_gym_friction_initial(initial, env, root, job, plan):
    """Verify only shape friction and the truthful critic friction field differ."""
    import torch
    original=torch.load(Path(plan['random_root'])/job['source']/'initial_state.pt',map_location='cpu')
    def equal(a,b):
        if isinstance(a,dict):return a.keys()==b.keys() and all(equal(a[k],b[k]) for k in a)
        return torch.equal(a,b)
    assert torch.equal(initial['materials'][:,:,:2],torch.ones_like(initial['materials'][:,:,:2]))
    assert torch.equal(initial['materials'][:,:,2:],original['materials'][:,:,2:])
    for key in ('masses','inertias','coms','motor_strength','rng','root_velocity','all_joint_position','all_joint_velocity'):
        assert equal(initial[key],original[key]),key
    assert torch.equal(env.domain.friction,torch.ones_like(env.domain.friction))
    deviations={}
    def close(a,b,path):
        if isinstance(a,dict):
            assert a.keys()==b.keys()
            for k in a:close(a[k],b[k],path+'/'+k)
        elif a.is_floating_point():
            delta=float((a-b).abs().max());deviations[path]=delta
            assert delta<1e-5,(path,delta)
        else:assert equal(a,b),path
    for key in initial:
        if key not in ('materials','observations'):close(initial[key],original[key],key)
    assert float((initial['root_position']-original['root_position']).abs().max())<1e-7
    for key in ('obs','obs_pred'):close(initial['observations'][key],original['observations'][key],key)
    a=initial['observations']['privileged_obs'].reshape(32,3,98).clone()
    b=original['observations']['privileged_obs'].reshape(32,3,98).clone()
    assert torch.equal(a[:,-1,17],torch.ones(32)) and torch.count_nonzero(a[:,:-1,17])==0
    a[:,:,17]=b[:,:,17];close(a,b,'privileged_obs_except_friction')
    metadata=env.transport['friction_intervention'];assert metadata['before_prepare']
    result=dict(all_passed=True,fixed_robot_shape_friction=1.,ground_friction=1.,
        random_robot_friction=original['materials'][:,0,0].tolist(),before_prepare=True,
        other_mass_inertia_com_motor_joints_root_velocity_rng_exact=True,truthful_critic_friction_field_only=True,
        initial_float_max_differences=deviations,root_position_tolerance_m=1e-7,
        source_actions=str(Path(plan['random_root'])/job['source']/'tape.pt'),intervention=metadata)
    (root/job['name']/'friction_initial_verification.json').write_text(json.dumps(result,indent=2)+'\n')


