def summarize_gym_friction_strata(root):
    """Pair below/above the fixed coefficient to expose possible cancellation."""
    import torch
    torch.set_num_threads(2)
    read=lambda p:json.loads(Path(p).read_text())
    load=lambda p:torch.load(p,map_location='cpu',weights_only=False)
    plan=read(root/'plan.json');groups={};reconstruction_checks=0
    def world(d,p):
        w,x,y,z=d['root_quat'].double().unbind(-1)
        yaw=torch.atan2(2*(w*z+x*y),1-2*(y*y+z*z));c,s=yaw.cos(),yaw.sin()
        return torch.stack((c*p[...,0]-s*p[...,1],s*p[...,0]+c*p[...,1],p[...,2]),-1)
    for seed in plan['models']:
        for behavior in ('mean','steer'):
            jobs=[j for j in plan['jobs'] if str(j['model_seed'])==seed and j['behavior']==behavior]
            source=next(j for j in jobs if j['branch']=='source')
            mu=load(Path(plan['random_root'])/source['name']/'initial_state.pt')['materials'][:,0,0]
            valid=load(root/'analysis_nominal'/f'masks_{seed}_{behavior}.pt')['common_valid']
            data={c:{j['branch']:load(Path(plan[c+'_root'])/j['name']/'tape.pt') for j in jobs} for c in ('random','nominal')}
            group={}
            for stratum,selection in (('below1',mu<1.),('at_or_above1',mu>=1.)):
                mask=valid&selection[None];plateau=mask.clone();plateau[:224]=False;plateau[288:]=False
                pre=mask.clone();pre[:96]=False;pre[160:]=False
                row=dict(environments=int(selection.sum()),original_friction=mu[selection].tolist(),samples=int(plateau.sum()),pre_samples=int(pre.sum()),conditions={})
                if not plateau.any():group[stratum]=row;continue
                for condition,tapes in data.items():
                    base=tapes['source'];forces=[tapes[a+s] for a in 'xyz' for s in ('+1','-1')];scores={}
                    for policy in plan['protocol']['scoring_policies']:
                        p0=base['prediction'][policy][:,:,6:9].double()*100
                        prediction=torch.cat([d['prediction'][policy][:,:,6:9].double()[plateau]*100 for d in forces])
                        truth=torch.cat([d['target'][:,:,6:9].double()[plateau]*100 for d in forces])
                        delta=torch.cat([(world(d,d['prediction'][policy][:,:,6:9].double()*100)-world(base,p0))[plateau] for d in forces])
                        actual=torch.cat([(d['force_world']-base['force_world']).double()[plateau] for d in forces])
                        scores[policy]=dict(force_rmse_per_axis_n=float((prediction-truth).square().mean().sqrt()),
                            active_vector_error_n=float((prediction-truth).norm(dim=-1).mean()),
                            source_plateau_zero_norm_n=float(p0[plateau].norm(dim=-1).mean()),source_pre_zero_norm_n=float(p0[pre].norm(dim=-1).mean()),
                            force_direction_gain=float((delta*actual).sum()/actual.square().sum()),delta_rmse_per_axis_n=float((delta-actual).square().mean().sqrt()))
                    row['conditions'][condition]=scores
                group[stratum]=row
            groups[seed+'/'+behavior]=group
    for condition in ('random','nominal'):
        scored=read(root/('analysis_'+condition)/'results.json')['groups']
        for key,strata in groups.items():
            rows=[r for r in strata.values() if r['samples']];total=sum(r['samples'] for r in rows)
            assert total==scored[key]['common_samples']['plateau']
            for policy in plan['protocol']['scoring_policies']:
                aggregate=scored[key]['aggregate'][policy]
                for field,expected,squared in (
                    ('force_rmse_per_axis_n',aggregate['plateau']['force_rmse_per_axis_n'],True),
                    ('active_vector_error_n',aggregate['plateau']['active_vector_error_n'],False),
                    ('source_plateau_zero_norm_n',aggregate['source_plateau']['zero_estimate_norm_n'],False),
                    ('source_pre_zero_norm_n',aggregate['pre_zero']['zero_estimate_norm_n'],False),
                    ('force_direction_gain',aggregate['mean_direction_gain'],False),
                    ('delta_rmse_per_axis_n',aggregate['delta_force_rmse_per_axis_n'],True)):
                    weight='pre_samples' if field=='source_pre_zero_norm_n' else 'samples'
                    value=sum(r[weight]*r['conditions'][condition][policy][field]**(2 if squared else 1) for r in rows)/sum(r[weight] for r in rows)
                    if squared:value=value**.5
                    assert abs(value-expected)<2e-6,(condition,key,policy,field,value,expected)
                    reconstruction_checks+=1
    (root/'friction_strata.json').write_text(json.dumps(dict(groups=groups,weighted_reconstruction_checks=reconstruction_checks,all_reconstruction_checks_passed=True,split='Original robot friction <1 versus >=1; specified before final scoring; same environments and16-branch mask within each pair. Descriptive, no significance claim.'),indent=2,allow_nan=False)+'\n')


