def verify_gym_motor_initial(initial, env, root, job, plan):
    """Verify that only action scales and their truthful critic fields differ."""
    import torch
    original=torch.load(Path(plan['random_root'])/job['source']/'initial_state.pt',map_location='cpu')
    assert torch.equal(env.diagnostic_original_motor,original['motor_strength'])
    assert torch.equal(initial['motor_strength'],torch.ones_like(original['motor_strength']))
    assert torch.equal(env.shared_state.motor_initial,initial['motor_strength'])
    deviations={}
    def close(a,b,path):
        if isinstance(a,dict):
            assert a.keys()==b.keys()
            for k in a:close(a[k],b[k],path+'/'+k)
        elif a.is_floating_point():
            delta=float((a-b).abs().max());deviations[path]=delta
            assert delta<1e-5,(path,delta)
        else:assert torch.equal(a,b),path
    for key in initial:
        if key not in ('motor_strength','observations'):close(initial[key],original[key],key)
    for key in ('masses','inertias','coms','materials','rng','root_velocity','all_joint_position','all_joint_velocity'):
        assert torch.equal(initial[key],original[key]),key
    assert float((initial['root_position']-original['root_position']).abs().max())<1e-7
    for key in ('obs','obs_pred'):close(initial['observations'][key],original['observations'][key],key)
    a=initial['observations']['privileged_obs'].reshape(32,3,98).clone()
    b=original['observations']['privileged_obs'].reshape(32,3,98).clone()
    assert torch.count_nonzero(a[:,:,18:32])==0
    assert torch.equal(b[:,-1,18:32],original['motor_strength']-1.)
    a[:,:,18:32]=b[:,:,18:32];close(a,b,'privileged_obs_except_motor')
    c=env.controller
    result=dict(all_passed=True,fixed_motor_strength=1.,original_motor_strength=original['motor_strength'].tolist(),
        before_first_reset_and_observation=True,all_random_draws_retained=True,other_physical_properties_and_rng_exact=True,
        truthful_critic_motor_fields_only=True,initial_float_max_differences=deviations,
        default_action_positions=c.default_positions[c.action_indices].tolist(),position_action_indices=c.position_action_indices.tolist(),
        source_actions=str(Path(plan['random_root'])/job['source']/'tape.pt'),intervention=env.transport['motor_intervention'])
    (root/job['name']/'motor_initial_verification.json').write_text(json.dumps(result,indent=2)+'\n')


