def verify_gym_arm_motor_metrics(root):
    """Reuse float64 checks, then verify channel separation against both ends."""
    import torch
    edits=[('0.85-1.15 vs 1.0 / formula-verified target changes',
            'arm6 random vs fixed1 / base8 original random retained',1),
           ('motor_comparison.png','arm_motor_comparison.png',1)]
    gym_replay_control_function(verify_gym_motor_metrics,edits,'<arm_motor_metrics>')(root)
    plan=json.loads((root/'plan.json').read_text());rows=[]
    load=lambda p:torch.load(p,map_location='cpu',weights_only=False)
    for job in plan['jobs']:
        name=job['name'];fixed=load(root/name/'tape.pt')
        original=load(Path(plan['random_root'])/name/'tape.pt')
        all_fixed=load(Path(plan['all_fixed_root'])/name/'tape.pt')
        initial=load(root/name/'initial_state.pt');old=load(Path(plan['random_root'])/name/'initial_state.pt')
        assert torch.equal(initial['motor_strength'][:,8:],torch.ones_like(initial['motor_strength'][:,8:]))
        assert torch.equal(initial['motor_strength'][:,:8],old['motor_strength'][:,:8])
        assert torch.equal(fixed['actual_target_q'][:,:,:8],original['actual_target_q'][:,:,:8])
        assert torch.equal(fixed['actual_target_q'][:,:,8:],all_fixed['actual_target_q'][:,:,8:])
        expected_v=torch.zeros_like(fixed['actual_target_velocity']);expected_v[:,:,4:8]=5.*(original['actions'][:,:,4:8].clamp(-100,100)*old['motor_strength'][None,:,4:8])
        assert torch.equal(fixed['actual_target_velocity'],expected_v)
        assert torch.equal(fixed['actions'],original['actions']) and torch.equal(fixed['actions'],all_fixed['actions'])
        rows.append(dict(job=name,arm_scales_fixed=True,base_scales_original_exact=True,
            base_position_targets_original_exact=True,arm_position_targets_all_fixed_exact=True,base_velocity_targets_original_formula_exact=True))
    (root/'channel_verification.json').write_text(json.dumps(dict(all_passed=True,checks=rows),indent=2)+'\n')

def compare_gym_arm_motor(root):
    """Complete the frozen2x2 design; contrasts are descriptive metric differences."""
    import torch
    import numpy as np
    read=lambda p:json.loads(Path(p).read_text())
    plan=read(root/'plan.json');current=read(root/'results.json')
    old=read(Path(plan['base_fixed_root'])/'three_condition_results.json');checks=[]
    for seed in plan['models']:
        for behavior in ('mean','steer'):
            dirs=[root/'analysis_random',root/'analysis_nominal',Path(plan['base_fixed_root'])/'analysis_nominal',Path(plan['all_fixed_root'])/'analysis_nominal']
            masks=[torch.load(d/f'masks_{seed}_{behavior}.pt',map_location='cpu',weights_only=False)['common_valid'] for d in dirs]
            assert all(torch.equal(masks[0],m) for m in masks[1:]),'Rescore four conditions on common32 branch mask if censoring differs'
            checks.append(dict(source=seed,behavior=behavior,four_masks_exact=True,platform_samples=int(masks[0][224:288].sum())))
    assert current['summary']['random']==old['summary']['random']
    summary=dict(random=old['summary']['random'],base_fixed=old['summary']['base_fixed'],arm_fixed=current['summary']['nominal'],all_fixed=old['summary']['all_fixed'])
    paired={key:{p:dict(random=old['paired_groups'][key][p]['random'],base_fixed=old['paired_groups'][key][p]['base_fixed'],arm_fixed=value[p]['nominal'],all_fixed=old['paired_groups'][key][p]['all_fixed']) for p in plan['protocol']['scoring_policies']} for key,value in current['paired_groups'].items()}
    def metrics(v):
        return dict(zero_norm_n=v['source_plateau']['zero_estimate_norm_n'],gain=v['mean_direction_gain'],rmse_n=v['plateau']['force_rmse_per_axis_n'],delta_rmse_n=v['delta_force_rmse_per_axis_n'],active_vector_error_n=v['plateau']['active_vector_error_n'])
    contrasts={}
    for key,group in paired.items():
        contrasts[key]={}
        for policy,conditions in group.items():
            m={c:metrics(v) for c,v in conditions.items()};r,b,a,f=[m[c] for c in ('random','base_fixed','arm_fixed','all_fixed')]
            contrasts[key][policy]={k:dict(arm_effect_base_random=a[k]-r[k],arm_effect_base_fixed=f[k]-b[k],base_effect_arm_random=b[k]-r[k],base_effect_arm_fixed=f[k]-a[k],interaction=f[k]-b[k]-a[k]+r[k]) for k in r}
    result=dict(summary=summary,paired_groups=paired,mask_checks=checks,descriptive_contrasts=contrasts,optimizer_steps=0,note='Two related sources; frozen test interventions. Metric contrasts, especially nonlinear norms/RMSE, are not additive mechanical causal shares or training benefit.')
    (root/'four_condition_results.json').write_text(json.dumps(result,indent=2,allow_nan=False)+'\n')
    import matplotlib
    matplotlib.use('Agg')
    import matplotlib.pyplot as plt
    fig,axes=plt.subplots(2,3,figsize=(17,8));x=np.arange(4);policies=plan['protocol']['scoring_policies']
    for row,behavior in zip(axes,('mean','steer')):
        for ax,key,title in zip(row,('zero_norm_n','gain','rmse_n'),('Zero-force predicted norm (N)','True force increment gain / ideal1','Force plateau RMSE (N/axis)')):
            for c,offset,color in [('random',-.3,'#6486ab'),('base_fixed',-.1,'#ba8650'),('arm_fixed',.1,'#9875af'),('all_fixed',.3,'#42a182')]:
                ax.bar(x+offset,[metrics(summary[c][behavior][p])[key] for p in policies],width=.19,color=color,label=c)
            ax.set_xticks(x,['9200 start','9400 old','9400 fresh','9400 retained'],rotation=16,ha='right');ax.set_title(behavior+' / '+title,fontsize=10);ax.grid(axis='y',alpha=.2);ax.set_axisbelow(True)
            if key=='gain':ax.axhline(1,color='gray',ls='--');ax.set_ylim(0,1.1)
        row[0].legend(fontsize=8)
    fig.suptitle('Frozen2x2 motor action amplitude intervention / same raw actions / +/-60N')
    fig.tight_layout();fig.savefig(root/'four_condition_comparison.png',dpi=160);plt.close(fig)


