def gym_arm_training_backend(domain, evidence_folder, *args, **kwargs):
    """Original task with arm-only intervention before all resets/observations."""
    import torch
    original=globals().get('_gym_arm_training_original_backend',gym_ranger_backend)
    assert domain in ('random','arm_fixed')
    intervention="self.diagnostic_original_motor=self.domain.motor_strength.clone()\n                "
    if domain=='arm_fixed':intervention+="self.domain.motor_strength[:,8:].fill_(1.)\n                "
    intervention+="install_ranger_official_shared(self,ns,float(params.dt)*4)"
    backend=gym_replay_control_function(original,[('install_ranger_official_shared(self,ns,float(params.dt)*4)',intervention,1)],'<arm_training_backend>')
    env,ns=backend(*args,**kwargs)
    expected=env.diagnostic_original_motor.clone()
    if domain=='arm_fixed':expected[:,8:]=1.
    assert torch.equal(env.domain.motor_strength,expected) and torch.equal(env.shared_state.motor_initial,expected)
    assert torch.equal(expected[:,:8],env.diagnostic_original_motor[:,:8])
    step=env.step;env.diagnostic_motor_checked_steps=0
    def checked_step(*a,**kw):
        assert torch.equal(env.domain.motor_strength,expected)
        value=step(*a,**kw)
        assert torch.equal(env.domain.motor_strength,expected) and torch.equal(env.shared_state.motor_initial,expected)
        env.diagnostic_motor_checked_steps+=1
        return value
    env.step=checked_step
    env.transport['motor_intervention']=dict(domain=domain,before_first_reset_and_observation=True,original_draws_retained=True,arm_channels=list(range(8,14)),base_channels=list(range(8)),reset_reuses_initial_coefficients=True)
    (Path(evidence_folder)/'motor_intervention.json').write_text(json.dumps(dict(all_passed=True,domain=domain,num_envs=env.num_envs,original=env.diagnostic_original_motor.tolist(),actual=expected.tolist(),transport=env.transport['motor_intervention']),indent=2)+'\n')
    return env,ns


def gym_arm_training_train(args):
    """Reuse retained-bank joint learner; change only environment arm amplitudes."""
    helper=gym_replay_control_function
    def customize(original,edits,filename):
        if original is gym_joint_coverage_train:
            edits=list(edits)+[
                ("env,ns=gym_ranger_backend(128,job['seed'],60.,False,True,init_before_prepare=True,official_shared=True)","env,ns=gym_arm_training_backend(job['domain'],output,128,job['seed'],60.,False,True,init_before_prepare=True,official_shared=True)",1),
                ("result=dict(all_passed=True,job=job,restoration=restoration,", "assert env.diagnostic_motor_checked_steps==4800\n        result=dict(all_passed=True,motor_checked_steps=env.diagnostic_motor_checked_steps,job=job,restoration=restoration,",1)]
        return helper(original,edits,filename)
    globals()['gym_replay_control_function']=customize
    try:gym_replay_retention_train(args)
    finally:globals()['gym_replay_control_function']=helper


