def summarize_gym_arm_training(args):
    """Reuse independent full-history and control scorer in both validation domains."""
    import copy
    import inspect
    import shutil
    from types import SimpleNamespace
    root=args.probe_output.resolve();read=lambda p:json.loads(Path(p).read_text())
    plan=read(root/'analysis_plan.json');assert read(root/'status.json')['state']=='ready_for_independent_analysis'
    source=inspect.getsource(summarize_gym_coverage_closed_loop).split('    # Read-only evaluation on the already completed same-action physical',1)[0]
    edits=[("policies=('initial','sample_only','mixed')","policies=('initial','random','arm_fixed')",1),
           ("os.sched_setaffinity(0,{min(os.sched_getaffinity(0))})","affinity=os.sched_getaffinity(0);os.sched_setaffinity(0,{min(affinity)})",1),
           ("torch.set_num_threads(1)","os.sched_setaffinity(0,affinity);torch.set_num_threads(2)",1),
           ("(149101,149102)","(plan['test_seeds'][str(seed)],)",2),
           ("sum(c[k]**2 for c in cs)/2","sum(c[k]**2 for c in cs)/len(cs)",1),
           ("sum(c[k] for c in cs)/2","sum(c[k] for c in cs)/len(cs)",1)]
    for before,after,count in edits:
        assert source.count(before)==count,(before,source.count(before));source=source.replace(before,after)
    source+="    write(root/'results.json',dict(merged=merged,per_replay=cases))\n    write(root/'independent_verification.json',dict(all_passed=True,history_label_action_termination_checks=checks,numpy_metric_evaluations=metric_checks,forward_action_checks=forward,initial_pair_checks=initial_checks,optimizer_steps=0))\n"
    namespace={};exec(compile(source,'<arm_training_closed_loop_scorer>','exec'),globals(),namespace)
    for domain in ('random','arm_fixed'):
        folder=root/('closed_'+domain);folder.mkdir(exist_ok=False)
        config=copy.deepcopy(plan);config['jobs']=[]
        for job in plan['jobs']:
            if job['domain']!=domain:continue
            j=dict(job);j['name']=job['name'][len(domain)+1:];config['jobs'].append(j)
            (folder/j['name']).symlink_to(root/job['name'],target_is_directory=True)
        (folder/'plan.json').write_text(json.dumps(config,indent=2)+'\n');(folder/'status.json').write_text(json.dumps(dict(state='ready_for_independent_analysis'))+'\n')
        namespace['summarize_gym_coverage_closed_loop'](SimpleNamespace(probe_output=folder))
    if all((root/('physical_'+d)/'results.json').exists() for d in ('random','arm_fixed')):
        for domain in ('random','arm_fixed'):assert read(root/('physical_'+domain)/'independent_verification.json')['all_passed']
    else:score_gym_arm_training_physical(args)
    verify_gym_arm_training(args)


def score_gym_arm_training_physical(args):
    """New frozen candidates on existing same-action tapes; never rewrite tapes."""
    import copy
    import inspect
    import shutil
    from types import SimpleNamespace
    root=args.probe_output.resolve();read=lambda p:json.loads(Path(p).read_text());plan=read(root/'analysis_plan.json')
    source=inspect.getsource(summarize_gym_current_force).split('    shutil.copy2(__file__',1)[0]
    edits=[("root=args.probe_output.resolve();assert root==(OUT/'gym_current_force_20261026_v1').resolve()","root=args.probe_output.resolve()",1),
      ("root/source_job['name']/'initial_state.pt'","Path(plan['physical_input_root'])/source_job['name']/'initial_state.pt'",1),
      ("folder=root/j['name'];r=read(folder/'result.json')","folder=Path(plan['physical_input_root'])/j['name'];r=read(folder/'result.json')",1),
      ("assert r['source_sha256']=={p:plan['source_sha256'][p] for p in plan['models'][seed].values()}","assert r['source_sha256']==plan['recorded_source_sha256'][seed]",1),
      ("d=load(folder/'tape.pt');tapes[j['branch']]=d", "d=load(folder/'tape.pt');tapes[j['branch']]=d",1),
      ("                for policy in policies:\n                    with torch.inference_mode():p=", "                history=d['initial_history'].reshape(32,32,58).clone();all_x=[]\n                for step in range(512):\n                    history[d['done'][step]]=0.;history[:,:-1]=history[:,1:].clone();history[:,-1]=d['frame'][step]\n                    all_x.append(history.reshape(32,1856).clamp(-100,100).clone())\n                all_x=torch.stack(all_x);assert torch.equal(all_x[d['sparse_times']],rebuilt)\n                original_initial=d['prediction']['initial'].clone();d['prediction']={}\n                for policy in policies:\n                    with torch.inference_mode():new_p=torch.cat([models[seed,policy].get_student_latent(x) for x in all_x.flatten(0,1).split(512)]).reshape(512,32,12)\n                    if policy=='initial':assert (new_p-original_initial).abs().max()*100<.005\n                    d['prediction'][policy]=new_p\n                    with torch.inference_mode():p=",1),
      ("            torch.save(dict(common_valid=", "            other=Path(plan['paired_root'])\n            common=common&~torch.stack([load(other/j['name']/'tape.pt')['censored'] for j in jobs]).any(0).numpy()\n            torch.save(dict(common_valid=",1),
      ("slots=base['sparse_times'];obs_before=torch.cat((base['initial_history'][None],base['sparse_obs'][:-1]),0)","action_base=load(Path(plan['random_action_root'])/source_job['name']/'tape.pt')\n            slots=action_base['sparse_times'];obs_before=torch.cat((action_base['initial_history'][None],action_base['sparse_obs'][:-1]),0)",1),
      ("expected_actions-base['actions'][action_times]","expected_actions-action_base['actions'][action_times]",1),
      ("            groups[f'{seed}/{behavior}']=group", "            torch.save({b:d['prediction'] for b,d in tapes.items()},root/f'predictions_{seed}_{behavior}.pt')\n            groups[f'{seed}/{behavior}']=group",1)]
    for before,after,count in edits:
        assert source.count(before)==count,(before,source.count(before));source=source.replace(before,after)
    namespace={};exec(compile(source,'<arm_training_physical_scorer>','exec'),globals(),namespace)
    for domain in ('random','arm_fixed'):
        current=Path(plan['physical_reuse'][domain]);old=read(current/'plan.json');folder=root/('physical_'+domain);folder.mkdir(exist_ok=False)
        config=copy.deepcopy(old);config['models']={str(seed):{p:plan['models'][f'{seed}_{p}'] for p in ('initial','random','arm_fixed')} for seed in (140001,140002)}
        config['source_sha256']=plan['source_sha256'];config['physical_input_root']=str(current)
        config['protocol']['scoring_policies']=['initial','random','arm_fixed'];config['random_action_root']=plan['physical_reuse']['random']
        config['paired_root']=plan['physical_reuse']['arm_fixed' if domain=='random' else 'random']
        config['recorded_source_sha256']={seed:{p:old['source_sha256'][p] for p in old['models'][seed].values()} for seed in old['models']}
        for name in ('audit_before.py','protected_sha256.json'):shutil.copy2(root/name,folder/name)
        (folder/'plan.json').write_text(json.dumps(config,indent=2)+'\n');(folder/'status.json').write_text(json.dumps(dict(state='experiments_complete'))+'\n')
        namespace['summarize_gym_current_force'](SimpleNamespace(probe_output=folder))


def verify_gym_arm_training(args):
    """Check both restored Adams, paired sampling, interventions and float64 metrics."""
    import ast
    import hashlib
    import numpy as np
    import torch
    root=args.probe_output.resolve();read=lambda p:json.loads(Path(p).read_text())
    load=lambda p:torch.load(p,map_location='cpu',weights_only=False)
    sha=lambda p:hashlib.sha256(Path(p).read_bytes()).hexdigest()
    plan=read(root/'analysis_plan.json');policies=('initial','random','arm_fixed');checks={};pairs={};metric_checks=0
    def same(a,b):
        if torch.is_tensor(a):return torch.equal(a,b)
        if isinstance(a,dict):return a.keys()==b.keys() and all(same(v,b[k]) for k,v in a.items())
        if isinstance(a,(tuple,list)):return len(a)==len(b) and all(same(x,y) for x,y in zip(a,b))
        return a==b
    def check(a,b):
        nonlocal metric_checks
        assert torch.allclose(torch.as_tensor(a,dtype=torch.float64),torch.as_tensor(b,dtype=torch.float64),atol=2e-6,rtol=2e-7),(a,b)
        metric_checks+=1
    def verify_force(p,y,z,row):
        f=p.double()[:,6:9]*100;t=y.double()[:,6:9]*100;active=t.norm(dim=-1)>1;zero=t.norm(dim=-1)<.05
        check((f-t).square().mean().sqrt(),row['force_rmse_per_axis_n']);check(t.square().mean().sqrt(),row['constant_zero_rmse_per_axis_n'])
        if active.any():check((f[active]-t[active]).norm(dim=-1).mean(),row['active_vector_error_n'])
        if zero.any():check(f[zero].norm(dim=-1).mean(),row['zero_estimate_norm_n'])
        if z.any():check(f[z].norm(dim=-1).mean(),row['sustained_zero_norm_n'])
    def motor_pair(a,b,ma,mb,n):
        for key in ('masses','coms','inertias','materials','rng','state'):assert same(a[key],b[key]),key
        for key in ('obs','obs_pred'):assert torch.equal(a['observations'][key],b['observations'][key]),key
        original=torch.tensor(ma['original']);actual_a=torch.tensor(ma['actual']);actual_b=torch.tensor(mb['actual'])
        assert torch.equal(original,torch.tensor(mb['original'])) and torch.equal(actual_a,original)
        expected=original.clone();expected[:,8:]=1.;assert torch.equal(actual_b,expected)
        assert torch.equal(a['motor_strength'],actual_a) and torch.equal(b['motor_strength'],actual_b)
        x=a['observations']['privileged_obs'].reshape(n,3,98).clone();y=b['observations']['privileged_obs'].reshape(n,3,98).clone()
        assert torch.equal(x[:,:,:26],y[:,:,:26]) and torch.equal(x[:,:,32:],y[:,:,32:])
        assert torch.count_nonzero(y[:,:,26:32])==0
        return dict(same_non_motor_properties_state_rng=True,same_student_inputs=True,truthful_arm_critic_only=True,arm_fixed_base_original=True)
    for job in plan['training_jobs']:
        folder=root/job['name'];seed=job['model_seed'];initial=load(plan['models'][f'{seed}_initial']);r=read(folder/'result.json')
        assert r['all_passed'] and r['ppo_updates']==4000 and r['auxiliary_updates']==4000 and r['bank_auxiliary_calls']==4000 and r['motor_checked_steps']==4800
        assert all(v['independent_tensors'] for v in r['restoration'].values())
        assert r['checks']['labels']==4800 and r['checks']['history']==4800 and r['checks']['timeouts']==4800
        order=load(folder/'sample_order.pt');expected=torch.stack([torch.randperm(3072,generator=torch.Generator().manual_seed(job['seed']+220000+200+i)) for i in range(200)])
        assert torch.equal(order['minibatch_permutations'],expected)
        gen=torch.Generator().manual_seed(job['seed']+210000);count=plan['bank_samples'][str(seed)]
        for _ in range(4000):torch.randint(count,(384,),generator=gen)
        expected=torch.stack([torch.randint(count,(384,),generator=gen) for _ in range(4000)])
        assert torch.equal(order['bank_indices'],expected)
        for node in (50,100,200):
            ck=load(folder/f'joint_iter_{node:04d}.pt');assert ck['iterations']==9200+node and ck['global_policy_steps']==220800+node*24
            for k in ('optimizer_state_dict','adaptation_optimizer_state_dict'):
                assert ck[k]['state'].keys()==initial[k]['state'].keys()
                for pid,st in ck[k]['state'].items():
                    assert float(st['step'])==float(initial[k]['state'][pid]['step'])+node*20
                    assert all(torch.isfinite(t).all() for t in st.values() if torch.is_tensor(t))
            assert ck['adaptation_optimizer_state_dict']['param_groups']==initial['adaptation_optimizer_state_dict']['param_groups']
            assert all(torch.isfinite(v).all() for v in ck['model_state_dict'].values())
        assert torch.equal(ck['replay_generator_state'],gen.get_state())
        checks[job['name']]=dict(ppo_updates=4000,auxiliary_updates=4000,verified_minibatch_permutations=200,verified_bank_draws=4000,motor_checked_steps=r['motor_checked_steps'],restoration=r['restoration'],rollout_checks=r['checks'])
    for seed in (140001,140002):
        a=root/f'train_{seed}_random';b=root/f'train_{seed}_arm_fixed'
        assert same(load(a/'sample_order.pt'),load(b/'sample_order.pt'))
        pairs[str(seed)]=motor_pair(load(a/'initial_state.pt'),load(b/'initial_state.pt'),read(a/'motor_intervention.json'),read(b/'motor_intervention.json'),128)
        pairs[str(seed)].update(same_bank_draws=True,same_minibatch_order=True,independent_processes=True)
        first_a=load(a/'first_rollout.pt');first_b=load(b/'first_rollout.pt')
        for key in ('observations','observation_preds','actions','mu','sigma','actions_log_prob'):assert torch.equal(first_a[key][0],first_b[key][0]),key
        pairs[str(seed)]['same_first_behavior_action_and_student_input']=True
        del first_a,first_b
        sim=plan['test_seeds'][str(seed)]
        for behavior in ('mean','sample'):
            a=root/f'random_m{seed}_s{sim}_{behavior}_initial';b=root/f'arm_fixed_m{seed}_s{sim}_{behavior}_initial'
            pairs[f'{seed}/{behavior}/holdout']=motor_pair(load(a/'initial_state.pt'),load(b/'initial_state.pt'),read(a/'motor_intervention.json'),read(b/'motor_intervention.json'),32)
    summary=dict(averaging='Arithmetic mean across two related sources, one unseen sim seed each; no window-level independent statistics',fixed={},closed={},controls={},physical={},per_source={},training_trends={})
    average=lambda rows:{k:float(np.mean([r[k] for r in rows])) for k,v in rows[0].items() if isinstance(v,(int,float)) and all(r[k] is not None for r in rows)}
    for domain in ('random','arm_fixed'):
        folder=root/('closed_'+domain);results=read(folder/'results.json');evidence=load(folder/'cross_predictions.pt')
        for name,e in evidence.items():
            for policy,p in e['predictions'].items():verify_force(p,e['target'],e['sustained_zero'],results['per_replay'][name]['cross'][policy])
        summary['fixed'][domain]={};summary['closed'][domain]={};summary['controls'][domain]={};summary['per_source'][domain]=results['merged']
        for behavior in ('mean','sample'):
            summary['fixed'][domain][behavior]={p:average([results['merged'][str(s)][behavior]['initial']['cross'][p] for s in (140001,140002)]) for p in policies}
            summary['closed'][domain][behavior]={p:average([results['merged'][str(s)][behavior][p]['force'] for s in (140001,140002)]) for p in policies}
            summary['controls'][domain][behavior]={p:average([results['merged'][str(s)][behavior][p]['controls']['all_steps'] for s in (140001,140002)]) for p in policies}
        physical=read(root/('physical_'+domain)/'results.json');summary['physical'][domain]=physical['summary']
        for group,g in physical['groups'].items():
            seed,behavior=group.split('/');preds=load(root/('physical_'+domain)/f'predictions_{seed}_{behavior}.pt');pp=read(root/('physical_'+domain)/'plan.json')
            jobs=[j for j in pp['jobs'] if str(j['model_seed'])==seed and j['behavior']==behavior];tapes={j['branch']:load(Path(plan['physical_reuse'][domain])/j['name']/'tape.pt') for j in jobs}
            mask=load(root/('physical_'+domain)/f'masks_{seed}_{behavior}.pt')['common_valid'];phase=mask.clone();phase[:224]=False;phase[288:]=False
            def world(d,p):
                q=d['root_quat'].double();w,x,y,z=q.unbind(-1);angle=torch.atan2(2*(w*z+x*y),1-2*(y*y+z*z));c,s=angle.cos(),angle.sin()
                return torch.stack((c*p[...,0]-s*p[...,1],s*p[...,0]+c*p[...,1],p[...,2]),-1)
            for p in policies:
                rows=[];deltas=[];truths=[];base=tapes['source'];bw=world(base,preds['source'][p][:,:,6:9].double()*100)
                for branch in ('x+1','x-1','y+1','y-1','z+1','z-1'):
                    d=tapes[branch];f=preds[branch][p][:,:,6:9].double()*100;t=d['target'][:,:,6:9].double()*100
                    row=g['cases'][branch]['plateau'][p];check((f[phase]-t[phase]).square().mean().sqrt(),row['force_rmse_per_axis_n']);check((f[phase]-t[phase]).norm(dim=-1).mean(),row['active_vector_error_n'])
                    delta=(world(d,f)-bw)[phase];truth=(d['force_world']-base['force_world']).double()[phase]
                    response=g['response'][branch]['plateau'][p];check((delta*truth).sum()/truth.square().sum(),response['force_direction_gain']);check((delta-truth).square().mean().sqrt(),response['delta_force_rmse_per_axis_n'])
                    deltas.append(delta);truths.append(truth)
                delta=torch.cat(deltas);truth=torch.cat(truths);row=g['aggregate'][p]
                check((delta*truth).sum()/truth.square().sum(),row['mean_direction_gain']);check((delta-truth).square().mean().sqrt(),row['delta_force_rmse_per_axis_n'])
                for label,start,end in [('source_plateau',224,288),('pre_zero',96,160),('recovery_zero',352,512)]:
                    m=mask.clone();m[:start]=False;m[end:]=False;f=preds['source'][p][:,:,6:9].double()*100
                    check(f[m].norm(dim=-1).mean(),row[label]['zero_estimate_norm_n'])
    for job in plan['training_jobs']:
        progress=read(root/job['name']/'progress.json');summary['training_trends'][job['name']]=[row for row in progress if 'validation' in row]
    null_checks={}
    for seed in (140001,140002):
        current=root/f'train_{seed}_random';previous=OUT/f'gym_replay_retention_20261026_v1/train_{seed}_replay_retained'
        row={name:same(load(current/name),load(previous/name)) for name in ('initial_state.pt','first_rollout.pt','first_ppo_model.pt','sample_order.pt')}
        for node in (50,100,200):
            a=load(current/f'joint_iter_{node:04d}.pt');b=load(previous/f'joint_iter_{node:04d}.pt')
            row[str(node)]={key:same(a[key],b[key]) for key in ('model_state_dict','optimizer_state_dict','adaptation_optimizer_state_dict')}
        assert all(row[k] for k in ('initial_state.pt','first_rollout.pt','first_ppo_model.pt','sample_order.pt'))
        null_checks[str(seed)]=row
    (root/'null_intervention_verification.json').write_text(json.dumps(null_checks,indent=2)+'\n')
    for name in ('protected_sha256.json','frozen_holdout_sha256.json','frozen_bank_sha256.json'):
        for p,h in read(root/name).items():assert sha(p)==h,p
    for name,files in read(root/'completed_job_sha256.json').items():
        for p,h in files.items():assert sha(p)==h,p
    definitions=lambda p:{n.name:ast.dump(n,include_attributes=False) for n in ast.parse(Path(p).read_text()).body if isinstance(n,(ast.FunctionDef,ast.ClassDef))}
    old,new=definitions(root/'audit_before.py'),definitions(Path(__file__));assert all(new[k]==v for k,v in old.items())
    (root/'summary.json').write_text(json.dumps(summary,indent=2,allow_nan=False)+'\n')
    (root/'completion_verification.json').write_text(json.dumps(dict(all_passed=True,training=checks,pairs=pairs,independent_float64_metric_checks=metric_checks,old_functions_unchanged=len(old),protected_files=len(read(root/'protected_sha256.json')),total_new_ppo_updates=16000,total_new_auxiliary_updates=16000,evaluation_optimizer_steps=0,formal_training_resumed=False),indent=2)+'\n')
    import matplotlib
    matplotlib.use('Agg')
    import matplotlib.pyplot as plt
    fig,axes=plt.subplots(2,3,figsize=(14,8));labels=['9200 start','9400 random','9400 arm fixed'];colors=['#85929e','#5089be','#d18a52']
    for row,domain in zip(axes,('random','arm_fixed')):
        panels=[([summary['fixed'][domain]['mean'][p]['force_rmse_per_axis_n'] for p in policies],'Fixed-input mean-action RMSE (N/axis)'),
            ([summary['closed'][domain]['mean'][p]['sustained_zero_norm_n'] for p in policies],'Own-loop mean-action sustained zero (N)'),
            ([summary['physical'][domain]['mean'][p]['mean_direction_gain'] for p in policies],'Same-action true-force gain / ideal 1')]
        for ax,(values,title) in zip(row,panels):
            ax.bar(range(3),values,color=colors);ax.set_xticks(range(3),labels,rotation=15,ha='right');ax.set_title(domain+' / '+title,fontsize=9);ax.grid(axis='y',alpha=.2);ax.set_axisbelow(True)
            for i,v in enumerate(values):ax.text(i,v,f'{v:.3f}',ha='center',va='bottom',fontsize=9)
        row[2].axhline(1,color='gray',ls='--');row[2].set_ylim(0,1.1)
    fig.suptitle('Arm-only amplitude intervention / paired 200 joint iterations / two related sources');fig.tight_layout();fig.savefig(root/'arm_training_comparison.png',dpi=160);plt.close(fig)
    fig,axes=plt.subplots(2,2,figsize=(12,8))
    for row,seed in zip(axes,(140001,140002)):
        for ax,domain in zip(row,('random','arm_fixed')):
            for policy,color in zip(('random','arm_fixed'),colors[1:]):
                rows=summary['training_trends'][f'train_{seed}_{policy}'];xs=[];ys=[]
                for record in rows:
                    values=[v['force_rmse_per_axis_n'] for k,v in record['validation'].items() if k.startswith(domain+'_') and '_mean_' in k]
                    assert len(values)==1;xs.append(record['iteration']);ys.append(values[0])
                ax.plot(xs,ys,'o-',color=color,label=policy+' training')
            ax.set_title(str(seed)+' / '+domain+' fixed mean-action holdout');ax.set_xlabel('Added joint iterations');ax.set_ylabel('Force RMSE (N/axis)');ax.grid(alpha=.2);ax.legend()
    fig.tight_layout();fig.savefig(root/'arm_training_trends.png',dpi=160);plt.close(fig)
    print('ARM_TRAINING_ANALYSIS_CHECKED',metric_checks,flush=True)


def gym_encoder_actor_model(model, key, plan):
    """Frozen crossed behavior; decoder always matches encoder, never actor."""
    import torch
    seed,combo=str(key).split('_');e=int(combo[1]);a=int(combo[3])
    assert combo in ('E0A0','E0A1','E1A0','E1A1')
    old=torch.load(plan['evidence_models'][seed+'_initial'],map_location='cpu',weights_only=False)['model_state_dict']
    new=torch.load(plan['evidence_models'][seed+'_arm_fixed'],map_location='cpu',weights_only=False)['model_state_dict']
    expected={}
    for k in model.state_dict():
        source=(old if e==0 else new) if k.startswith(('adaptation_encoder_module.','adaptation_decoder_module.')) else (old if a==0 else new)
        expected[k]=source[k].clone()
    model.load_state_dict(expected);model.eval();model.requires_grad_(False)
    assert all(torch.equal(v,expected[k]) for k,v in model.state_dict().items())
    return model


def gym_encoder_actor_collect(args):
    """Reuse passive collector and arm-domain backend; replace frozen behavior."""
    import inspect
    root=args.probe_output.resolve();plan=json.loads((root/'plan.json').read_text())
    job=next(j for j in plan['jobs'] if j['name']==args.coverage_job)
    assert 'reuse' not in job and job['behavior']=='mean'
    original_collect=gym_behavior_coverage_collect;original_backend=gym_ranger_backend
    collect=gym_replay_control_function(original_collect,[
        ("model.eval();model.requires_grad_(False);before=", "gym_encoder_actor_model(model,job['model_seed'],plan)\n    model.eval();model.requires_grad_(False);before=",1)],'<encoder_actor_frozen_collect>')
    worker=gym_replay_control_function(gym_coverage_closed_loop_worker,[
        ('backend=gym_ranger_backend;rows=[]',"backend=lambda *a,**kw:gym_arm_training_backend(job['domain'],root/job['name'],*a,**kw)\n    rows=[]",1),
        ("    job=next(j for j in plan['jobs'] if j['name']==args.coverage_job)","    job=next(j for j in plan['jobs'] if j['name']==args.coverage_job)",1)],'<encoder_actor_passive_worker>')
    globals()['_gym_arm_training_original_backend']=original_backend
    globals()['gym_behavior_coverage_collect']=collect
    try:worker(args)
    finally:
        globals()['gym_behavior_coverage_collect']=original_collect
        globals()['gym_ranger_backend']=original_backend
        del globals()['_gym_arm_training_original_backend']


def gym_encoder_actor_replay(args):
    """Four frozen means on identical saved histories, with exact factorial sum."""
    import contextlib
    import hashlib
    import io
    import os
    affinity=os.sched_getaffinity(0);os.sched_setaffinity(0,{min(affinity)})
    import torch
    from legged_gym.b2_gym_learn.ppo_cse_pf.actor_critic import ActorCritic
    os.sched_setaffinity(0,affinity);torch.set_num_threads(2)
    root=args.probe_output.resolve();plan=json.loads((root/'plan.json').read_text());models={};rows={};saved={}
    for key,path in plan['models'].items():
        with contextlib.redirect_stdout(io.StringIO()):m=ActorCritic(1856,294,12,58,14,actor_hidden_dims=[512,256,128],critic_hidden_dims=[512,256,128])
        models[key]=gym_encoder_actor_model(m,key,plan)
    with torch.inference_mode():
        for job in plan['jobs']:
            if 'reuse' not in job:continue
            folder=Path(job['reuse']);d=torch.load(folder/'data.pt',map_location='cpu',weights_only=False)
            mask=d['full_history'];x=d['obs'][mask];seed=job['training_seed'];actions={};force={}
            for combo in ('E0A0','E0A1','E1A0','E1A1'):
                m=models[f'{seed}_{combo}'];actions[combo]=torch.cat([m.act_inference({'obs':b}) for b in x.split(512)])
                force[combo]=torch.cat([m.get_student_latent(b) for b in x.split(512)])
            assert torch.equal(force['E0A0'],force['E0A1']) and torch.equal(force['E1A0'],force['E1A1'])
            encoder=actions['E1A0']-actions['E0A0'];actor=actions['E0A1']-actions['E0A0']
            total=actions['E1A1']-actions['E0A0'];interaction=total-encoder-actor
            assert torch.allclose(encoder+actor+interaction,total,atol=2e-6,rtol=1e-6)
            effect={}
            for label,delta in [('encoder_only',encoder),('actor_only',actor),('interaction',interaction),('total',total)]:
                effect[label]={part:dict(action_rms=float(delta[:,sl].double().square().mean().sqrt()),target_rms=float((delta[:,sl]*scale).double().square().mean().sqrt()),target_unit=unit)
                    for part,sl,scale,unit in [('steering',slice(0,4),.25,'rad'),('wheel',slice(4,8),5.,'rad/s'),('arm',slice(8,14),.25,'rad')]}
            rows[job['name']]=dict(job=job,samples=len(x),effects=effect,input_sha256=hashlib.sha256((folder/'data.pt').read_bytes()).hexdigest(),force_decoder_pairs_matched=True)
            saved[job['name']]=dict(actions=actions,valid_index=mask.nonzero(),encoder=encoder,actor=actor,interaction=interaction)
            print('ENCODER_ACTOR_FIXED_REPLAY',job['name'],effect,flush=True)
    torch.save(saved,root/'fixed_action_predictions.pt')
    (root/'fixed_action_replay.json').write_text(json.dumps(dict(all_passed=True,optimizer_steps=0,rows=rows),indent=2)+'\n')


def gym_encoder_actor_run(args):
    """Reuse sequential bounded queue; only eight new frozen evaluations."""
    edits=[('gym_joint_coverage_20261025_v1','gym_encoder_actor_cross_20261026_v1',1),
        ("sequence=[('validation',j) for j in plan['jobs'] if j['policy']=='initial']+[('training',j) for j in plan['training_jobs']]+[('evaluation',j) for j in plan['jobs'] if j['policy']!='initial']", "sequence=[('evaluation',j) for j in plan['jobs'] if 'reuse' not in j]",1),
        ('--gym_coverage_closed_loop_worker','--gym_encoder_actor_collect',1),
        ('frozen_holdout_sha256.json','frozen_inputs_sha256.json',4)]
    gym_replay_control_function(run_gym_joint_coverage,edits,'<encoder_actor_frozen_queue>')(args)


def gym_encoder_actor_summary(args):
    """Reuse full history, force, action and control checks in each domain."""
    import copy
    import inspect
    from types import SimpleNamespace
    root=args.probe_output.resolve();plan=json.loads((root/'plan.json').read_text())
    source=inspect.getsource(summarize_gym_coverage_closed_loop).split('    # Read-only evaluation on the already completed same-action physical',1)[0]
    edits=[("policies=('initial','sample_only','mixed')","policies=('E0A0','E0A1','E1A0','E1A1')",1),
        ("m.load_state_dict(torch.load(path,map_location='cpu',weights_only=False)['model_state_dict']);m.eval()", "m.load_state_dict(torch.load(path,map_location='cpu',weights_only=False)['model_state_dict']);gym_encoder_actor_model(m,key,plan);m.eval()",1),
        ("os.sched_setaffinity(0,{min(os.sched_getaffinity(0))})","affinity=os.sched_getaffinity(0);os.sched_setaffinity(0,{min(affinity)})",1),
        ("torch.set_num_threads(1)","os.sched_setaffinity(0,affinity);torch.set_num_threads(2)",1),
        ("('mean','sample')","('mean',)",2),
        ("(149101,149102)","(plan['test_seeds'][str(seed)],)",2),
        ("_mean_initial'","_mean_E0A0'",1),
        ("sum(c[k]**2 for c in cs)/2","sum(c[k]**2 for c in cs)/len(cs)",1),
        ("sum(c[k] for c in cs)/2","sum(c[k] for c in cs)/len(cs)",1)]
    for before,after,count in edits:
        assert source.count(before)==count,(before,source.count(before),count);source=source.replace(before,after)
    source+="    write(root/'results.json',dict(merged=merged,per_replay=cases))\n    write(root/'independent_verification.json',dict(all_passed=True,history_label_action_termination_checks=checks,numpy_metric_evaluations=metric_checks,forward_action_checks=forward,initial_pair_checks=initial_checks,optimizer_steps=0))\n"
    namespace={};exec(compile(source,'<encoder_actor_cross_scorer>','exec'),globals(),namespace)
    for domain in ('arm_fixed','random'):
        folder=root/('closed_'+domain);folder.mkdir(exist_ok=False);config=copy.deepcopy(plan);config['jobs']=[]
        for job in plan['jobs']:
            if job['domain']!=domain:continue
            j=dict(job);j['name']=job['name'][len(domain)+1:];config['jobs'].append(j)
            (folder/j['name']).symlink_to(Path(job['reuse']) if 'reuse' in job else root/job['name'],target_is_directory=True)
        (folder/'plan.json').write_text(json.dumps(config,indent=2)+'\n')
        (folder/'status.json').write_text(json.dumps(dict(state='ready_for_independent_analysis'))+'\n')
        namespace['summarize_gym_coverage_closed_loop'](SimpleNamespace(probe_output=folder))


def verify_gym_encoder_actor(args):
    """Independent float64 force/action checks and matched-scorer comparisons."""
    import ast
    import os
    affinity=os.sched_getaffinity(0);os.sched_setaffinity(0,{min(affinity)})
    import numpy as np
    import torch
    os.sched_setaffinity(0,affinity);torch.set_num_threads(2)
    root=args.probe_output.resolve();read=lambda p:json.loads(Path(p).read_text())
    load=lambda p:torch.load(p,map_location='cpu',weights_only=False)
    plan=read(root/'plan.json');comparisons={};checks=0
    for domain in ('arm_fixed','random'):
        folder=root/('closed_'+domain);result=read(folder/'results.json');evidence=load(folder/'cross_predictions.pt')
        assert read(folder/'independent_verification.json')['all_passed']
        comparisons[domain]={}
        for seed in (140001,140002):
            sim=plan['test_seeds'][str(seed)];rows={}
            for combo in ('E0A0','E0A1','E1A0','E1A1'):
                name=f'm{seed}_s{sim}_mean_{combo}';r=result['per_replay'][name];d=evidence[name]
                target=d['target'].double().numpy()[:,6:9]*100;norm=np.linalg.norm(target,axis=-1)
                predictions=d['predictions'];assert torch.equal(predictions['E0A0'],predictions['E0A1']) and torch.equal(predictions['E1A0'],predictions['E1A1'])
                for policy,p in predictions.items():
                    force=p.double().numpy()[:,6:9]*100
                    metrics={'force_rmse_per_axis_n':float(np.sqrt(np.mean((force-target)**2))),
                        'constant_zero_rmse_per_axis_n':float(np.sqrt(np.mean(target**2))),
                        'active_vector_error_n':float(np.linalg.norm(force[norm>1]-target[norm>1],axis=-1).mean()),
                        'zero_estimate_norm_n':float(np.linalg.norm(force[norm<.05],axis=-1).mean()),
                        'sustained_zero_norm_n':float(np.linalg.norm(force[d['sustained_zero'].numpy()],axis=-1).mean())}
                    for k,v in metrics.items():np.testing.assert_allclose(v,r['cross'][policy][k],atol=2e-6,rtol=2e-7);checks+=1
                rows[combo]=dict(old_matched_estimator=r['cross']['E0A0'],new_matched_estimator=r['cross']['E1A1'],controls=r['controls']['all_steps'])
            comparisons[domain][str(seed)]=rows
    replay=load(root/'fixed_action_predictions.pt');nominal=read(root/'fixed_action_replay.json');actual={}
    for name,row in replay.items():
        job=nominal['rows'][name]['job'];strength=load(Path(job['reuse'])/'initial_state.pt')['motor_strength'].double().numpy()
        actions={k:v.double().numpy() for k,v in row['actions'].items()}
        assert all(np.max(np.abs(v))<100 for v in actions.values())
        e=actions['E1A0']-actions['E0A0'];a=actions['E0A1']-actions['E0A0'];total=actions['E1A1']-actions['E0A0'];interaction=total-e-a
        ids=row['valid_index'][:,1].numpy();s=strength[ids];actual[name]={}
        for label,value in [('encoder_only',e),('actor_only',a),('interaction',interaction),('total',total)]:
            actual[name][label]={}
            for part,sl,scale,unit in [('steering',slice(0,4),.25,'rad'),('wheel',slice(4,8),5.,'rad/s'),('arm',slice(8,14),.25,'rad')]:
                rms=float(np.sqrt(np.mean(value[:,sl]**2)));recorded=nominal['rows'][name]['effects'][label][part]['action_rms']
                np.testing.assert_allclose(rms,recorded,atol=2e-6,rtol=2e-6);checks+=1
                actual[name][label][part]=dict(action_rms=rms,actual_target_rms=float(np.sqrt(np.mean((value[:,sl]*s[:,sl]*scale)**2))),unit=unit)
    means={}
    for domain,by_seed in comparisons.items():
        means[domain]={}
        for combo in ('E0A0','E0A1','E1A0','E1A1'):
            means[domain][combo]={}
            for group in ('old_matched_estimator','new_matched_estimator','controls'):
                parts=[by_seed[str(seed)][combo][group] for seed in (140001,140002)]
                means[domain][combo][group]={k:sum(p[k] for p in parts)/2 for k in parts[0] if all(isinstance(p[k],(int,float)) for p in parts)}
    old={n.name:ast.dump(n,include_attributes=False) for n in ast.parse((root/'audit_before.py').read_text()).body if isinstance(n,(ast.FunctionDef,ast.ClassDef))}
    current={n.name:ast.dump(n,include_attributes=False) for n in ast.parse(Path(__file__).read_text()).body if isinstance(n,(ast.FunctionDef,ast.ClassDef))}
    assert all(current.get(k)==v for k,v in old.items())
    summary=dict(protocol='Same complete matched old/new force estimators cross-score all four frozen behavior combinations; mean across related sources is descriptive.',per_source=comparisons,source_means=means,actual_target_action_replay=actual)
    (root/'summary.json').write_text(json.dumps(summary,indent=2,allow_nan=False)+'\n')
    (root/'completion_verification.json').write_text(json.dumps(dict(all_passed=True,independent_numpy_force_and_action_checks=checks,old_definitions_unchanged=len(old),total_definitions=len(current),optimizer_steps=0,training_started=False,formal_training_resumed=False),indent=2)+'\n')
    import matplotlib
    matplotlib.use('Agg')
    import matplotlib.pyplot as plt
    combos=('E0A0','E0A1','E1A0','E1A1');fig,axes=plt.subplots(2,3,figsize=(15,8))
    for row,seed in zip(axes,(140001,140002)):
        for ax,key,group,title in zip(row,('force_rmse_per_axis_n','sustained_zero_norm_n','ee_force_target_error_mean_m'),('new_matched_estimator','new_matched_estimator','controls'),('Force RMSE / matched new estimator (N/axis)','Sustained-zero norm / matched new estimator (N)','EE force-target error (m)')):
            for domain,color in [('arm_fixed','#277c73'),('random','#ba7750')]:
                ax.plot(combos,[comparisons[domain][str(seed)][c][group][key] for c in combos],'o-',color=color,label=domain)
            ax.set_title(str(seed)+' / '+title,fontsize=9);ax.set_xlabel('E0/A0 old; E1/A1 new');ax.grid(alpha=.2);ax.legend(fontsize=8)
    fig.suptitle('Frozen encoder x actor behavior / no training / same matched estimators')
    fig.tight_layout();fig.savefig(root/'encoder_actor_comparison.png',dpi=160);plt.close(fig)
    print('ENCODER_ACTOR_INDEPENDENT_CHECKS',checks,flush=True)



def gym_b2_fresh_worker(args):
    """Released registry/runner from random weights; instrumentation only."""
    import os, time, hashlib, traceback, random, copy, subprocess
    from types import SimpleNamespace as NS
    output=args.probe_output.resolve(); output.mkdir(parents=True,exist_ok=False)
    root=args.joint_root.resolve(); plan=json.loads((root/'plan.json').read_text())
    sha=lambda p:hashlib.sha256(Path(p).read_bytes()).hexdigest()
    def write(path,value):
        temp=path.with_suffix(path.suffix+'.tmp')
        temp.write_text(json.dumps(value,indent=2,allow_nan=False,default=lambda x:x.tolist())+'\n');temp.replace(path)
    # Empty force strata are reported as null, never NaN or a spurious zero.
    def finite_json(v):
        import math
        if isinstance(v,dict):return {k:finite_json(x) for k,x in v.items()}
        if isinstance(v,(list,tuple)):return [finite_json(x) for x in v]
        if isinstance(v,float) and not math.isfinite(v):return None
        return v
    resume_path=getattr(args,'resume_checkpoint',None)
    env=None; result=dict(state='initializing',mode=args.gym_b2_fresh_mode,
        seed=args.ablation_seed,source_checkpoint=str(resume_path) if resume_path else None,diagnostic_only=True)
    write(output/'status.json',result)
    try:
        for rel,digest in plan['protected_sources_sha256'].items():assert sha(ROOT/rel)==digest,rel
        affinity=os.sched_getaffinity(0);os.sched_setaffinity(0,{min(affinity)})
        from isaacgym import gymapi
        import torch
        os.sched_setaffinity(0,affinity);torch.set_num_threads(int(os.environ.get('UNIFP_BASELINE_THREADS','2')))
        import numpy as np
        from legged_gym.envs import task_registry
        from legged_gym.utils import get_args,class_to_dict
        n=args.gym_b2_fresh_envs
        sys.argv=['fresh_b2','--task=b2z1_pos_force','--headless','--num_envs='+str(n),
            '--sim_device=cuda:0','--pipeline=cpu','--rl_device=cpu','--seed='+str(args.ablation_seed)]
        native_args=get_args();env_cfg,train_cfg=task_registry.get_cfgs(native_args.task)
        env_cfg.seed=train_cfg.seed=args.ablation_seed
        assert not train_cfg.runner.resume
        # No task/config/optimizer modification. Synchronize CPU tensors from constructor onward.
        acquire=gymapi.acquire_gym;native=acquire()
        class SyncedGym:
            def __getattr__(self,name):return getattr(native,name)
            def fetch_results(self,*a,**kw):return None
            def simulate(self,sim):native.simulate(sim);native.fetch_results(sim,True)
        gymapi.acquire_gym=lambda:SyncedGym()
        os.chdir(ROOT/'UniFP')
        try:env,env_cfg=task_registry.make_env(native_args.task,args=native_args,env_cfg=env_cfg)
        finally:gymapi.acquire_gym=acquire
        runner,train_cfg=task_registry.make_alg_runner(env,args=native_args,train_cfg=train_cfg,log_root=None)
        model=runner.alg.actor_critic;alg=runner.alg
        assert len(alg.optimizer.state)==len(alg.adaptation_module_optimizer.state)==0
        assert runner.current_learning_iteration==0
        # The native runner performs one reset/step before learn. Preserve this official offset.
        initial_steps=int(env.global_steps)
        assert initial_steps in (0,1)
        initial_iteration=0; step_offset=0; adam_offsets={'ppo':0,'auxiliary':0}
        if resume_path:
            ck=torch.load(resume_path,map_location='cpu',weights_only=False)
            source=plan['resume_checkpoints'][str(args.ablation_seed)]
            assert sha(resume_path)==source['sha256']
            assert ck['diagnostic_only'] and ck['seed']==args.ablation_seed
            assert ck['num_envs']==n and ck['steps_per_env']==runner.num_steps_per_env==24
            assert ck['iterations']==ck['iter']==source['iterations']
            model.load_state_dict(ck['model_state_dict'])
            alg.optimizer.load_state_dict(copy.deepcopy(ck['optimizer_state_dict']))
            alg.adaptation_module_optimizer.load_state_dict(copy.deepcopy(ck['adaptation_optimizer_state_dict']))
            alg.learning_rate=float(ck['learning_rate'])
            assert alg.optimizer.param_groups[0]['lr']==alg.learning_rate
            initial_iteration=int(ck['iterations']);runner.current_learning_iteration=initial_iteration
            initial_steps=int(ck['initial_global_policy_steps'])
            env.global_steps=int(ck['global_policy_steps'])
            step_offset=env.global_steps-initial_steps-24*initial_iteration
            assert step_offset==source['uncommitted_rollout_policy_steps']
            for name,opt,key in [('ppo',alg.optimizer,'optimizer_state_dict'),
                    ('auxiliary',alg.adaptation_module_optimizer,'adaptation_optimizer_state_dict')]:
                steps=sorted({int(s['step']) for s in opt.state.values()})
                assert len(steps)==1
                adam_offsets[name]=steps[0]-20*initial_iteration
            assert adam_offsets==source['adam_update_offsets']
            def equal(x,y):
                if isinstance(x,torch.Tensor):return isinstance(y,torch.Tensor) and torch.equal(x,y)
                if isinstance(x,dict):return x.keys()==y.keys() and all(equal(x[k],y[k]) for k in x)
                if isinstance(x,(list,tuple)):return len(x)==len(y) and all(equal(i,j) for i,j in zip(x,y))
                return x==y
            assert equal(model.state_dict(),ck['model_state_dict'])
            assert equal(alg.optimizer.state_dict(),ck['optimizer_state_dict'])
            assert equal(alg.adaptation_module_optimizer.state_dict(),ck['adaptation_optimizer_state_dict'])
            ptrs=lambda opt:{v.data_ptr() for s in opt.state.values() for v in s.values() if isinstance(v,torch.Tensor)}
            assert not ptrs(alg.optimizer)&ptrs(alg.adaptation_module_optimizer)
            torch.set_rng_state(ck['torch_rng']);np.random.set_state(ck['numpy_rng']);random.setstate(ck['python_rng'])
            assert torch.equal(torch.get_rng_state(),ck['torch_rng']) and random.getstate()==ck['python_rng']
            nr=np.random.get_state();assert nr[0]==ck['numpy_rng'][0] and np.array_equal(nr[1],ck['numpy_rng'][1]) and nr[2:]==ck['numpy_rng'][2:]
            result.update(restoration_verified=True,simulation_state_not_restored=True,
                history_not_restored=True,resume_checkpoint_sha256=sha(resume_path),
                restored_adam_state_counts=[len(alg.optimizer.state),len(alg.adaptation_module_optimizer.state)],
                adam_update_offsets=adam_offsets,uncommitted_rollout_policy_steps=step_offset,
                resume_global_policy_steps=int(env.global_steps),rng_restored_before_learn=True)
        target_iteration=int(args.ablation_iterations)
        assert target_iteration>initial_iteration
        assert (env.num_obs,env.num_privileged_obs,env.num_pred_obs,env.num_single_obs,env.num_actions)==(2336,447,12,73,17)
        assert env.cfg.commands.force_start_step==8000 and env.cfg.terrain.num_rows==10 and env.cfg.terrain.num_cols==20
        assert env.sim_params.physx.use_gpu and not env.sim_params.use_gpu_pipeline and str(env.device)=='cpu'
        original_cfg=dict(environment=class_to_dict(env_cfg),training=class_to_dict(train_cfg))
        write(output/'official_config.json',original_cfg)
        flags=NS(gym_sync_after_simulate=False,gym_zero_external_force=False,
            gym_fresh_timeouts=True,gym_control_action='policy')
        audit=install_gym_control_audit(env,alg,flags)
        result.update(initial_global_policy_steps=initial_steps,initial_iteration=initial_iteration,
            fresh_adam_state_counts=([0,0] if not resume_path else None),num_envs=n,steps_per_env=runner.num_steps_per_env,
            torch=str(torch.__version__),learner_threads=torch.get_num_threads(),sim_device=str(env.sim_device),learner_device=str(runner.device),
            official_cfg_sha256=sha(output/'official_config.json'),synchronization_includes_constructor=True,
            fresh_timeout_mask=True,init_at_random_ep_len=True,
            terrain_grid=[env.cfg.terrain.num_rows,env.cfg.terrain.num_cols])
        write(output/'initialization.json',result)
        completed=initial_iteration;start=time.monotonic();rows=[]
        def save_checkpoint(iteration):
            path=output/f'model_iter_{iteration:06d}.pt'
            if path.exists():return path
            state=dict(model_state_dict=model.state_dict(),optimizer_state_dict=alg.optimizer.state_dict(),
                adaptation_optimizer_state_dict=alg.adaptation_module_optimizer.state_dict(),
                iter=iteration,iterations=iteration,global_policy_steps=int(env.global_steps),
                initial_global_policy_steps=initial_steps,num_envs=n,steps_per_env=24,learning_rate=alg.learning_rate,
                source_checkpoint=str(resume_path) if resume_path else None,diagnostic_only=True,seed=args.ablation_seed,
                actual_force_start_iteration=int(env.cfg.commands.force_start_step),
                torch_rng=torch.get_rng_state(),numpy_rng=np.random.get_state(),python_rng=random.getstate(),
                simulation_state_not_restored=True,adam_update_offsets=adam_offsets,
                uncommitted_rollout_policy_steps=step_offset,resume_checkpoint_sha256=sha(resume_path) if resume_path else None,config=original_cfg)
            # We retain RNG and full optimizers; an ordinary future resume still resets PhysX/history.
            temp=path.with_suffix('.tmp');torch.save(state,temp);temp.replace(path)
            return path
        if args.gym_b2_fresh_mode=='evaluate':
            checkpoint=torch.load(args.replay_models_json,map_location='cpu')
            model.load_state_dict(checkpoint['model_state_dict']);model.eval();model.requires_grad_(False)
            saved={k:v.clone() for k,v in model.state_dict().items()}
            env.global_steps=int(checkpoint['global_policy_steps'])
            env.cfg.commands.force_start_step=int(checkpoint.get('actual_force_start_iteration',8000))
            # Dedicated zero-force trial preserves all randomization and force commands.
            if args.gym_zero_external_force:
                push=env._push_gripper
                def zero_push(*a,**kw):
                    push(*a,**kw);env.forces[:,env.gripper_idx]=0.
                env._push_gripper=zero_push
                env.forces[:,env.gripper_idx]=0.
            x=env.get_observations();traces={};sparse=[];sparse_steps=[]
            full=torch.zeros(n,dtype=torch.long);alignment=0.
            generator=torch.Generator().manual_seed(args.ablation_seed+190000)
            def add(k,v):traces.setdefault(k,[]).append(v.detach().clone())
            from isaacgym.torch_utils import quat_rotate_inverse
            with torch.inference_mode():
                for step in range(plan['replay_steps']):
                    obs,target=x['obs'],x['obs_pred'];pred=model.get_student_latent(obs)
                    expected=quat_rotate_inverse(env.base_yaw_quat,env.forces[:,env.gripper_idx])*0.01
                    alignment=max(alignment,float((target[:,6:9]-expected).abs().max())*100)
                    add('target',target);add('predictions',pred);add('full_history',full>=32)
                    if step%32==0:sparse.append(obs.clone());sparse_steps.append(step)
                    action=model.act_inference({'obs':obs})
                    if args.gym_ranger_sample_actions:action=action+model.std*torch.randn(action.shape,generator=generator)
                    add('actions',action)
                    x,reward,done,info=env.step(action)
                    s=audit['last_state'];add('done',done);add('timeout',env.time_out_buf);add('reward',reward)
                    add('ee_error',(s['ee_position']-s['goal_world']).norm(dim=-1))
                    add('base_velocity',env.base_lin_vel);add('base_angular_velocity',env.base_ang_vel)
                    add('velocity_command',s['commands'][:,:3])
                    full+=1;full[done.bool()]=1
                    if done.any():assert torch.count_nonzero(x['obs'][done.bool()].reshape(-1,32,73)[:,:-1])==0
                    audit['events'].clear()
            trace={k:torch.stack(v) for k,v in traces.items()}
            assert all(torch.isfinite(v).all() for v in trace.values()) and alignment<1e-4
            active=trace['target'][:,:,6:9].norm(dim=-1)*100>1
            zero=trace['target'][:,:,6:9].norm(dim=-1)*100<.05
            sustained=zero.clone()
            for lag in range(1,32):sustained[lag:] &= zero[:-lag]
            sustained &= trace['full_history'];sustained[:32]=False
            trace.update(sparse_obs=torch.stack(sparse),sparse_steps=sparse_steps)
            torch.save(trace,output/'trace.pt')
            p,y=trace['predictions'].flatten(0,1),trace['target'].flatten(0,1)
            vel=trace['base_velocity'][:,:,:2]-trace['velocity_command'][:,:,:2]
            yaw=trace['base_angular_velocity'][:,:,2]-trace['velocity_command'][:,:,2]
            result.update(state='complete',checkpoint=str(args.replay_models_json),checkpoint_sha256=sha(args.replay_models_json),
                checkpoint_iteration=checkpoint['iterations'],action_mode='sample' if args.gym_ranger_sample_actions else 'mean',
                zero_external_force=args.gym_zero_external_force,metrics=finite_json(auxiliary_metrics(p,y)),
                zero_baseline=finite_json(auxiliary_metrics(torch.zeros_like(p),y)),
                sustained_zero_count=int(sustained.sum()),active_force_count=int(active.sum()),
                sustained_zero_estimate_norm_n=float((trace['predictions'][:,:,6:9][sustained]*100).norm(dim=-1).mean()) if sustained.any() else None,
                ee_error_mean_m=float(trace['ee_error'].mean()),xy_velocity_rmse=float(vel.square().mean().sqrt()),
                yaw_velocity_rmse=float(yaw.square().mean().sqrt()),terminations=int(trace['done'].sum()),
                timeout_count=int((trace['done'].bool() & trace['timeout'].bool()).sum()),
                force_alignment_max_n=alignment,control_checks=audit['checks'],elapsed_s=time.monotonic()-start)
            assert all(torch.equal(v,saved[k]) for k,v in model.state_dict().items())
            write(output/'result.json',result);write(output/'status.json',result);return
        initial={k:v.clone() for k,v in model.state_dict().items()}
        save_checkpoint(initial_iteration)
        runner.log_dir=str(output);runner.writer=object();runner.save=lambda *a,**kw:None
        original_update=alg.update
        coverage={}
        def update():
            label=alg.storage.observation_preds[:,:,6:9]*100
            assert torch.isfinite(alg.storage.observations).all() and torch.isfinite(label).all()
            coverage.update(active_samples=int((label.norm(dim=-1)>1).sum()),zero_samples=int((label.norm(dim=-1)<.05).sum()),max_force_n=float(label.abs().max()))
            if completed==initial_iteration:
                torch.save(dict(num_envs_total=n,saved_env_ids=list(range(min(n,32))),
                    **{k:getattr(alg.storage,k)[:,:min(n,32)].clone() for k in ('observations','observation_preds','actions','rewards','dones')}),output/'first_rollout.pt')
            return original_update()
        alg.update=update
        def record(v):
            nonlocal completed
            completed=v['it']+1
            import math
            row=dict(iteration=completed,global_policy_steps=int(env.global_steps),samples=completed*n*24,
                collection_s=v['collection_time'],learning_s=v['learn_time'],elapsed_s=time.monotonic()-start,
                value_loss=float(v['mean_value_loss']),surrogate_loss=float(v['mean_surrogate_loss']),
                official_auxiliary_logged_loss=float(v['mean_adaptation_module_loss']),learning_rate=alg.learning_rate,
                action_std=float(model.std.mean()),force_coverage=dict(coverage),control_checks=dict(audit['checks']))
            assert all(math.isfinite(row[k]) for k in ('value_loss','surrogate_loss','official_auxiliary_logged_loss','action_std'))
            assert env.global_steps==initial_steps+24*completed+step_offset
            events=audit['events'];row['done_count']=sum(x['done_count'] for x in events)
            row['timeout_count']=sum(x['current_timeout_count'] for x in events)
            row['incorrect_bootstrap_abs_sum']=sum(x.get('incorrect_bootstrap_abs_sum',0.) for x in events)
            row['ee_error_mean_m']=sum(x['ee_error_mean_m'] for x in events)/len(events)
            row['root_height_world_m']=sum(x['root_z_mean'] for x in events)/len(events)
            row['mean_episode_reward']=sum(v['rewbuffer'])/len(v['rewbuffer']) if v['rewbuffer'] else None
            row['mean_episode_length']=sum(v['lenbuffer'])/len(v['lenbuffer']) if v['lenbuffer'] else None
            assert row['incorrect_bootstrap_abs_sum']==0 and audit['checks']['history_max_abs']<1e-5
            assert audit['checks']['non_noise_frame_max_abs']<1e-5
            assert audit['checks']['pd_equation_max_nm']<1e-5 and audit['checks']['goal_roundtrip_max_m']<1e-4
            if completed in plan['milestones'] or completed==args.ablation_iterations:
                assert all(torch.isfinite(t).all() for t in model.state_dict().values())
                steps={name:sorted({int(s['step']) for s in opt.state.values() if 'step' in s})
                    for name,opt in [('ppo',alg.optimizer),('auxiliary',alg.adaptation_module_optimizer)]}
                assert steps=={name:[20*completed+adam_offsets[name]] for name in ('ppo','auxiliary')},steps
                row['adam_steps']=steps
                row['module_change_l2']={prefix:float(sum((v-initial[k]).double().square().sum() for k,v in model.state_dict().items() if k.startswith(prefix)).sqrt())
                    for prefix in ('actor_body','critic_body','adaptation_encoder_module','adaptation_decoder_module')}
                assert all(x>0 for x in row['module_change_l2'].values())
                checkpoint=save_checkpoint(completed)
                row['checkpoint_sha256']=sha(checkpoint)
            with (output/'timings.jsonl').open('a') as f:f.write(json.dumps(row,allow_nan=False)+'\n')
            result.update(state='running',iteration=completed,global_policy_steps=int(env.global_steps),latest=row)
            write(output/'status.json',result)
            if completed==1 or completed%10==0:print('B2_FRESH_PROGRESS',args.ablation_seed,completed,json.dumps(row),flush=True)
            audit['events'].clear()
            # Frozen evaluation in another process cannot perturb training RNG/history/PhysX.
            if args.gym_b2_fresh_mode=='train' and completed in plan['evaluation_iterations']:
                for seed in plan['evaluation_seeds']:
                    for sample in (False,True):
                        for zero in ((True,) if env.global_steps<=env.cfg.commands.force_start_step*24 else (False,True)):
                            name=f'eval_i{completed:05d}_s{seed}_{"sample" if sample else "mean"}_{"zero" if zero else "force"}'
                            command=[sys.executable,str(root/'execution_snapshot.py'),'--gym_b2_fresh_worker',
                                '--gym_b2_fresh_mode=evaluate','--joint_root',str(root),'--probe_output',str(output/name),
                                '--gym_b2_fresh_envs=32','--ablation_seed',str(seed),'--replay_models_json',str(checkpoint)]
                            if sample:command+=['--gym_ranger_sample_actions']
                            if zero:command+=['--gym_zero_external_force']
                            with (output/(name+'.log')).open('w') as log:
                                subprocess.run(command,stdout=log,stderr=subprocess.STDOUT,check=True)
        class StageComplete(Exception):pass
        def gated_record(values):
            record(values)
            if plan.get('stage_gate_enabled') and completed in plan['evaluation_iterations']:
                if gym_b2_stage_gate(root,output,plan,result,env,completed,write):raise StageComplete()
        runner.log=gated_record
        try:runner.learn(num_learning_iterations=target_iteration-initial_iteration,init_at_random_ep_len=True)
        except StageComplete:runner.current_learning_iteration=completed
        assert completed==args.ablation_iterations or (output/f'stage_decision_{completed:06d}.json').exists()
        result.update(state='complete',iteration=completed,elapsed_s=time.monotonic()-start)
        write(output/'result.json',result);write(output/'status.json',result)
    except BaseException as error:
        result.update(state='failed',error=repr(error),traceback=traceback.format_exc())
        write(output/'status.json',result)
        if 'model' in locals() and args.gym_b2_fresh_mode!='evaluate':
            try:
                torch.save(dict(model_state_dict=model.state_dict(),optimizer_state_dict=alg.optimizer.state_dict(),
                    adaptation_optimizer_state_dict=alg.adaptation_module_optimizer.state_dict(),
                    last_completed_iteration=completed,global_policy_steps=int(env.global_steps),
                    not_a_completed_iteration_checkpoint=True,diagnostic_only=True),output/'interrupted_update.pt')
            except Exception:pass
        raise
    finally:
        if env is not None:env.gym.destroy_sim(env.sim)
        for rel,digest in plan['protected_sources_sha256'].items():assert sha(ROOT/rel)==digest,rel
        formal=plan['formal_ranger_checkpoint'];assert sha(formal['path'])==formal['sha256']


def gym_b2_stage_gate(root,output,plan,result,env,completed,write):
    """Hold live physics and history until a reviewed checkpoint decision arrives."""
    import time,hashlib
    checkpoint=output/f'model_iter_{completed:06d}.pt'
    digest=hashlib.sha256(checkpoint.read_bytes()).hexdigest()
    previous=output/'stage_transition.json'
    transition=json.loads(previous.read_text()) if previous.exists() else None
    force_iterations=completed-int(transition['entered_force_at']) if transition else 0
    evaluations=[]
    for path in sorted(output.glob(f'eval_i{completed:05d}_*/result.json')):
        item=json.loads(path.read_text())
        assert item['state']=='complete' and item['checkpoint_sha256']==digest
        evaluations.append(dict(path=str(path),action_mode=item['action_mode'],
            zero_external_force=item['zero_external_force'],ee_error_mean_m=item['ee_error_mean_m'],
            xy_velocity_rmse=item['xy_velocity_rmse'],yaw_velocity_rmse=item['yaw_velocity_rmse'],
            terminations=item['terminations'],timeout_count=item['timeout_count'],
            metrics=item['metrics'],zero_baseline=item['zero_baseline'],
            sustained_zero_estimate_norm_n=item['sustained_zero_estimate_norm_n']))
    assert len(evaluations)==(8 if transition else 4),len(evaluations)
    allowed=(['stop'] if force_iterations>=2000 or (not transition and completed>=8000) else ['stop','extend_force'] if transition else
        ['enter_force','continue_control','stop'])
    request=dict(state='awaiting_review',seed=result['seed'],iteration=completed,
        checkpoint=str(checkpoint),checkpoint_sha256=digest,force_training_iterations=force_iterations,
        evaluations=evaluations,training_history_and_simulation_preserved=True,allowed_actions=allowed)
    write(output/f'stage_review_{completed:06d}.json',request)
    result.update(state='awaiting_review',review=request);write(output/'status.json',result)
    print('B2_STAGE_AWAITING_REVIEW',result['seed'],completed,flush=True)
    decision_path=output/f'stage_decision_{completed:06d}.json'
    while not decision_path.exists():time.sleep(1)
    decision=json.loads(decision_path.read_text())
    assert decision['checkpoint_sha256']==digest and decision['iteration']==completed
    assert isinstance(decision.get('reason'),str) and decision['reason'].strip()
    action=decision['action'];assert action in allowed
    if action=='enter_force':
        assert not transition and completed<8000
        env.cfg.commands.force_start_step=completed
        write(previous,dict(entered_force_at=completed,maximum_force_iterations=2000,
            initial_force_iterations=1000,decision=decision))
    elif action=='extend_force':assert transition and force_iterations==1000
    elif action=='continue_control':assert not transition and completed<8000
    result.update(state='complete' if action=='stop' else 'running',last_stage_decision=decision,
        actual_force_start_iteration=int(env.cfg.commands.force_start_step))
    result.pop('review',None);write(output/'status.json',result)
    return action=='stop'


def gym_b2_uninterrupted_queue(args):
    """Serialize the authorized fixed-budget comparison using unchanged workers."""
    import os, time, signal, subprocess, hashlib, traceback, fcntl
    from datetime import datetime, timezone
    root=args.joint_root.resolve(); plan=json.loads((root/'plan.json').read_text())
    lock=(root/'coordinator.lock').open('a')
    fcntl.flock(lock,fcntl.LOCK_EX|fcntl.LOCK_NB)
    original=Path(plan['comparison_original_root'])
    resumed=Path(plan['comparison_resumed_root'])
    current=resumed/'train_seed260261'
    queue_identity=plan['existing_queue_identity']; worker_identity=plan['existing_worker_identity']
    child=None; held=False; checked_initial=False
    state=dict(pid=os.getpid(),diagnostic_only=True)
    def write(path,value):
        temp=path.with_suffix(path.suffix+'.tmp')
        temp.write_text(json.dumps(value,ensure_ascii=False,indent=2,allow_nan=False)+'\n')
        temp.replace(path)
    def status(phase,**values):
        state.update(state=phase,updated_utc=datetime.now(timezone.utc).isoformat(),**values)
        write(root/'coordinator_status.json',state)
    def alive(identity):
        try:
            text=Path('/proc/{}/stat'.format(identity['pid'])).read_text()
            fields=text[text.rfind(')')+2:].split()
            return fields[19]==identity['start_ticks'] and fields[0] not in ('Z','X')
        except FileNotFoundError:return False
    def decide(output,iteration,action,reason):
        request=json.loads((output/f'stage_review_{iteration:06d}.json').read_text())
        assert request['iteration']==iteration and request['force_training_iterations']==0
        digest=hashlib.sha256(Path(request['checkpoint']).read_bytes()).hexdigest()
        assert request['checkpoint_sha256']==digest and action in request['allowed_actions']
        assert len(request['evaluations'])==4
        results=[]
        for evaluation in request['evaluations']:
            path=Path(evaluation['path']); result=json.loads(path.read_text())
            assert result['state']=='complete' and result['checkpoint_sha256']==digest
            assert result['checkpoint_iteration']==iteration and result['zero_external_force']
            assert result['active_force_count']==0 and result['force_alignment_max_n']<1e-4
            assert all(value<1e-4 for value in result['control_checks'].values())
            assert (path.parent/'trace.pt').is_file()
            results.append(dict(result_path=str(path),trace_sha256=hashlib.sha256((path.parent/'trace.pt').read_bytes()).hexdigest(),
                action_mode=result['action_mode'],seed=result['seed'],ee_error_mean_m=result['ee_error_mean_m'],
                xy_velocity_rmse=result['xy_velocity_rmse'],yaw_velocity_rmse=result['yaw_velocity_rmse'],
                non_timeout_count=result['terminations']-result['timeout_count'],
                force_rmse_per_axis_n=result['metrics']['force_rmse_per_axis_n'],
                sustained_zero_estimate_norm_n=result['sustained_zero_estimate_norm_n']))
        decision=dict(action=action,iteration=iteration,checkpoint_sha256=digest,reason=reason,
            reviewed_at=datetime.now(timezone.utc).isoformat(),protocol_decision=True)
        path=output/f'stage_decision_{iteration:06d}.json'
        if path.exists():
            existing=json.loads(path.read_text())
            assert all(existing[key]==decision[key] for key in ('action','iteration','checkpoint_sha256'))
        else:write(path,decision)
        write(root/f'protocol_review_{output.parent.name}_{iteration:06d}.json',dict(decision=decision,evaluations=results))
    try:
        assert plan['iterations']==5000 and plan['training_seeds']==[260261]
        assert plan['evaluation_iterations']==[4000,5000] and not plan.get('resume_checkpoints')
        recovery_path=root/'coordinator_recovery.json'
        if recovery_path.exists():
            recovery=json.loads(recovery_path.read_text())
            assert alive(queue_identity) and alive(recovery['comparison_queue_identity'])
            assert json.loads((current/'status.json').read_text())['state']=='complete'
            decide(current,6000,'stop','恢复协调器时核验既有6000轮停止决策；不重新启动训练。')
            held=True
            class AttachedQueue:
                def __init__(self):
                    self.pid=recovery['comparison_queue_identity']['pid']; self.returncode=None
                def poll(self):
                    if alive(recovery['comparison_queue_identity']):return None
                    value=json.loads((root/'queue_status.json').read_text())
                    self.returncode=0 if value['state']=='complete' else 1
                    return self.returncode
            child=AttachedQueue()
            write(resumed/'serial_priority.json',dict(state='dispatcher_held_for_same_seed_comparison',
                coordinator_root=str(root),coordinator_pid=os.getpid(),training_process_not_suspended=True,
                current_training_finishes_at=6000,dispatcher_pid=queue_identity['pid']))
            status('comparison_running',comparison_queue_pid=child.pid,adopted_existing_queue=True,dispatcher_held=True)
        else:
            assert alive(queue_identity) and alive(worker_identity)
            for rel,digest in plan['protected_sources_sha256'].items():
                assert hashlib.sha256((ROOT/rel).read_bytes()).hexdigest()==digest,rel
            # Stop only the dispatcher waiting for its child, never the active learner.
            os.kill(queue_identity['pid'],signal.SIGSTOP); held=True
            write(resumed/'serial_priority.json',dict(state='dispatcher_held_for_same_seed_comparison',
                coordinator_root=str(root),coordinator_pid=os.getpid(),training_process_not_suspended=True,
                current_training_finishes_at=6000,dispatcher_pid=queue_identity['pid']))
            status('waiting_existing_6000',existing_worker_pid=worker_identity['pid'],dispatcher_held=True)
            while True:
                assert alive(queue_identity),'Existing dispatcher disappeared'
                value=json.loads((current/'status.json').read_text())
                if value['state']=='awaiting_review':
                    assert value['iteration']==6000,value['iteration']
                    decide(current,6000,'stop','按用户最新授权，优先补同种子从零连续5000轮对照。现有恢复分支完成已授权6000轮及四条验证后在完整边界停止，不进入受力；不是根据本边界成绩挑选终点。原队列第二种子待对照完成后继续。')
                    status('waiting_existing_exit');break
                assert value['state']!='failed',value.get('error')
                assert alive(worker_identity),'Existing worker exited before the6000 review'
                time.sleep(10)
            while alive(worker_identity):time.sleep(2)
            assert json.loads((current/'status.json').read_text())['state']=='complete'
            environment=os.environ.copy();environment.update(json.loads((root/'runtime_environment.json').read_text()))
            command=[sys.executable,str(root/'execution_snapshot.py'),'--gym_b2_fresh_queue','--joint_root',str(root)]
            with (root/'queue.log').open('x') as log:
                child=subprocess.Popen(command,cwd=ROOT,env=environment,stdout=log,stderr=subprocess.STDOUT,start_new_session=True)
            write(root/'queue_launch.json',dict(pid=child.pid,command=command,started_utc=datetime.now(timezone.utc).isoformat()))
            status('comparison_running',comparison_queue_pid=child.pid)
        output=root/'train_seed260261'
        while child.poll() is None:
            if not checked_initial and (output/'model_iter_000000.pt').exists():
                import torch
                torch.set_num_threads(1)
                source=torch.load(original/'train_seed260261/model_iter_000000.pt',map_location='cpu')
                candidate=torch.load(output/'model_iter_000000.pt',map_location='cpu')
                def equal_config(left,right):
                    import numpy as np
                    if isinstance(left,dict):
                        return isinstance(right,dict) and left.keys()==right.keys() and all(equal_config(left[k],right[k]) for k in left)
                    if isinstance(left,(list,tuple)):
                        return type(left) is type(right) and len(left)==len(right) and all(equal_config(a,b) for a,b in zip(left,right))
                    if isinstance(left,np.ndarray) or isinstance(right,np.ndarray):
                        return isinstance(left,np.ndarray) and isinstance(right,np.ndarray) and left.dtype==right.dtype and np.array_equal(left,right,equal_nan=True)
                    if isinstance(left,torch.Tensor) or isinstance(right,torch.Tensor):
                        return isinstance(left,torch.Tensor) and isinstance(right,torch.Tensor) and torch.equal(left,right)
                    return bool(left==right)
                checks=dict(initial_model_equal=all(torch.equal(value,candidate['model_state_dict'][key]) for key,value in source['model_state_dict'].items()),
                    config_equal=equal_config(source['config'],candidate['config']),
                    ppo_adam_empty=not candidate['optimizer_state_dict']['state'],
                    auxiliary_adam_empty=not candidate['adaptation_optimizer_state_dict']['state'],
                    initial_iteration_zero=candidate['iterations']==0,
                    initial_policy_steps_equal=source['global_policy_steps']==candidate['global_policy_steps'],
                    torch_rng_equal=torch.equal(source['torch_rng'],candidate['torch_rng']))
                write(root/'initialization_comparison.json',dict(checks=checks,all_passed=all(checks.values()),
                    source_checkpoint=str(original/'train_seed260261/model_iter_000000.pt'),
                    exact_physics_replay_not_guaranteed=True))
                assert all(checks.values()),checks
                checked_initial=True;del source,candidate
            if (output/'status.json').exists():
                value=json.loads((output/'status.json').read_text())
                if value['state']=='awaiting_review':
                    iteration=value['iteration'];assert iteration in (4000,5000)
                    action='continue_control' if iteration==4000 else 'stop'
                    decide(output,iteration,action,'预注册的暂停恢复对照：相同种子260261从随机权重和空Adam连续训练；4000只评不切受力，保留同一父PhysX/history与两Adam继续；5000完成评估即停止。决策由固定预算决定，不按成绩挑选节点，不额外续训。')
                    status('comparison_running',last_protocol_decision=iteration)
            time.sleep(10)
        assert child.returncode==0,child.returncode
        assert checked_initial,'Initialization comparison missing'
        value=json.loads((output/'result.json').read_text())
        assert value['state']=='complete' and value['iteration']==5000
        status('complete',comparison_iteration=5000)
    except BaseException as error:
        status('failed',error=repr(error),traceback=traceback.format_exc(),
            comparison_child_alive=bool(child is not None and child.poll() is None))
        raise
    finally:
        if held and alive(queue_identity) and (child is None or child.poll() is not None):
            os.kill(queue_identity['pid'],signal.SIGCONT)
            write(resumed/'serial_priority.json',dict(state='dispatcher_released',coordinator_root=str(root),
                coordinator_state=state['state'],dispatcher_pid=queue_identity['pid']))
            state['dispatcher_held']=False;write(root/'coordinator_status.json',state)


def gym_b2_fresh_queue(args):
    """Finite serial queue; no Ranger jobs and no parameter restoration."""
    import os,subprocess,time,traceback,hashlib,fcntl
    root=args.joint_root.resolve();plan=json.loads((root/'plan.json').read_text())
    lock=(root/'queue.lock').open('a')
    fcntl.flock(lock,fcntl.LOCK_EX|fcntl.LOCK_NB)
    recovery_path=getattr(args,'gym_b2_fresh_queue_recovery_manifest',None)
    skipped=[]
    if recovery_path:
        recovery=json.loads(recovery_path.read_text())
        assert Path(recovery['root']).resolve()==root
        for path,digest in recovery['bound_files_sha256'].items():
            assert hashlib.sha256(Path(path).read_bytes()).hexdigest()==digest,path
        skipped=recovery['artifact_complete_with_exit_error_seeds']
        assert skipped and skipped==plan['training_seeds'][:len(skipped)]
        for seed in skipped:
            output=root/f'train_seed{seed}'
            result=json.loads((output/'result.json').read_text())
            iteration=result['iteration'];suffix=f'{iteration:06d}'
            review=json.loads((output/f'stage_review_{suffix}.json').read_text())
            decision=json.loads((output/f'stage_decision_{suffix}.json').read_text())
            assert result['state']=='complete' and decision['action']=='stop'
            assert decision['iteration']==review['iteration']==iteration
            digest=hashlib.sha256((output/f'model_iter_{suffix}.pt').read_bytes()).hexdigest()
            assert digest==review['checkpoint_sha256']==decision['checkpoint_sha256']==result['latest']['checkpoint_sha256']
    pending=plan['training_seeds'][len(skipped):]
    for seed in pending:
        assert not (root/f'train_seed{seed}').exists(),f'Output exists: {seed}'
        assert not (root/f'train_seed{seed}.log').exists(),f'Log exists: {seed}'
    status=dict(state='running',pid=os.getpid(),completed_seeds=[],current_seed=None)
    if recovery_path:
        status.update(recovery_manifest=str(recovery_path.resolve()),
            artifact_complete_with_exit_error_seeds=skipped,
            prior_failure_preserved=True)
    def write():
        temp=root/'queue_status.tmp';temp.write_text(json.dumps(status,indent=2)+'\n');temp.replace(root/'queue_status.json')
    try:
        write()
        for seed in pending:
            status.update(current_seed=seed);write()
            command=[sys.executable,str(root/'execution_snapshot.py'),'--gym_b2_fresh_worker',
                '--gym_b2_fresh_mode=train','--joint_root',str(root),'--probe_output',str(root/f'train_seed{seed}'),
                '--gym_b2_fresh_envs',str(plan['training_envs']),'--ablation_seed',str(seed),
                '--ablation_iterations',str(plan['iterations'])]
            resume=plan.get('resume_checkpoints',{}).get(str(seed))
            if resume:command+=['--resume_checkpoint',resume['path']]
            with (root/f'train_seed{seed}.log').open('x') as log:
                process=subprocess.Popen(command,stdout=log,stderr=subprocess.STDOUT)
                status['worker_pid']=process.pid;write()
                code=process.wait()
            if code:raise RuntimeError(f'Training seed {seed} exited {code}')
            status['completed_seeds'].append(seed);write()
        status.update(state='complete',current_seed=None);write()
    except BaseException as error:
        status.update(state='failed',error=repr(error),traceback=traceback.format_exc());write();raise

